    ["Crisp portrait hit numbers"] = "Scharfe Trefferzahlen am Porträt",
    ["Renders the damage/heal numbers that flash on the Player/Pet portrait with a fixed, sharp font instead of Blizzard's blurry growing animation."] = "Stellt die Schadens-/Heilzahlen, die am Spieler-/Begleiter-Porträt aufblitzen, mit fester, scharfer Schrift dar statt mit Blizzards verschwommener Wachstumsanimation.",
    ["Hit number size"] = "Größe der Trefferzahlen",
    ["Font size of the portrait hit numbers (when 'Crisp' is on)."] = "Schriftgröße der Trefferzahlen am Porträt (wenn 'Scharf' aktiv ist).",
    ["Auto-select single gossip option"] = "Einzelne NPC-Dialogoption automatisch wählen",
    ["Skips NPC dialog windows that only have a single option. Hold SHIFT to temporarily bypass."] = "Überspringt NPC-Dialoge mit nur einer Option. SHIFT halten, um es kurzzeitig zu umgehen.",
    ["Faster auto-loot"] = "Schnelleres Auto-Looten",
    ["Loots all items at once when auto-loot applies, instead of one by one."] = "Lootet alle Gegenstände auf einmal statt nacheinander, wenn Auto-Loot greift.",
    ["Max camera zoom"] = "Maximaler Kamerazoom",
    ["Raises the maximum camera zoom-out distance far beyond the default."] = "Erhöht die maximale Kamera-Entfernung weit über den Standardwert hinaus.",

    -- UnitFrames
    ["Player & Target Frame"] = "Spieler- & Zielfenster",
    ["Elite dragon border for your player frame, plus real health, threat display and the rare-elite border for the target and focus frames."] = "Elite-Drachenrahmen für dein Spielerfenster, plus echte HP, Bedrohungsanzeige und Selten-Elite-Rahmen für Ziel- und Fokusfenster.",
    ["Target & Focus Frame"] = "Ziel- & Fokusfenster",
    ["|cffaaaaaaPuts the golden elite dragon (or the rare variants) around your player portrait — the look elite mobs have on the target frame.|r"] = "|cffaaaaaaLegt den goldenen Elite-Drachen (oder die Selten-Varianten) um dein Spielerporträt — der Look, den Elite-Mobs im Zielfenster haben.|r",
    ["Frame style"] = "Rahmen-Stil",
    ["Elite (golden dragon)"] = "Elite (goldener Drache)",
    ["Rare-Elite (silver dragon)"] = "Selten-Elite (silberner Drache)",
    ["Rare (silver)"] = "Selten (silber)",
    ["Off (default frame)"] = "Aus (Standard-Rahmen)",

    -- CooldownManager
    ["Cooldown Manager"] = "Cooldown-Manager",
    ["A row of icons that shows the cooldowns of spells and trinkets you choose — like the retail cooldown manager."] = "Eine Icon-Reihe, die die Cooldowns von selbst gewählten Zaubern und Schmuckstücken zeigt — wie der Cooldown-Manager in Retail.",
    ["Movable cooldown bars grouped however you like (procs, defensives, offensives ...) — like the retail cooldown manager."] = "Verschiebbare Cooldown-Leisten, gruppiert wie du willst (Procs, Defensiv, Offensiv …) — wie der Cooldown-Manager in Retail.",
    ["|cffaaaaaaMovable cooldown bars grouped however you like — e.g. one for procs/buffs, one for defensive cooldowns, one for offensives. Pick or create a group below, then add spells/trinkets to it.|r"] = "|cffaaaaaaVerschiebbare Cooldown-Leisten, gruppiert wie du willst — z. B. eine für Procs/Buffs, eine für Defensiv-Cooldowns, eine für Offensiv. Wähle oder erstelle unten eine Gruppe und füge ihr Zauber/Schmuckstücke hinzu.|r",
    ["Cooldowns"] = "Cooldowns",
    ["Groups"] = "Gruppen",
    ["Edit group"] = "Gruppe bearbeiten",
    ["New group"] = "Neue Gruppe",
    ["Group %d"] = "Gruppe %d",
    ["Delete group"] = "Gruppe löschen",
    ["|cff888888Nothing in this group yet.|r"] = "|cff888888Noch nichts in dieser Gruppe.|r",
    ["Cooldown group '%s' unlocked. Drag spells/items onto it; |cff9b6cffdrag|r to move."] = "Cooldown-Gruppe '%s' entsperrt. Zieh Zauber/Gegenstände drauf; |cff9b6cffziehen|r zum Verschieben.",
    ["Cooldown group '%s' locked."] = "Cooldown-Gruppe '%s' gesperrt.",
    ["Group type"] = "Gruppentyp",
    ["Buffs & Procs (only show while active)"] = "Buffs & Procs (nur sichtbar wenn aktiv)",
    ["|cffaaaaaaIcons appear only while their buff/proc is on you; the bar is empty otherwise. Add the BUFF (e.g. Clearcasting) by name or ID.|r"] = "|cffaaaaaaIcons erscheinen nur, solange ihr Buff/Proc auf dir aktiv ist; sonst ist die Leiste leer. Füge den BUFF (z. B. Gedankenblitz-Proc) per Name oder ID hinzu.|r",
    ["|cffaaaaaaIcons show the cooldown of each spell/trinket.|r"] = "|cffaaaaaaIcons zeigen den Cooldown jedes Zaubers/Schmuckstücks.|r",
    ["Size & offsets"] = "Größe & Versatz",
    ["Extra settings"] = "Mehr Einstellungen",

    -- FriendList
    ["Friends List"] = "Freundesliste",
    ["Class-coloured friend names, class icons, faction accent and optional auto-accept for Battle.net invites."] = "Freundesnamen in Klassenfarbe, Klassen-Icons, Fraktions-Akzent und optionales Auto-Annehmen von Battle.net-Anfragen.",
    -- Dialog popups
    ["Dialog Popups"] = "Dialogfenster",
    ["Restyles Blizzard's confirmation dialogs (logout countdown, delete item, resurrect, group invite) to match the dark look."] = "Gestaltet Blizzards Bestätigungsdialoge (Logout-Countdown, Gegenstand zerstören, Wiederbeleben, Gruppeneinladung) im dunklen Look.",
    ["|cffaaaaaaRestyles Blizzard's confirmation dialogs — logout countdown, delete item, resurrect, group invite — to match the dark look.|r"] = "|cffaaaaaaGestaltet Blizzards Bestätigungsdialoge – Logout-Countdown, Gegenstand zerstören, Wiederbeleben, Gruppeneinladung – im dunklen Look.|r",
    ["Accent strip"] = "Akzentstreifen",
    ["Draws a thin accent gradient along the top edge of each dialog."] = "Zeichnet einen dünnen Akzent-Verlauf an der Oberkante jedes Dialogs.",
    -- Addon skins
    ["Addon Skins"] = "Addon-Skins",
    ["Restyles supported third-party addon windows to match the dark look: error list, quest tracker, loot browser, profiler and more."] = "Gestaltet die Fenster unterstützter Fremd-Addons im dunklen Look: Fehlerliste, Quest-Tracker, Loot-Browser, Profiler und mehr.",
    ["|cffaaaaaaRestyles the windows of supported addons to the dark look. Skins apply when the addon is loaded; turning one off needs a /reload (the quest tracker restores live).|r"] = "|cffaaaaaaGestaltet die Fenster unterstützter Addons im dunklen Look. Skins greifen, sobald das Addon geladen ist; zum Abschalten eines Skins ist ein /reload nötig (der Quest-Tracker stellt sich live zurück).|r",
    ["not loaded"] = "nicht geladen",
    ["Map addon"] = "Karten-Addon",
    ["Dark window skin"] = "Dunkler Fenster-Skin",
    ["Restyles the whole friends window dark with purple accents. Turning it off needs a /reload to restore Blizzard's frame."] = "Gestaltet das gesamte Freundesfenster dunkel mit lila Akzenten. Zum Zurücksetzen auf Blizzards Original ist nach dem Ausschalten ein /reload nötig.",
    ["Class color names"] = "Namen in Klassenfarbe",
    ["Colors each online friend's name by their class."] = "Färbt den Namen jedes Online-Freundes nach seiner Klasse.",
    ["Show class icons"] = "Klassen-Icons anzeigen",
    ["Shows a class icon next to online WoW friends (in-game and Battle.net)."] = "Zeigt ein Klassen-Icon neben Online-WoW-Freunden (im Spiel und Battle.net).",
    ["Class icon style"] = "Klassen-Icon-Stil",
    ["Blizzard crests"] = "Blizzard-Wappen",
    ["Vulo Modern"] = "Vulo Modern",
    ["Vulo Style"] = "Vulo Style",
    ["Vulo icons"] = "Vulo-Icons",
    ["Circles"] = "Kreise",
    ["Squares"] = "Quadrate",
    ["Show status dot"] = "Status-Punkt anzeigen",
    ["A coloured dot after the name: green online, yellow away, red busy, grey offline."] = "Ein farbiger Punkt hinter dem Namen: grün online, gelb abwesend, rot beschäftigt, grau offline.",
    ["Show friend notes"] = "Freundes-Notizen anzeigen",
    ["Shows your saved note for the friend in grey under their name."] = "Zeigt deine gespeicherte Notiz zum Freund grau unter dem Namen.",
    ["Faction"] = "Fraktion",
    ["Faction accent on realm line"] = "Fraktions-Akzent in der Realm-Zeile",
    ["Tints the realm/zone line red (Horde) or blue (Alliance)."] = "Färbt die Realm-/Zonen-Zeile rot (Horde) oder blau (Allianz).",
    ["Faction row tint"] = "Fraktions-Zeilentönung",
    ["Adds a subtle red/blue background tint to each online friend's row."] = "Fügt jeder Online-Freundeszeile eine dezente rote/blaue Hintergrundtönung hinzu.",
    ["Invites"] = "Einladungen",
    ["Auto-accept Battle.net friend invites"] = "Battle.net-Freundschaftsanfragen automatisch annehmen",
    ["Automatically accepts incoming Battle.net friend requests."] = "Nimmt eingehende Battle.net-Freundschaftsanfragen automatisch an.",
    ["Auto-accept group invites from friends"] = "Gruppeneinladungen von Freunden automatisch annehmen",
    ["Automatically joins a group when the invite comes from someone on your friends list."] = "Tritt einer Gruppe automatisch bei, wenn die Einladung von jemandem auf deiner Freundesliste kommt.",
    ["Class-coloured names, class icons, status dots, inline notes, faction tint and optional auto-accept."] = "Namen in Klassenfarbe, Klassen-Icons, Status-Punkte, Inline-Notizen, Fraktionstönung und optionales Auto-Annehmen.",
    ["Highlight"] = "Hervorhebung",
    ["Proc glow (animated)"] = "Proc-Glow (animiert)",
    ["Glow"] = "Leuchten",
    ["Colored border"] = "Farbiger Rand",
    ["Highlight color"] = "Hervorhebungsfarbe",
    ["Yellow"] = "Gelb",
    ["Purple"] = "Violett",
    ["White"] = "Weiß",
    ["|cffaaaaaaA row of icons showing the cooldowns of the spells and trinkets you add. Type a spell/item name or ID below, shift-click a spell from your spellbook into the box, or unlock the bar and drag spells/items onto it.|r"] = "|cffaaaaaaEine Icon-Reihe mit den Cooldowns der von dir hinzugefügten Zauber und Schmuckstücke. Tippe unten einen Zauber-/Gegenstandsnamen oder eine ID ein, shift-klicke einen Zauber aus dem Zauberbuch ins Feld, oder entsperre die Leiste und zieh Zauber/Gegenstände darauf.|r",
    ["Cooldown Manager: '%s' is not a known spell or item."] = "Cooldown-Manager: '%s' ist kein bekannter Zauber oder Gegenstand.",
    ["Cooldown Manager: already tracking that."] = "Cooldown-Manager: wird bereits verfolgt.",
    ["Cooldown Manager: added %s."] = "Cooldown-Manager: %s hinzugefügt.",
    ["Bar scale"] = "Leisten-Skalierung",
    ["Icon border thickness"] = "Icon-Rahmenstärke",
    ["Class-colored border"] = "Rahmen in Klassenfarbe",
    ["Border color..."] = "Rahmenfarbe...",
    ["Bar background"] = "Leisten-Hintergrund",
    ["Background color..."] = "Hintergrundfarbe...",
    ["Show this bar"] = "Diese Leiste anzeigen",
    ["Only in a party (not raid)"] = "Nur in einer Gruppe (kein Schlachtzug)",
    ["Only in a raid"] = "Nur im Schlachtzug",
    ["Only while solo"] = "Nur alleine",
    ["Never (temporarily off)"] = "Nie (vorübergehend aus)",
    ["Countdown text size"] = "Countdown-Textgröße",
    ["Percent of the icon size."] = "In Prozent der Icon-Größe.",
    ["Countdown text color..."] = "Countdown-Textfarbe...",
    ["Warn color under (sec)"] = "Warnfarbe unter (Sek.)",
    ["Below this many seconds the countdown switches to the warn color; 0 turns the warn color off."] = "Unter dieser Restzeit wechselt der Countdown zur Warnfarbe; 0 schaltet die Warnfarbe ab.",
    ["Warn color..."] = "Warnfarbe...",
    ["Glow while ready"] = "Leuchten wenn bereit",
    ["A steady glow while the cooldown is ready - and, for spells, only while it is actually usable (enough mana etc.)."] = "Dauerhaftes Leuchten, solange der Cooldown bereit ist – bei Zaubern nur, wenn er auch nutzbar ist (genug Mana usw.).",
    ["Glow color"] = "Leuchtfarbe",
    ["Show keybinds"] = "Tastenbelegung anzeigen",
    ["Shows the key the spell/item is bound to on your action bars. Macros are not matched; stance pages follow the main bar."] = "Zeigt die Taste, auf der der Zauber/Gegenstand in deinen Aktionsleisten liegt. Makros werden nicht erkannt; Haltungs-Seiten folgen der Hauptleiste.",
    ["Keybind color..."] = "Tastenfarbe...",
    ["Keep inactive buffs visible (greyed out)"] = "Inaktive Stärkungszauber ausgegraut anzeigen",
    ["Icons stay in place when the buff runs out, just desaturated - the bar never jumps around."] = "Icons bleiben beim Auslaufen des Stärkungszaubers an ihrem Platz, nur entsättigt – die Leiste springt nie.",
    ["Add (name / ID)"] = "Hinzufügen (Name / ID)",
    ["Tracked"] = "Verfolgt",
    ["|cff888888Nothing tracked yet.|r"] = "|cff888888Noch nichts verfolgt.|r",
    ["  |cff888888(item)|r"] = "  |cff888888(Gegenstand)|r",
    ["Up"] = "Hoch",
    ["Icons per row"] = "Icons pro Reihe",
    ["Growth direction"] = "Wachstumsrichtung",
    ["Right"] = "Rechts",
    ["Left"] = "Links",
    ["Down"] = "Runter",
    ["Up (direction)"] = "Hoch",
    ["Only show while on cooldown"] = "Nur während Cooldown anzeigen",
    ["Hides ready icons; they reappear when on cooldown."] = "Versteckt bereite Icons; sie erscheinen wieder, sobald sie auf Cooldown sind.",
    ["Show countdown text"] = "Countdown-Text anzeigen",
    ["Show stacks"] = "Stapel anzeigen",
    ["  |cffaa5555(other class)|r"] = "  |cffaa5555(andere Klasse)|r",
    ["Unlock Mode"] = "Bearbeiten-Modus",
    ["|cffaaaaaaFor Blizzard's own Edit Mode: open it yourself via the game menu (|cffffffffEsc → Edit Mode|r). Blizzard blocks addons from starting it. Once it's open, your VuloUI windows appear in it automatically.|r"] = "|cffaaaaaaFür Blizzards eigenen Bearbeitungsmodus: öffne ihn selbst über das Spielmenü (|cffffffffEsc → Bearbeitungsmodus|r). Blizzard verhindert, dass Addons ihn starten. Sobald er offen ist, erscheinen deine VuloUI-Fenster automatisch darin.|r",
    ["Open Blizzard's Edit Mode"] = "Blizzards Bearbeitungsmodus öffnen",
    ["Open game menu for Blizzard's Edit Mode"] = "Spielmenü für Blizzards Bearbeitungsmodus öffnen",
    ["Blizzard blocks addons from starting Edit Mode directly (it would taint). This opens the game menu — pick 'Edit Mode' there. Our windows then appear in it automatically."] = "Blizzard verhindert, dass Addons den Bearbeitungsmodus direkt starten (würde Taint verursachen). Das öffnet das Spielmenü – dort „Bearbeitungsmodus“ wählen. Unsere Fenster erscheinen dann automatisch darin.",
    ["Opens Blizzard's own Edit Mode (closes this window first). Our windows show up in it too."] = "Öffnet Blizzards eigenen Bearbeitungsmodus (schließt vorher dieses Fenster). Unsere Fenster erscheinen darin ebenfalls.",
    ["Can't open Edit Mode in combat."] = "Bearbeitungsmodus kann im Kampf nicht geöffnet werden.",
    ["This client has no Blizzard Edit Mode."] = "Dieser Client hat keinen Blizzard-Bearbeitungsmodus.",
    ["Activate edit mode to move every VuloUI window at once."] = "Bearbeiten-Modus aktivieren, um alle VuloUI-Fenster auf einmal zu verschieben.",
    ["|cffaaaaaaActivate edit mode to move every VuloUI window at once — cooldown bars, combat text, trackers, castbar, swing timer and more. It also opens automatically with Blizzard's Edit Mode.|r"] = "|cffaaaaaaBearbeiten-Modus aktivieren, um alle VuloUI-Fenster auf einmal zu verschieben — Cooldown-Leisten, Combat-Text, Tracker, Castbar, Swing-Timer und mehr. Öffnet auch automatisch mit Blizzards Bearbeitungsmodus.|r",
    ["|cff888888• Drag a purple box to move that window.|n• Hover a box, then use the arrow keys to fine-tune (SHIFT = 5px).|n• Right-click a box for exact X / Y.|n• |cffffffff/cdedit|r toggles this too.|r"] = "|cff888888• Ein lila Kästchen ziehen, um das Fenster zu verschieben.|n• Über ein Kästchen fahren, dann Pfeiltasten zum Feinjustieren (SHIFT = 5px).|n• Rechtsklick auf ein Kästchen für genaue X / Y.|n• |cffffffff/cdedit|r schaltet das ebenfalls um.|r",
    ["|cff44ff44Edit mode is ON.|r Close this window to reach the boxes, then lock again here or with /cdedit."] = "|cff44ff44Bearbeiten-Modus ist AN.|r Schließe dieses Fenster, um an die Kästchen zu kommen, dann hier oder mit /cdedit wieder sperren.",
    ["Edit mode — move the cooldown bars"] = "Bearbeiten — Cooldown-Leisten verschieben",
    ["Stop editing — lock the cooldown bars"] = "Bearbeiten beenden — Cooldown-Leisten sperren",
    ["Unlocks just the cooldown bars so you can drag them. Arrow keys fine-tune; right-click a purple box for X/Y. (To move ALL VuloUI windows, use 'Unlock Mode' in Global.)"] = "Entsperrt nur die Cooldown-Leisten zum Ziehen. Pfeiltasten justieren fein; Rechtsklick auf ein lila Kästchen für X/Y. (Um ALLE VuloUI-Fenster zu verschieben, nutze „Bearbeiten-Modus“ in Global.)",
    ["Edit mode — move all VuloUI windows"] = "Bearbeiten — alle VuloUI-Fenster verschieben",
    ["Stop editing — lock all windows"] = "Bearbeiten beenden — alle Fenster sperren",
    ["Unlocks every movable VuloUI window at once (cooldown bars, combat text, trackers …) so you can drag them. Arrow keys fine-tune; right-click a purple box for X/Y. Also opens with Blizzard's Edit Mode."] = "Entsperrt alle verschiebbaren VuloUI-Fenster gleichzeitig (Cooldown-Leisten, Combat-Text, Tracker …) zum Ziehen. Pfeiltasten justieren fein; Rechtsklick auf ein lila Kästchen für X/Y. Öffnet auch mit Blizzards Bearbeitungsmodus.",
    ["right-click: settings"] = "Rechtsklick: Einstellungen",
    ["Edit mode — unlock all bars to move"] = "Bearbeiten — alle Leisten zum Verschieben entsperren",
    ["Stop editing — lock all bars"] = "Bearbeiten beenden — alle Leisten sperren",
    ["Unlocks every cooldown bar at once so you can drag them all into place. Also opens automatically with Blizzard's Edit Mode. Anchoring is set per group in 'Anchor'."] = "Entsperrt alle Cooldown-Leisten gleichzeitig, damit du sie alle platzieren kannst. Öffnet sich auch automatisch mit Blizzards Bearbeitungsmodus. Ankern stellst du pro Gruppe unter „Verankerung“ ein.",
    ["Cooldown edit mode |cff44ff44ON|r — drag any bar to move it. Toggle again to lock."] = "Cooldown-Bearbeiten |cff44ff44AN|r — zieh eine Leiste zum Verschieben. Nochmal umschalten zum Sperren.",
    ["Cooldown edit mode |cffff5555OFF|r — all bars locked."] = "Cooldown-Bearbeiten |cffff5555AUS|r — alle Leisten gesperrt.",
    ["Hide cooldowns under (sec)"] = "Cooldowns ausblenden unter (Sek.)",
    ["Cooldowns at or below this are ignored. 1.5 hides the global cooldown; raise it to also hide short cooldowns; 0 shows everything."] = "Cooldowns bis zu diesem Wert werden ignoriert. 1,5 blendet den globalen Cooldown aus; höher stellen blendet auch kurze Cooldowns aus; 0 zeigt alles.",
    ["Reorder / remove"] = "Sortieren / entfernen",
    ["Move earlier"] = "Nach vorne",
    ["Move later"] = "Nach hinten",
    ["Stack / reagent position"] = "Stapel-/Reagenz-Position",
    ["Stack / reagent size"] = "Stapel-/Reagenz-Größe",
    ["Stack / reagent color..."] = "Stapel-/Reagenz-Farbe...",
    ["Bottom right"] = "Unten rechts",
    ["Bottom left"] = "Unten links",
    ["Top right"] = "Oben rechts",
    ["Top left"] = "Oben links",
    ["Show reagent counts"] = "Reagenz-Anzahl anzeigen",
    ["Shows each spell's OWN reagent count — Soul Shards on Soul Fire, Infernal Stone on Inferno, etc. Spells without a reagent show nothing. Needs 'Show stacks' on."] = "Zeigt für jeden Zauber sein EIGENES Reagenz – Seelensplitter auf Seelenfeuer, Höllenstein auf Inferno usw. Zauber ohne Reagenz zeigen nichts. Benötigt aktives „Stapel anzeigen“.",
    ["Anchor"] = "Verankerung",
    ["Anchor to"] = "Ankern an",
    ["Pin this bar to a unit frame, the minimap, or another group's bar — it then moves with it. Drag the bar to detach."] = "Heftet diese Leiste an ein Einheitenfenster, die Minimap oder die Leiste einer anderen Gruppe – sie bewegt sich dann mit. Zum Lösen die Leiste ziehen.",
    ["Player Frame"] = "Spielerfenster",
    ["Focus Frame"] = "Fokusfenster",
    ["Pet Frame"] = "Begleiterfenster",
    ["None (free)"] = "Keine (frei)",
    ["Cooldown Manager: can't anchor there — it would loop."] = "Cooldown Manager: Ankern dort nicht möglich – das würde eine Schleife ergeben.",
    ["Side"] = "Seite",
    ["Below"] = "Unten",
    ["Above"] = "Oben",
    ["Left of"] = "Links",
    ["Right of"] = "Rechts",
    ["X offset"] = "X-Versatz",
    ["Y offset"] = "Y-Versatz",
    ["Icon shape"] = "Icon-Form",
    ["Square"] = "Eckig",
    ["Rounded"] = "Abgerundet",
    ["Icon zoom"] = "Icon-Zoom",
    ["Cooldown swipe darkness"] = "Cooldown-Wisch-Dunkelheit",
    ["Only in combat"] = "Nur im Kampf",
    ["Only with a target"] = "Nur mit Ziel",
    ["Only with an attackable target"] = "Nur mit angreifbarem Ziel",
    ["Hide while mounted"] = "Ausblenden wenn beritten",
    ["Only in instances"] = "Nur in Instanzen",
    ["Dim icon while on cooldown"] = "Icon während Cooldown abdunkeln",
    ["Flash when ready"] = "Aufleuchten wenn bereit",
    ["|cffffffffCOOLDOWNS|r"] = "|cffffffffCOOLDOWNS|r",
    ["Cooldowns: x=%.0f, y=%.0f"] = "Cooldowns: x=%.0f, y=%.0f",
    ["Cooldown Manager unlocked. Drag spells/items onto the bar to add. |cff9b6cffDrag|r the bar to move."] = "Cooldown-Manager entsperrt. Zieh Zauber/Gegenstände auf die Leiste zum Hinzufügen. |cff9b6cffZiehen|r zum Verschieben.",
    ["Cooldown Manager locked."] = "Cooldown-Manager gesperrt.",

    -- Bar Setups
    ["Bar Setups"] = "Leisten-Belegungen",
    ["Saves named snapshots of your action bars, macros and keybindings, and restores them with one click."] = "Speichert benannte Schnappschüsse deiner Aktionsleisten, Makros und Tastenbelegungen und stellt sie mit einem Klick wieder her.",
    ["|cffaaaaaaSaves your complete bar setup (all action slots, macros, keybindings) as a named profile and restores it with one click — e.g. PvP and Raid layouts, or to copy a setup to a twink (account-wide storage).|r"] = "|cffaaaaaaSpeichert dein komplettes Leisten-Setup (alle Aktionsslots, Makros, Tastenbelegungen) als benanntes Profil und stellt es mit einem Klick wieder her — z. B. PvP- und Raid-Layout, oder um ein Setup auf einen Twink zu übertragen (accountweite Speicherung).|r",
    ["Load"] = "Laden",
    ["Save current setup"] = "Aktuelles Setup speichern",
    ["Please enter a profile name first."] = "Bitte zuerst einen Profilnamen eingeben.",
    ["|cff888888No profiles saved yet.|r"] = "|cff888888Noch keine Profile gespeichert.|r",
    ["Also restore macros"] = "Auch Makros wiederherstellen",
    ["Rewrites saved macros by name (existing ones are updated, missing ones created)."] = "Schreibt gespeicherte Makros per Name zurück (vorhandene werden aktualisiert, fehlende neu erstellt).",
    ["Also restore keybindings"] = "Auch Tastenbelegungen wiederherstellen",
    ["Load profile"] = "Profil laden",
    ["Overwrite with current setup"] = "Mit aktuellem Setup überschreiben",
    ["Replaces the selected profile with your current bars/macros/bindings."] = "Ersetzt das gewählte Profil durch deine aktuellen Leisten/Makros/Tasten.",
    ["Bar setup '%s' saved."] = "Leisten-Belegung '%s' gespeichert.",
    ["Bar setup '%s' deleted."] = "Leisten-Belegung '%s' gelöscht.",
    ["Not in combat — bars can't be changed while fighting."] = "Nicht im Kampf — Leisten lassen sich im Kampf nicht ändern.",
    ["Note: profile '%s' was saved on another class (%s)."] = "Hinweis: Profil '%s' wurde auf einer anderen Klasse gespeichert (%s).",
    ["Bar setup '%s' loaded: %d slots set, %d cleared, |cffff8800%d skipped|r (unknown spell / missing item or macro)."] = "Leisten-Belegung '%s' geladen: %d Plätze gesetzt, %d geleert, |cffff8800%d übersprungen|r (unbekannter Zauber / fehlender Gegenstand oder Makro).",
    ["Bar setup '%s' loaded: %d slots set, %d cleared."] = "Leisten-Belegung '%s' geladen: %d Plätze gesetzt, %d geleert.",

    -- FlightTimer
    ["Flight Timer"] = "Flugzeit",
    ["|cffff8800Flight route database not loaded.|r Fully restart WoW (a /reload is not enough after an update) so the flight times work."] = "|cffff8800Flugrouten-Datenbank nicht geladen.|r Starte WoW komplett neu (ein /reload reicht nach einem Update nicht), damit die Flugzeiten funktionieren.",
    ["Show flight time bar"] = "Flugzeitbalken anzeigen",
    ["Shows destination and remaining time while on a taxi. The first flight of a route is learned, then you get a draining countdown."] = "Zeigt Ziel und Restzeit während des Taxi-Flugs. Der erste Flug einer Route wird gelernt, danach gibt es einen ablaufenden Countdown.",
    ["Shows a progress bar with the duration of taxi flights. Unknown routes are learned on the first flight."] = "Zeigt eine Fortschrittsleiste mit der Dauer von Flugrouten. Unbekannte Routen werden beim ersten Flug gelernt.",
    ["|cffaaaaaaShows a bar with destination and remaining time while on a taxi. The first flight of a route counts up and is saved; from then on you get a countdown.|r"] = "|cffaaaaaaZeigt während des Flugs eine Leiste mit Ziel und Restzeit. Der erste Flug einer Route zählt hoch und wird gespeichert; danach gibt es einen Countdown.|r",
    ["(learning)"] = "(lernt)",
    ["Flight: %s (%s)"] = "Flug: %s (%s)",
    ["Print flight time to chat"] = "Flugzeit im Chat ausgeben",
    ["After landing, prints the measured flight time."] = "Gibt nach der Landung die gemessene Flugzeit aus.",
    ["Reset learned times"] = "Gelernte Zeiten zurücksetzen",
    ["Deletes all saved route durations."] = "Löscht alle gespeicherten Routen-Zeiten.",
    ["Learned flight times reset."] = "Gelernte Flugzeiten zurückgesetzt.",
    ["|cffaaaaaaLearned routes: %d|r"] = "|cffaaaaaaGelernte Routen: %d|r",
    ["|cffffffffFLIGHT TIME|r"] = "|cffffffffFLUGZEIT|r",
    ["Flight timer: x=%.0f, y=%.0f"] = "Flugzeit: x=%.0f, y=%.0f",
    ["Flight timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Flugzeit-Mover aktiv. |cff9b6cffZiehen|r oder |cff9b6cffPfeiltasten|r (SHIFT = 5px).",
    ["Flight timer mover disabled."] = "Flugzeit-Mover deaktiviert.",
    ["Flight debug on — take a flight, the resolution appears in the chat."] = "Flugdebug an — nimm einen Flug, dann steht die Auflösung im Chat.",
    ["Flight debug off."] = "Flugdebug aus.",

    -- LazyVulo
    ["LazyVulo"] = "Apexis-Minispiel",
    ["VulTraining"] = "Trainer",
    ["Group Board"] = "Gruppensuche",
    ["Apexis Relic memory minigame helper (Ogri'la dailies): record the flashing color sequence, always see what to click next."] = "Helfer für das Apexis-Relikt-Memory-Minispiel (Ogri'la-Dailies): Zeichne die Farbsequenz auf und sieh immer, was als Nächstes zu klicken ist.",
    ["Green relic"] = "Grünes Relikt",
    ["Yellow relic"] = "Gelbes Relikt",
    ["Blue relic"] = "Blaues Relikt",
    ["Red relic"] = "Rotes Relikt",
    ["Left click: remove this entry.\nRight click: remove this and all later entries."] = "Linksklick: diesen Eintrag entfernen.\nRechtsklick: diesen und alle späteren Einträge entfernen.",
    ["Click to record this color."] = "Klicken, um diese Farbe aufzuzeichnen.",
    ["Hotkey: %s"] = "Hotkey: %s",
    ["LazyVulo is disabled."] = "LazyVulo ist deaktiviert.",
    ["|cffaaaaaaHelper for the Apexis Relic memory minigame (Ogri'la dailies). Record the flashing sequence with the buttons or hotkeys; the first icon is always your next click. Correct clicks are consumed automatically, wrong clicks are restored.|r"] = "|cffaaaaaaHelfer für das Apexis-Relikt-Memory-Minispiel (Ogri'la-Dailies). Zeichne die Blink-Sequenz mit den Buttons oder Hotkeys auf; das erste Icon ist immer dein nächster Klick. Richtige Klicks werden automatisch verbraucht, falsche wiederhergestellt.|r",
    ["|cffaaaaaaOpen manually with /lazyvulo or /lv.|r"] = "|cffaaaaaaManuell öffnen mit /lazyvulo oder /lv.|r",
    ["Auto-show at the Apexis Relic"] = "Am Apexis-Relikt automatisch öffnen",
    ["Opens the window automatically when you start the relic minigame."] = "Öffnet das Fenster automatisch, wenn du das Relikt-Minispiel startest.",
    ["Enable hotkeys while the window is shown"] = "Hotkeys aktivieren, solange das Fenster offen ist",
    ["Disable hotkeys while in combat"] = "Hotkeys im Kampf deaktivieren",
    ["Hands the keys back to your action bars while you are in combat."] = "Gibt die Tasten im Kampf an deine Aktionsleisten zurück.",
    ["Show help tooltips"] = "Hilfe-Tooltips anzeigen",
    ["Window scale"] = "Fenster-Skalierung",
    ["Hotkeys"] = "Hotkeys",
    ["|cffaaaaaaOne key per color (e.g. G, Y, B, R or NUMPAD1). Empty = no hotkey.|r"] = "|cffaaaaaaEine Taste pro Farbe (z. B. G, Y, B, R oder NUMPAD1). Leer = kein Hotkey.|r",
    ["Show window"] = "Fenster anzeigen",

