    ["Auto-declines party/raid invites from players who are not in your guild or on your friends list."] = "Lehnt Gruppen-/Schlachtzug-Einladungen von Spielern automatisch ab, die nicht in deiner Gilde oder auf deiner Freundesliste sind.",
    ["Block trades from strangers"] = "Handel von Fremden blocken",
    ["Auto-closes trade windows opened by players who are not in your guild or on your friends list. Trades you start yourself are not affected."] = "Schließt Handelsfenster automatisch, die von Spielern geöffnet werden, die nicht in deiner Gilde oder auf deiner Freundesliste sind. Selbst gestartete Trades sind nicht betroffen.",
    ["|cffffd200[QoL]|r Blocked group invite from %s (not guild/friend)."] = "|cffffd200[QoL]|r Gruppen-Einladung von %s geblockt (nicht Gilde/Freund).",
    ["|cffffd200[QoL]|r Blocked trade from %s (not guild/friend)."] = "|cffffd200[QoL]|r Handel von %s geblockt (nicht Gilde/Freund).",

    -- VulTraining
    ["Adds a tab to your spell book that lists the abilities you can still learn from your class trainer, grouped by level. Open the book icon below the spell schools."] = "Fügt deinem Zauberbuch einen Tab hinzu, der die noch beim Klassenlehrer lernbaren Fähigkeiten auflistet, nach Stufe gruppiert. Öffne das Buch-Symbol unter den Zauberschulen.",
    ["|cffaaaaaaAdds a tab to your spell book (the book icon on the side, below the spell schools) listing every ability you can still learn from your class trainer — grouped by status and coloured by level. No need to visit a trainer.|r"] = "|cffaaaaaaFügt deinem Zauberbuch einen Tab hinzu (das Buch-Symbol an der Seite, unter den Zauberschulen), der alle noch beim Klassenlehrer lernbaren Fähigkeiten auflistet — nach Status gruppiert und nach Stufe gefärbt. Kein Lehrerbesuch nötig.|r",
    ["Available now"] = "Jetzt verfügbar",
    ["Available but Missing Requirements"] = "Verfügbar, aber fehlende Anforderungen",
    ["Upcoming"] = "Demnächst",
    ["Not Yet Available"] = "Noch nicht verfügbar",
    ["Missing Required Talents"] = "Fehlende Talente",
    ["Already Known"] = "Bereits bekannt",
    ["Level %d"] = "Stufe %d",
    ["Cost: %s"] = "Kosten: %s",
    ["What can I train?"] = "Was kann ich lernen?",
    ["No results found"] = "Keine Ergebnisse gefunden",
    ["|cffffffffPOWER BAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffRESSOURCENLEISTE|r\n|cffaaaaaaZiehen oder Pfeiltasten|r",
    ["Power Bar mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Move' again to finish."] = "Ressourcenleiste-Mover aktiv. |cff9b6cffZiehe das lila Kästchen|r oder nutze die |cff9b6cffPfeiltasten|r (SHIFT = 5px). Klicke erneut auf 'Entsperren / Bewegen' zum Beenden.",
    ["Power Bar mover disabled."] = "Ressourcenleiste-Mover deaktiviert.",
    ["|cffaaaaaaResource bar that follows your class automatically (Mana / Rage / Energy). Druids switch with their form: Bear = Rage, Cat = Energy, otherwise Mana.|r"] = "|cffaaaaaaRessourcenleiste, die automatisch deiner Klasse folgt (Mana / Wut / Energie). Druiden wechseln mit der Form: Bär = Wut, Katze = Energie, sonst Mana.|r",
    ["|cffaaaaaaThe bar colour follows your current power type automatically (Mana = blue, Rage = red, Energy = yellow).|r"] = "|cffaaaaaaDie Leistenfarbe folgt automatisch deinem aktuellen Energietyp (Mana = blau, Wut = rot, Energie = gelb).|r",

