    ["Alone"] = "Allein",
    ["Applies only in this situation. Combined with a talent group, both have to be true - and that group then overrides one that names only the talent group."] = "Gilt nur in dieser Situation. Zusammen mit einer Talentwahl müssen beide zutreffen — und diese Gruppe übersteuert dann eine, die nur die Talentwahl nennt.",
    ["Icon"] = "Symbol",
    ["No icon"] = "Kein Symbol",
    ["Shown in front of the group name in the menu and on the header button."] = "Erscheint im Menü vor dem Gruppennamen und im Kurztipp des Kopfknopfes.",
    ["Switch off to drop this one override. The setting then follows the profile again."] = "Ausschalten entfernt genau diese Übersteuerung. Die Einstellung folgt danach wieder dem Profil.",
