    ["Max Camera Distance"] = "Max. Kameradistanz",
    ["Maximum camera distance (CVar cameraDistanceMaxZoomFactor)."] = "Maximale Kameradistanz (CVar cameraDistanceMaxZoomFactor).",
    ["Show Minimap Button"] = "Minimap-Button anzeigen",
    ["Toggle the VuloClassicUI button on the minimap."] = "Schaltet den VuloClassicUI-Button auf der Minimap um.",
    ["Performance Display"] = "Leistungsanzeige",
    ["Show CPU Usage in Header"] = "CPU-Auslastung im Header anzeigen",
    ["Shows total CPU usage of all active addons (plus VuloClassicUI's own share) at the top of the config header.\n\n|cffaaaaaaRequires /reload after toggling.\n\nNote: Enables WoW's scriptProfile CVar, which costs ~3-5% performance — that's the price for WoW collecting this data at all.|r"] = "Zeigt die gesamte CPU-Auslastung aller aktiven Addons (plus VuloClassicUIs eigenen Anteil) oben im Konfigurations-Header.\n\n|cffaaaaaaErfordert /reload nach dem Umschalten.\n\nHinweis: Aktiviert WoWs scriptProfile-CVar, was ~3-5% Performance kostet — der Preis dafür, dass WoW diese Daten überhaupt sammelt.|r",
    ["Script profiling changed. /reload required for the CPU display to update."] = "Script-Profiling geändert. /reload erforderlich, damit die CPU-Anzeige aktualisiert wird.",
    ["Reload now"] = "Jetzt neu laden",
    ["Later"] = "Später",

    -- Minimap
    ["Shows a button on the minimap to quickly open VuloClassicUI. Shift+drag moves the button."] = "Zeigt einen Button auf der Minimap, um VuloClassicUI schnell zu öffnen. Shift+Ziehen verschiebt den Button.",
    ["UI is not loaded yet."] = "UI ist noch nicht geladen.",
    ["|cffffffffLeft click:|r Open options"] = "|cffffffffLinksklick:|r Optionen öffnen",
    ["|cffffffffRight click:|r Quick module selection"] = "|cffffffffRechtsklick:|r Schnelle Modulauswahl",
    ["|cffffffffShift+drag:|r Move button"] = "|cffffffffShift+Ziehen:|r Button verschieben",
    ["Open Options"] = "Optionen öffnen",
    ["Show button on minimap"] = "Button auf Minimap anzeigen",
    ["If off, the button is completely hidden."] = "Wenn aus, wird der Button komplett ausgeblendet.",
    ["Distance from center"] = "Abstand zum Zentrum",
    ["Angle (degrees)"] = "Winkel (Grad)",
    ["Tip: You can also move the button directly on the minimap — hold Shift and drag it to the desired position."] = "Tipp: Du kannst den Button auch direkt auf der Minimap verschieben — halte Shift gedrückt und ziehe ihn an die gewünschte Position.",

    -- FontBars
    ["Font Bars"] = "Font-Bars",
    ["Smaller font sizes for Player/Target/Pet Health & Mana bars, optionally hide TargetFrameBackground."] = "Kleinere Schriftgrößen für Lebens- und Mana-Balken von Spieler/Ziel/Begleiter, optional TargetFrameBackground ausblenden.",
    ["Health Bar Text"] = "Lebensbalken-Text",
    ["Font size on health bars (Player/Target/Pet)."] = "Schriftgröße auf Lebensbalken (Spieler/Ziel/Begleiter).",
    ["Power Bar Text"] = "Powerbalken-Text",
    ["Font size on mana/power bars."] = "Schriftgröße auf Mana-/Powerbalken.",
    ["Pet Combat Feedback Text"] = "Pet-Kampfmeldungstext",
    ["Font size for 'Damage', 'Dodge', 'Miss' on the pet."] = "Schriftgröße für 'Schaden', 'Ausweichen', 'Verfehlt' auf dem Begleiter.",
    ["Only affect Player/Target/Pet bars"] = "Nur Spieler-/Ziel-/Pet-Balken betreffen",
    ["If off: all TextStatusBars in the UI are overridden with the sizes above (may interfere with other addons)."] = "Wenn aus: alle TextStatusBars im UI werden mit den obigen Größen überschrieben (kann andere Addons stören).",
    ["Hide TargetFrame background"] = "TargetFrame-Hintergrund ausblenden",
    ["Permanently hides the dark background element of the TargetFrame."] = "Blendet das dunkle Hintergrundelement des TargetFrames dauerhaft aus.",

    -- Target Frame module
    ["Target Frame"] = "Zielfenster",
    ["|cffaaaaaaAdds the modern Target/Focus frame extras the default Anniversary UI is missing - all cosmetic, no taint.|r"] = "|cffaaaaaaFügt dem Ziel-/Fokus-Fenster die modernen Extras hinzu, die das Standard-Anniversary-UI weglässt – rein kosmetisch, kein Taint.|r",
    ["Threat"] = "Bedrohung",
    ["Numeric threat %"] = "Bedrohung in %",
    ["Shows your threat percentage on the target (and focus) above the frame, coloured by threat status."] = "Zeigt deinen Bedrohungswert in % über dem Ziel- (und Fokus-)Fenster, eingefärbt nach Bedrohungsstatus.",
    ["Threat glow"] = "Bedrohungs-Glow",
    ["Glows the target (and focus) frame in yellow/orange/red as your threat rises."] = "Lässt das Ziel- (und Fokus-)Fenster gelb/orange/rot leuchten, wenn deine Bedrohung steigt.",
    ["Classification"] = "Einstufung",
    ["Rare-Elite border"] = "Selten-Elite-Rahmen",
    ["Shows the winged silver-dragon Rare-Elite border on rare-elite mobs."] = "Zeigt den geflügelten Silberdrachen-Rahmen (Selten-Elite) bei Selten-Elite-Gegnern.",
    ["Class icon on player targets"] = "Klassen-Icon bei Spieler-Zielen",
    ["Shows the target's class crest on the frame when you target a player."] = "Zeigt das Klassen-Symbol des Ziels am Frame, wenn du einen Spieler anvisierst.",
    ["Also apply to the Focus frame"] = "Auch auf das Fokus-Fenster anwenden",
    ["Health"] = "Leben",
    ["Show real NPC health"] = "Echte NPC-HP anzeigen",
    ["Shows the true health value on NPCs instead of the obfuscated percentage (enemy players stay %)."] = "Zeigt bei NPCs den echten Lebenswert statt der verschleierten Prozentanzeige (feindliche Spieler bleiben %).",

    -- PlayerCastbar
    ["Player Castbar"] = "Spieler-Castbar",
    ["Player castbar with two modes: Original (Blizzard bar extended) or Custom castbar (VUI style)."] = "Spieler-Castbar mit zwei Modi: Original (Blizzard-Bar erweitert) oder Custom-Castbar (VUI-Stil).",
    ["|cffffffffCASTBAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffCASTBAR|r\n|cffaaaaaaZiehen oder Pfeiltasten|r",
    ["Castbar position: x=%.0f, y=%.0f"] = "Castbar-Position: x=%.0f, y=%.0f",
    ["|cff9b6cffMind Flay|r"] = "|cff9b6cffGedankenschinden|r",
    ["Castbar mover active. |cff9b6cffDrag purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Castbar-Mover aktiv. |cff9b6cffViolette Box ziehen|r oder |cff9b6cffPfeiltasten|r benutzen (SHIFT = 5px). Klicke nochmal auf 'Entsperren / Test' zum Beenden.",
    ["Castbar mover disabled."] = "Castbar-Mover deaktiviert.",
    ["Castbar Variant"] = "Castbar-Variante",
    ["Switch between Original (Blizzard bar extended) and Custom castbar (VUI style with icon, spell name below bar)."] = "Wechsel zwischen Original (Blizzard-Bar erweitert) und Custom-Castbar (VUI-Stil mit Icon, Zaubername unter dem Balken).",
    ["Original (Blizzard bar extended)"] = "Original (Blizzard-Bar erweitert)",
    ["Custom Castbar (VUI style)"] = "Custom-Castbar (VUI-Stil)",
    ["Castbar mode switched to |cff9b6cffOriginal|r. |cffffff00/reload|r recommended so the default bar works normally again."] = "Castbar-Modus auf |cff9b6cffOriginal|r gewechselt. |cffffff00/reload|r empfohlen, damit der Standardbalken wieder normal funktioniert.",
    ["Castbar mode switched to |cff9b6cffVUI Style|r."] = "Castbar-Modus auf |cff9b6cffVUI-Stil|r gewechselt.",
    ["|cffaaaaaaMode switch: A /reload may be required after switching so the default bar works normally again.|r"] = "|cffaaaaaaModus-Wechsel: Nach dem Wechseln kann ein /reload nötig sein, damit der Standardbalken wieder normal funktioniert.|r",
    ["Show spell name"] = "Zaubername anzeigen",
    ["Show cast timer"] = "Cast-Timer anzeigen",
    ["Show channel ticks"] = "Channel-Ticks anzeigen",
    ["Shows vertical lines at tick points (Mind Flay, Drain Soul, Hellfire, etc.)"] = "Zeigt vertikale Linien an den Tick-Punkten (Gedankenschinden, Seelenentzug, Höllenfeuer usw.)",
    ["Show clip window"] = "Clip-Fenster anzeigen",
    ["Shades the last bit of a channel (your latency) so you know when to recast and clip without losing the last tick - great for Mind Flay."] = "Hebt das letzte Stück eines Channels hervor (deine Latenz), damit du weißt, wann du neu wirken/clippen kannst, ohne den letzten Tick zu verlieren – ideal für Gedankenschinden.",
    ["Shades your latency at the end of the bar: on channels the moment to recast without losing the last tick, on casts the spell-queue window where the next cast can already be pressed."] = "Hebt deine Latenz am Ende der Leiste hervor: bei Channels der Moment zum Neuwirken ohne den letzten Tick zu verlieren, bei Casts das Zauber-Warteschlangen-Fenster, in dem der nächste Zauber schon gedrückt werden kann.",
    ["Timer format"] = "Zeitformat",
    ["Remaining / total (1.5 / 2.0)"] = "Restzeit / Gesamt (1.5 / 2.0)",
    ["Remaining only (1.5)"] = "Nur Restzeit (1.5)",
    ["Whole seconds (2)"] = "Ganze Sekunden (2)",
    ["Show pushback"] = "Rückstoß anzeigen",
    ["Briefly shows the time lost to spell pushback in red above the bar."] = "Zeigt die durch Zauber-Rückstoß verlorene Zeit kurz in Rot über der Leiste an.",
    ["Merge crafting casts"] = "Berufe-Serien zusammenfassen",
    ["When crafting several items in a row the bar shows a counter like 3/20 instead of single casts."] = "Beim Herstellen mehrerer Gegenstände zeigt die Leiste einen Zähler wie 3/20 statt einzelner Casts.",
    ["Fill color"] = "Füllfarbe",
    ["Bar textures = the classic yellow/green art. Accent or class color tint a neutral bar instead."] = "Balkentexturen = die klassische gelb/grüne Optik. Akzent- oder Klassenfarbe färben stattdessen einen neutralen Balken ein.",
    ["Bar textures (yellow/green)"] = "Balkentexturen (Gelb/Grün)",
    ["Accent color"] = "Akzentfarbe",
    ["VUI Style: Position & Size"] = "VUI-Stil: Position & Größe",
    ["Unlock / Test"] = "Entsperren / Test",
    ["Center Position"] = "Position zentrieren",
    ["|cffaaaaaaTip: Hold |cffffffffSHIFT|r and drag the castbar with the left mouse button during a cast to move it. Or use 'Unlock / Test' for a permanent test bar for positioning.|r"] = "|cffaaaaaaTipp: Halte |cffffffffSHIFT|r und ziehe die Castbar während eines Casts mit der linken Maustaste, um sie zu verschieben. Oder benutze 'Entsperren / Test' für einen permanenten Testbalken zur Positionierung.|r",
    ["Show icon"] = "Icon anzeigen",
    ["Icon Size"] = "Icon-Größe",
    ["Icon X Offset"] = "Icon X-Versatz",
    ["Icon Y Offset"] = "Icon Y-Versatz",
    ["Moves the icon horizontally. Negative = left, positive = right."] = "Verschiebt das Icon horizontal. Negativ = links, positiv = rechts.",
    ["Moves the icon vertically. Positive = up, negative = down."] = "Verschiebt das Icon vertikal. Positiv = oben, negativ = unten.",
    ["Test only available in 'Custom Castbar' mode."] = "Test nur im 'Custom-Castbar'-Modus verfügbar.",

    -- CooldownPulse
    ["Cooldown Pulse"] = "Cooldown-Pulse",
    ["Shows the icon of an expired cooldown as a brief pulsing animation in the screen center (based on Doom_CooldownPulse)."] = "Zeigt das Icon eines abgelaufenen Cooldowns als kurze pulsierende Animation in der Bildschirmmitte (basierend auf Doom_CooldownPulse).",
    ["Cooldown Pulse unlock active — drag icon to move."] = "Cooldown-Pulse-Entsperrung aktiv — Icon ziehen zum Verschieben.",
    ["Cooldown Pulse unlock disabled."] = "Cooldown-Pulse-Entsperrung deaktiviert.",
    ["Test Spell"] = "Testzauber",
    ["Cooldown Pulse position reset."] = "Cooldown-Pulse-Position zurückgesetzt.",
    ["Unlock"] = "Entsperren",
    ["Shows a test icon you can move around."] = "Zeigt ein Test-Icon, das du verschieben kannst.",
    ["Test Pulse"] = "Pulse testen",
    ["Plays a test animation."] = "Spielt eine Testanimation ab.",
    ["Reset Position"] = "Position zurücksetzen",
    ["Max Opacity"] = "Max. Deckkraft",
    ["Animation Scale"] = "Animations-Skalierung",
    ["Fade-In Time (s)"] = "Einblendzeit (s)",
    ["Hold Time (s)"] = "Haltezeit (s)",
    ["Fade-Out Time (s)"] = "Ausblendzeit (s)",
    ["Show Before Available (s)"] = "Vorzeitig anzeigen (s)",
    ["Triggers the animation X seconds BEFORE the cooldown expires. 0 = exactly at cooldown end."] = "Löst die Animation X Sekunden VOR Ablauf des Cooldowns aus. 0 = genau am Cooldown-Ende.",
    ["Spell Filter"] = "Zauberfilter",
    ["Show spell names"] = "Zaubernamen anzeigen",
    ["Shows the name of the spell under the icon."] = "Zeigt den Namen des Zaubers unter dem Icon.",
    ["Invert filter (whitelist instead of blacklist)"] = "Filter invertieren (Whitelist statt Blacklist)",
    ["Off: List = ignored spells. On: List = show ONLY these spells."] = "Aus: Liste = ignorierte Zauber. An: Liste = NUR diese Zauber anzeigen.",
    ["Spell List (comma-separated)"] = "Zauberliste (kommagetrennt)",
    ["Spell names exactly as in-game, comma-separated. Spell IDs also work."] = "Zaubernamen exakt wie im Spiel, kommagetrennt. Spell-IDs funktionieren ebenfalls.",

    -- ArenaFrames
    ["Arena Frames"] = "Arena-Fenster",
    ["Enhances the Arena enemy frames: move/scale, class colors, class icons, PvP trinket CD, DR tracking, castbar, drag&drop layout."] = "Erweitert die Arena-Gegnerfenster: Verschieben/Skalieren, Klassenfarben, Klassen-Icons, PvP-Trinket-CD, DR-Tracking, Castbar, Drag&Drop-Layout.",
    ["|cffff5555ArenaFrames submodule error:|r %s"] = "|cffff5555ArenaFrames-Submodul-Fehler:|r %s",
    ["|cffff5555Arena submodule OnEnable error:|r %s"] = "|cffff5555Arena-Submodul OnEnable-Fehler:|r %s",
    ["Layout"] = "Layout",
    ["Class Color"] = "Klassenfarbe",
    ["PvP Trinket"] = "PvP-Trinket",
    ["DR Tracker"] = "DR-Tracker",
    ["Castbar"] = "Castbar",
    ["|cffffffffArena Frames|r"] = "|cffffffffArena-Fenster|r",
    ["|cffaaaaaaClick + drag\nMouse wheel = scale|r"] = "|cffaaaaaaKlicken + ziehen\nMausrad = Skalierung|r",
    ["Arena Frames position saved."] = "Arena-Fenster-Position gespeichert.",
    ["|cff9b6cffArenaFrames Unlock|r  |cffaaaaaa(Scale: %.2f)|r"] = "|cff9b6cffArenaFrames Entsperrt|r  |cffaaaaaa(Skalierung: %.2f)|r",
    ["|cffaaaaaaClick + drag\nMouse wheel = scale\nCurrent: %.2f|r"] = "|cffaaaaaaKlicken + ziehen\nMausrad = Skalierung\nAktuell: %.2f|r",
    ["|cff9b6cffArenaFrames Unlock|r"] = "|cff9b6cffArenaFrames Entsperrt|r",
    ["Drag the purple overlay above the frames to move.\nMouse wheel on overlay = scale. /vcui arenaframes to finish."] = "Ziehe das violette Overlay über den Fenstern zum Verschieben.\nMausrad auf Overlay = Skalierung. /vcui arenaframes zum Beenden.",
    ["Unlock active. Click + drag the purple overlay to move."] = "Entsperren aktiv. Klicke + ziehe das violette Overlay zum Verschieben.",
    ["Unlock disabled."] = "Entsperren deaktiviert.",
    ["ArenaPlayer"] = "Arenaspieler",
    ["Reset position"] = "Position zurücksetzen",
    ["Position reset."] = "Position zurückgesetzt.",
    ["In unlock mode a purple overlay appears above the frames. Click + drag to move, mouse wheel to scale."] = "Im Entsperren-Modus erscheint ein violettes Overlay über den Fenstern. Klicken + ziehen zum Verschieben, Mausrad zum Skalieren.",

    ["Layout (Order)"] = "Layout (Reihenfolge)",
    ["Order of the arena frames. Use up/down to move slots 1-5."] = "Reihenfolge der Arena-Fenster. Mit Hoch/Runter Slots 1-5 verschieben.",
    ["|cff9b6cff%d.|r  Arena Slot %d"] = "|cff9b6cff%d.|r  Arena-Slot %d",
    ["Move up"] = "Nach oben",
    ["Move down"] = "Nach unten",
    ["Spacing between frames"] = "Abstand zwischen Fenstern",
    ["Grow direction"] = "Wuchsrichtung",
