    ["Upward"] = "Nach oben",
    ["Reset order"] = "Reihenfolge zurücksetzen",

    ["Class Visuals"] = "Klassen-Visuals",
    ["Class-colored health bars"] = "Klassenfarbige Lebensbalken",
    ["Colors the health bar in the player's class color."] = "Färbt den Lebensbalken in der Klassenfarbe des Spielers.",
    ["Class-colored name"] = "Klassenfarbiger Name",
    ["Class icon instead of portrait"] = "Klassen-Icon statt Portrait",
    ["Replaces the 3D portrait with a class symbol."] = "Ersetzt das 3D-Portrait durch ein Klassen-Symbol.",

    ["PvP Trinket Tracker"] = "PvP-Trinket-Tracker",
    ["Show PvP trinket cooldown"] = "PvP-Trinket-Cooldown anzeigen",
    ["Shows an icon with cooldown spiral next to the arena frame when the opponent used their PvP trinket."] = "Zeigt ein Icon mit Cooldown-Spirale neben dem Arena-Fenster, wenn der Gegner sein PvP-Trinket benutzt hat.",
    ["Icon size"] = "Icon-Größe",
    ["Left of frame"] = "Links vom Fenster",
    ["Right of frame"] = "Rechts vom Fenster",
    ["Offset X"] = "Versatz X",
    ["Offset Y"] = "Versatz Y",

    ["Diminishing Returns Tracker"] = "Diminishing-Returns-Tracker",
    ["Shows icons next to each arena frame for active DR categories (Stun, Fear, Polymorph etc.) with color indicator: |cff00ff00green|r = full, |cffffff00yellow|r = 1/2, |cffff8000orange|r = 1/4, |cffff0000red|r = immune."] = "Zeigt Icons neben jedem Arena-Fenster für aktive DR-Kategorien (Stun, Fear, Polymorph usw.) mit Farbindikator: |cff00ff00grün|r = voll, |cffffff00gelb|r = 1/2, |cffff8000orange|r = 1/4, |cffff0000rot|r = immun.",
    ["Enable DR tracking"] = "DR-Tracking aktivieren",

    ["INTERRUPTED"] = "UNTERBROCHEN",
    ["Castbar for arena opponents"] = "Castbar für Arena-Gegner",
    ["Shows a castbar below the frame when the opponent casts or channels."] = "Zeigt eine Castbar unter dem Fenster, wenn der Gegner zaubert oder kanalisiert.",

    -- MiscQoL
    ["Collection of simple quality-of-life toggles: auto-accept (quest, res, summon), auto-sell, repair, hide UI spam, text sizes."] = "Sammlung einfacher Komfort-Schalter: Auto-Annehmen (Quest, Wiederbelebung, Beschwörung), Auto-Verkaufen, Reparieren, UI-Spam ausblenden, Textgrößen.",
    ["Auto-sold: %d items, +%s"] = "Auto-verkauft: %d Gegenstände, +%s",
    ["Auto-sold: %d items."] = "Auto-verkauft: %d Gegenstände.",
    ["Repair exceeds gold (%d < %d)."] = "Reparatur übersteigt Gold (%d < %d).",
    ["Auto-repaired (%dg %ds)."] = "Auto-repariert (%dg %ds).",
    ["MAX"] = "MAX",
    ["General - Auto Actions"] = "Allgemein - Auto-Aktionen",
    ["|cffaaaaaaSimple on/off switches for common QoL actions. Take effect immediately, no /reload needed.|r"] = "|cffaaaaaaEinfache An/Aus-Schalter für gängige Komfort-Aktionen. Wirken sofort, kein /reload nötig.|r",
    ["Auto-accept quests"] = "Quests automatisch annehmen",
    ["Automatically accepts quests when clicking an NPC."] = "Nimmt Quests automatisch an, wenn du einen NPC anklickst.",
    ["Auto-turn in quests"] = "Quests automatisch abgeben",
    ["Automatically completes finished quests. Waits for user choice on multi-reward quests (no auto-pick)."] = "Schließt abgeschlossene Quests automatisch ab. Wartet bei Multi-Belohnungs-Quests auf die Auswahl (keine Auto-Auswahl).",
    ["Auto-accept resurrect"] = "Wiederbelebung automatisch annehmen",
    ["Automatically clicks 'Accept' on resurrect popups (not in combat)."] = "Klickt automatisch 'Annehmen' bei Wiederbelebungs-Popups (nicht im Kampf).",
    ["Auto-accept summon"] = "Beschwörung automatisch annehmen",
    ["Automatically clicks 'Accept' on warlock/stone summon popups."] = "Klickt automatisch 'Annehmen' bei Hexenmeister-/Steinbeschwörungs-Popups.",
    ["Auto-release spirit in PvP/Arena"] = "Geist in PvP/Arena automatisch befreien",
    ["Releases instantly on death in BG or arena."] = "Befreit den Geist sofort beim Tod im BG oder in der Arena.",
    ["Auto-sell junk (grey)"] = "Junk automatisch verkaufen (grau)",
    ["Sells all grey items when opening a vendor. Earnings shown in chat."] = "Verkauft beim Öffnen eines Anbieters alle grauen Gegenstände. Einnahmen werden im Chat angezeigt.",
    ["Auto-repair"] = "Auto-Reparatur",
    ["Repairs entire equipment at the vendor if gold is sufficient."] = "Repariert die gesamte Ausrüstung beim Anbieter, wenn genug Gold vorhanden ist.",
    ["Stack-split popup: MAX button"] = "Stack-Aufteilen-Popup: MAX-Button",
    ["Adds a 'MAX' button to the quantity popup. Click = buy full stack (at vendor) or split completely (for bag items)."] = "Fügt dem Mengen-Popup einen 'MAX'-Button hinzu. Klick = ganzen Stack kaufen (beim Anbieter) oder komplett aufteilen (bei Taschen-Items).",
    ["Stack-split popup: VuloUI look"] = "Stack-Aufteilen-Popup im VuloUI-Stil",
    ["Restyles the quantity popup (stack buying/splitting) to match the addon look: dark panel, clean buttons and arrows. Turning this off needs a /reload."] = "Gestaltet das Mengen-Popup (Stack-Kauf/-Aufteilen) im Addon-Look: dunkles Panel, klare Knöpfe und Pfeile. Zum Deaktivieren ist ein /reload nötig.",
    ["Hide UI error messages"] = "UI-Fehlermeldungen ausblenden",
    ["Hides the red error messages in the screen center."] = "Blendet die roten Fehlermeldungen in der Bildschirmmitte aus.",
    ["Hide zone text"] = "Gebietsnamen ausblenden",
    ["Hides the large zone name when entering new areas."] = "Blendet den großen Gebietsnamen beim Betreten neuer Gebiete aus.",
    ["Hide level numbers on portrait"] = "Stufenzahlen auf Portrait ausblenden",
    ["Hides the level display on the Player/Target/Pet portrait."] = "Blendet die Stufenanzeige auf dem Spieler-/Ziel-/Pet-Portrait aus.",
    ["Hide keybind text on action buttons"] = "Tastenbelegungstext auf Aktionsbuttons ausblenden",
    ["Hides the small key labels (1, F1, etc.) on the action buttons."] = "Blendet die kleinen Tastenbezeichnungen (1, F1 usw.) auf den Aktionsbuttons aus.",
    ["Hide macro/spell names on action buttons"] = "Makro-/Zaubernamen auf Aktionsbuttons ausblenden",
    ["Hides the text labels under the action buttons."] = "Blendet die Textbezeichnungen unter den Aktionsbuttons aus.",
    ["Hide stack/charge numbers on action buttons"] = "Stack-/Ladungszahlen auf Aktionsbuttons ausblenden",
    ["Hides the small boxes with numbers at the top right (item stacks, charges, cooldown seconds for long CDs)."] = "Blendet die kleinen Boxen mit Zahlen oben rechts aus (Item-Stacks, Ladungen, Cooldown-Sekunden für lange CDs).",
    ["Hide raid group labels"] = "Schlachtgruppen-Bezeichnungen ausblenden",
    ["Hides the 'Group 1'/'Group 2' labels above the compact raid frames."] = "Blendet die 'Gruppe 1'-/'Gruppe 2'-Bezeichnungen über den kompakten Schlachtgruppenfenstern aus.",
    ["Mail Text Size"] = "Mail-Textgröße",
    ["Font size in mail body (opened + sent mail)."] = "Schriftgröße im Mailtext (geöffnete + gesendete Mails).",
    ["Quest Text Size"] = "Quest-Textgröße",
    ["Font size in quest descriptions + quest log."] = "Schriftgröße in Questbeschreibungen + Questlog.",
    ["Book Text Size"] = "Buch-Textgröße",
    ["Font size in readable books and letters from item text."] = "Schriftgröße in lesbaren Büchern und Briefen aus Itemtexten.",

    -- QueueTimer
    ["Queue Timer"] = "Queue-Timer",
    ["Shows a countdown on the PvP/PvE queue pop dialog. Optional sound warning at 5 seconds."] = "Zeigt einen Countdown im PvP-/PvE-Warteschlangen-Dialog. Optional Soundwarnung bei 5 Sekunden.",
    ["Queue expires in"] = "Warteschlange läuft ab in",
    ["|cff00c0ffQueueTimer:|r "] = "|cff00c0ffWarteschlangen-Timer:|r ",
    ["Dungeon queue popped instantly!"] = "Dungeon-Warteschlange wurde sofort verfügbar!",
    ["Dungeon queue popped after %s"] = "Dungeon-Warteschlange verfügbar nach %s",
    ["Dungeon queue popped."] = "Dungeon-Warteschlange verfügbar.",
    ["Queue popped instantly!"] = "Warteschlange sofort verfügbar!",
    ["Queue popped after %s"] = "Warteschlange verfügbar nach %s",
    ["Sound on queue pop"] = "Sound bei Warteschlangen-Verfügbarkeit",
    ["Plays a sound as soon as the queue pops."] = "Spielt einen Sound ab, sobald die Warteschlange verfügbar ist.",
    ["5-second warning"] = "5-Sekunden-Warnung",
    ["Plays 3 quick sounds when only 5 seconds remain to accept."] = "Spielt 3 schnelle Sounds ab, wenn nur noch 5 Sekunden zum Annehmen verbleiben.",
    ["Hide other timers (e.g. BigWigs)"] = "Andere Timer ausblenden (z.B. BigWigs)",
    ["Hides foreign StatusBars on the LFG ready popup so only our timer is visible."] = "Blendet fremde StatusBars im LFG-Ready-Popup aus, sodass nur unser Timer sichtbar ist.",

    -- TooltipIDs
    ["Tooltip IDs"] = "Tooltip-IDs",
    ["Shows SpellID, ItemID, NPC ID and many other IDs in tooltips (based on idTip by silverwind)."] = "Zeigt SpellID, ItemID, NPC-ID und viele weitere IDs in Tooltips (basierend auf idTip von silverwind).",
    ["|cff9b6cffTalents:|r "] = "|cff9b6cffTalente:|r ",
    ["|cff9b6cffiLvL:|r %d"] = "|cff9b6cffiLvL:|r %d",
    ["  |cff888888(off by default)|r"] = "  |cff888888(standardmäßig aus)|r",
    ["Shows %s in tooltips."] = "Zeigt %s in Tooltips an.",
    ["Shows additional ID lines in tooltips, e.g. spell, item or NPC IDs."] = "Zeigt zusätzliche ID-Zeilen in Tooltips, z.B. Zauber-, Item- oder NPC-IDs.",
    ["Quick Select"] = "Schnellauswahl",
    ["All on"] = "Alle an",
    ["All off"] = "Alle aus",
    ["Defaults"] = "Standard",
    ["Player Tooltip (Inspect-based)"] = "Spieler-Tooltip (Inspect-basiert)",
    ["|cffaaaaaaWhen you hover over a player, their average iLvL + talent distribution (e.g. 14/0/47) is shown in the tooltip. Data is cached 60s per player, inspect throttle 1/s.|r"] = "|cffaaaaaaWenn du über einen Spieler hoverst, werden im Tooltip dessen Durchschnitts-iLvL + Talentverteilung (z.B. 14/0/47) angezeigt. Daten werden 60s pro Spieler gecacht, Inspect-Throttle 1/s.|r",
    ["Show average iLvL"] = "Durchschnitts-iLvL anzeigen",
    ["Show talent distribution (e.g. 14/0/47)"] = "Talentverteilung anzeigen (z.B. 14/0/47)",
    ["ID Types"] = "ID-Typen",
    ["Which IDs should be shown in tooltips? Some types are only active in Retail and are ignored in TBC (e.g. TraitNodeID, SourceID)."] = "Welche IDs sollen in Tooltips angezeigt werden? Manche Typen sind nur in Retail aktiv und werden in TBC ignoriert (z.B. TraitNodeID, SourceID).",

    -- AutoItemBuy
    ["Auto Item Buy"] = "Auto-Itemkauf",
    ["Automatically buys configured items at configured vendors. Shift when opening the merchant window = emergency stop."] = "Kauft konfigurierte Items automatisch bei konfigurierten Anbietern. Shift beim Öffnen des Anbieterfensters = Notbremse.",
    ["|cffffd200[AutoItemBuy]|r "] = "|cffffd200[Auto-Itemkauf]|r ",
    ["Buying: "] = "Kaufe: ",
    ["Close merchant window after purchase"] = "Anbieterfenster nach Kauf schließen",
    ["Closes the merchant window automatically ~0.2s after purchase."] = "Schließt das Anbieterfenster automatisch ~0.2s nach dem Kauf.",
    ["Chat message on each purchase"] = "Chatnachricht bei jedem Kauf",
    ["|cffaaaaaaTip: Hold SHIFT when opening the merchant window to skip automatic purchase once.|r"] = "|cffaaaaaaTipp: Halte SHIFT beim Öffnen des Anbieterfensters, um den automatischen Kauf einmal zu überspringen.|r",
    ["Add Vendor"] = "Anbieter hinzufügen",
    ["Vendor Name"] = "Anbietername",
    ["Add"] = "Hinzufügen",
    ["|cffff5555Please enter a vendor name.|r"] = "|cffff5555Bitte einen Anbieternamen eingeben.|r",
    ["|cffff5555Vendor '%s' already exists.|r"] = "|cffff5555Anbieter '%s' existiert bereits.|r",
    ["Vendor '%s' added."] = "Anbieter '%s' hinzugefügt.",
    ["Manage Vendors"] = "Anbieter verwalten",
    ["|cffaaaaaaNo vendors added yet. Add a vendor above, then select it here to configure items.|r"] = "|cffaaaaaaNoch keine Anbieter hinzugefügt. Füge oben einen Anbieter hinzu und wähle ihn dann hier aus, um Items zu konfigurieren.|r",
    ["Currently selected vendor"] = "Aktuell ausgewählter Anbieter",
    ["Delete this vendor"] = "Diesen Anbieter löschen",
    ["Vendor '%s' removed."] = "Anbieter '%s' entfernt.",
    ["Items at '%s'"] = "Items bei '%s'",
    ["Item name (exactly as in-game)"] = "Itemname (exakt wie im Spiel)",
    ["|cffff5555Please enter an item name.|r"] = "|cffff5555Bitte einen Itemnamen eingeben.|r",
    ["Item '%s' added at vendor '%s'."] = "Item '%s' bei Anbieter '%s' hinzugefügt.",
    ["|cffaaaaaaItem names must match the in-game name exactly (including case and special characters).|r"] = "|cffaaaaaaItemnamen müssen exakt dem In-Game-Namen entsprechen (inkl. Groß-/Kleinschreibung und Sonderzeichen).|r",
    ["|cffaaaaaaNo items configured. Add items above that should be bought automatically at this vendor.|r"] = "|cffaaaaaaKeine Items konfiguriert. Füge oben Items hinzu, die bei diesem Anbieter automatisch gekauft werden sollen.|r",
    ["Remove"] = "Entfernen",
    ["Item '%s' removed."] = "Item '%s' entfernt.",

    -- Bug Fix modules
    ["Inspect Fix"] = "Inspect-Fix",
    ["Fixes stuck inspect bugs (no player inspect possible after a faulty close/timeout). Auto-reset after 8s + cleanup when InspectFrame closes + /inspectreset slash command."] = "Behebt hängende Inspect-Bugs (kein Spieler-Inspect möglich nach fehlerhaftem Schließen/Timeout). Auto-Reset nach 8s + Cleanup beim Schließen des InspectFrames + /inspectreset Slash-Befehl.",
    ["Fixes stuck inspect bugs (no player inspect possible after a faulty close/timeout). Auto-reset after a timeout + cleanup when InspectFrame closes + /inspectreset slash command."] = "Behebt hängende Inspect-Bugs (kein Spieler-Inspect möglich nach fehlerhaftem Schließen/Timeout). Auto-Reset nach einem Timeout + Cleanup beim Schließen des InspectFrames + /inspectreset Slash-Befehl.",
    ["Inspect state manually reset. Try again now."] = "Inspect-Status manuell zurückgesetzt. Versuche es jetzt nochmal.",
    ["|cffffff00[VuloClassicUI]|r Inspect state reset."] = "|cffffff00[VuloClassicUI]|r Inspect-Status zurückgesetzt.",
    ["Auto-reset on timeout"] = "Auto-Reset bei Timeout",
    ["If no response from the server comes after X seconds, the pending inspect state is automatically reset — so the next inspect attempt works again."] = "Wenn nach X Sekunden keine Antwort vom Server kommt, wird der ausstehende Inspect-Status automatisch zurückgesetzt — der nächste Inspect-Versuch funktioniert dann wieder.",
    ["Aggressive reset before each inspect"] = "Aggressiver Reset vor jedem Inspect",
    ["Force-clears the inspect state before every NotifyInspect/InspectUnit call. Recommended for Anniversary because Blizzard's UI doesn't reliably clear the previous target's cache. Disable only if you have compatibility issues with another inspect addon."] = "Erzwingt das Leeren des Inspect-Status vor jedem NotifyInspect/InspectUnit-Aufruf. Empfohlen für Anniversary, da Blizzards UI den Cache des vorherigen Ziels nicht zuverlässig leert. Nur deaktivieren bei Kompatibilitätsproblemen mit einem anderen Inspect-Addon.",
    ["How long to wait for INSPECT_READY before auto-reset kicks in. 5 seconds is the new default for Anniversary — fast enough to recover quickly."] = "Wie lange auf INSPECT_READY gewartet werden soll, bevor der Auto-Reset greift. 5 Sekunden ist der neue Standard für Anniversary — schnell genug zur raschen Erholung.",
    ["NotifyInspect override: %s\nInspectUnit override:   %s\nInspectFrame hook:      %s"] = "NotifyInspect-Override: %s\nInspectUnit-Override:   %s\nInspectFrame-Hook:      %s",
    ["|cffaaaaaaSlash commands: /inspectreset (force-reset), /inspectstate (debug info in chat)|r"] = "|cffaaaaaaSlash-Befehle: /inspectreset (Reset erzwingen), /inspectstate (Debug-Info im Chat)|r",
    ["|cffaaaaaaWhat the fix does: replaces NotifyInspect and InspectUnit with wrappers that force-clear server state before each request. Plus full reset when the inspect frame closes or after a 5s timeout.|r"] = "|cffaaaaaaWas der Fix macht: ersetzt NotifyInspect und InspectUnit durch Wrapper, die den Server-Status vor jeder Anfrage zwangsweise leeren. Plus voller Reset beim Schließen des Inspect-Fensters oder nach 5s Timeout.|r",
    ["Timeout (seconds)"] = "Timeout (Sekunden)",
    ["How long to wait for INSPECT_READY before auto-reset kicks in. 8 seconds is a good default — fast enough for out-of-range, slow enough not to abort normal server lag."] = "Wie lange auf INSPECT_READY gewartet werden soll, bevor der Auto-Reset greift. 8 Sekunden sind ein guter Standard — schnell genug für Out-of-Range, langsam genug, um normalen Server-Lag nicht abzubrechen.",
    ["Manual Reset"] = "Manueller Reset",
    ["Reset inspect state now"] = "Inspect-Status jetzt zurücksetzen",
    ["Inspect state manually reset."] = "Inspect-Status manuell zurückgesetzt.",
    ["|cffaaaaaaSlash command: /inspectreset|r"] = "|cffaaaaaaSlash-Befehl: /inspectreset|r",
    ["NotifyInspect hook: %s\nInspectFrame hook: %s"] = "NotifyInspect-Hook: %s\nInspectFrame-Hook: %s",
    ["|cff66ff66active|r"] = "|cff66ff66aktiv|r",
    ["|cffff8800waiting|r"] = "|cffff8800wartet|r",
    ["|cffff8800waiting for Blizzard_InspectUI|r"] = "|cffff8800wartet auf Blizzard_InspectUI|r",
    ["|cffaaaaaaWhat the fix does: tracks active inspects with a timestamp, repaints late-arriving item data, re-requests an all-empty inspect once, and calls ClearInspectPlayer() on close + on timeout. Prevents a stuck state from blocking all subsequent inspects.|r"] = "|cffaaaaaaWas der Fix macht: verfolgt aktive Inspects mit einem Timestamp, zeichnet nachträglich eintreffende Item-Daten neu, fordert einen komplett leeren Inspect einmal automatisch neu an und ruft ClearInspectPlayer() beim Schließen + bei Timeout auf. Verhindert, dass ein hängender Status alle weiteren Inspects blockiert.|r",
    ["Auto-retry empty inspects"] = "Leere Inspects automatisch wiederholen",
    ["After the server answers, the item slots are repainted again shortly after (data often arrives late). If the window is still completely empty, the inspect is automatically requested one more time."] = "Nach der Server-Antwort werden die Item-Slots kurz danach erneut gezeichnet (Daten trudeln oft nach). Ist das Fenster dann immer noch komplett leer, wird der Inspect automatisch einmal neu angefordert.",

    ["|cffaaaaaaStatus: %s|r"] = "|cffaaaaaaStatus: %s|r",
    ["|cff66ff66Hook active|r"] = "|cff66ff66Hook aktiv|r",

    ["LFG Browse Nil Fix"] = "LFG-Browse",
    ["Catches Lua errors in the Anniversary Group Finder (LFGBrowseSearchEntry_Update with stale resultIDs). Prevents chat spam and broken browse lists."] = "Fängt Lua-Fehler im Anniversary-Gruppenfinder ab (LFGBrowseSearchEntry_Update mit veralteten resultIDs). Verhindert Chat-Spam und kaputte Browse-Listen.",
    ["|cffffff00[VuloClassicUI]|r Blizzard LFG browse error caught (stale entry skipped)."] = "|cffffff00[VuloClassicUI]|r Blizzard-LFG-Browse-Fehler abgefangen (veralteter Eintrag übersprungen).",
    ["Chat message on first error"] = "Chatnachricht beim ersten Fehler",
    ["Shows a brief message once per session in chat when an LFG browse error was caught."] = "Zeigt einmal pro Session eine kurze Nachricht im Chat, wenn ein LFG-Browse-Fehler abgefangen wurde.",
    ["This fix wraps Blizzard's |cffffffffLFGBrowseSearchEntry_Update|r function in a protected call (xpcall). When the entry crashes due to a stale resultID (\"searchResultInfo nil\"), the error is swallowed — Blizzard's next refresh automatically cleans up the list entry."] = "Dieser Fix umhüllt Blizzards |cffffffffLFGBrowseSearchEntry_Update|r-Funktion mit einem geschützten Aufruf (xpcall). Wenn der Eintrag wegen einer veralteten resultID (\"searchResultInfo nil\") abstürzt, wird der Fehler unterdrückt — Blizzards nächstes Refresh räumt den Listeneintrag automatisch auf.",
    ["waiting for Blizzard_GroupFinder_VanillaStyle"] = "wartet auf Blizzard_GroupFinder_VanillaStyle",

    ["Guild News Nil Fix"] = "Gildennews",
    ["Catches Lua errors in guild news entries (typically \"formatString\" or \"GuildUtil\") and replaces broken entries with a fallback text instead of letting the whole panel break."] = "Fängt Lua-Fehler in Gildennews-Einträgen ab (meist \"formatString\" oder \"GuildUtil\") und ersetzt kaputte Einträge mit einem Fallback-Text, statt das ganze Panel zerbrechen zu lassen.",
    ["|cffff8080Invalid guild news entry|r"] = "|cffff8080Ungültiger Gildennews-Eintrag|r",
    ["|cffffff00[VuloClassicUI]|r Blizzard guild news error caught (fallback applied)."] = "|cffffff00[VuloClassicUI]|r Blizzard-Gildennews-Fehler abgefangen (Fallback angewendet).",
    ["Shows a brief message once per session in chat when a guild news error was caught."] = "Zeigt einmal pro Session eine kurze Nachricht im Chat, wenn ein Gildennews-Fehler abgefangen wurde.",
    ["This fix wraps Blizzard's |cffffffffGuildNewsButton_SetNews|r function in a protected call (xpcall). When an entry throws a known error (\"formatString\" or \"GuildUtil\"), the entry is replaced with a fallback text \"Invalid guild news entry\" — the panel remains usable."] = "Dieser Fix umhüllt Blizzards |cffffffffGuildNewsButton_SetNews|r-Funktion mit einem geschützten Aufruf (xpcall). Wenn ein Eintrag einen bekannten Fehler wirft (\"formatString\" oder \"GuildUtil\"), wird der Eintrag durch einen Fallback-Text \"Ungültiger Gildennews-Eintrag\" ersetzt — das Panel bleibt benutzbar.",
    ["waiting for Blizzard_Communities"] = "wartet auf Blizzard_Communities",

    ["Auction Price Fix"] = "Auktions-Preis",
    ["Fixes a nil error in the German auction house UI (PriceDropdown not defined)."] = "Behebt einen Nil-Fehler im deutschen Auktionshaus-UI (PriceDropdown nicht definiert).",
    ["This fix addresses a known bug in the German WoW localization: the auction house UI references a \"PriceDropdown\" element that was never defined, which causes Lua errors when opening the auction house."] = "Dieser Fix behebt einen bekannten Bug der deutschen WoW-Lokalisierung: das Auktionshaus-UI referenziert ein \"PriceDropdown\"-Element, das nie definiert wurde, was beim Öffnen des Auktionshauses Lua-Fehler verursacht.",
    ["|cffaaaaaaCurrent locale: %s|r"] = "|cffaaaaaaAktuelle Sprache: %s|r",
    ["|cffaaaaaaThe fix only applies on German clients (deDE). On other languages the module is inactive.|r"] = "|cffaaaaaaDer Fix wird nur auf deutschen Clients (deDE) angewendet. In anderen Sprachen ist das Modul inaktiv.|r",
    ["|cff66ff66applied|r"] = "|cff66ff66angewendet|r",
    ["skipped (deDE-only)"] = "übersprungen (nur deDE)",
    ["not applied"] = "nicht angewendet",

    -- CombatText
    ["Combat Text"] = "Kampftext",
