    ["Shows the spell icon inline next to the spell name."] = "Zeigt das Zauber-Icon direkt neben dem Zaubernamen an.",
    ["Parried"] = "Pariert",
    ["Dodged"] = "Ausgewichen",
    ["Missed"] = "Verfehlt",
    ["Blocked"] = "Geblockt",
    ["Absorbed"] = "Absorbiert",
    ["|cffffffffCOMBAT TEXT|r"] = "|cffffffffKAMPFTEXT|r",
    ["Combat Text mover active. Drag or arrow keys (SHIFT=5px)."] = "Kampftext-Mover aktiv. Ziehen oder Pfeiltasten (SHIFT=5px).",
    ["|cffaaaaaaCustom scrolling text engine above the player. Anniversary disabled Blizzard's old player FCT. Each event can have its own color + size + outline/shadow.|r"] = "|cffaaaaaaEigene Scrolling-Text-Engine über dem Spieler. Anniversary hat Blizzards alten Player-FCT deaktiviert. Jedes Ereignis kann eigene Farbe + Größe + Kontur/Schatten haben.|r",
    ["Flashing combat notifications (with live preview) plus a scrolling combat-log text engine."] = "Aufblitzende Kampf-Benachrichtigungen (mit Live-Vorschau) plus eine scrollende Kampflog-Text-Engine.",
    ["|cffaaaaaaNotifications (+/- Combat, Low Durability) flash centred and stack; combat-log events (interrupts, dispels, misses) scroll upward. Use Preview to position and style them.|r"] = "|cffaaaaaaBenachrichtigungen (+/- Kampf, Niedrige Haltbarkeit) blitzen zentriert auf und stapeln sich; Kampflog-Ereignisse (Unterbrechungen, Banne, Misses) scrollen nach oben. Nutze die Vorschau zum Positionieren und Gestalten.|r",
    ["Show Preview"] = "Vorschau anzeigen",
    ["Shows all three notification messages on screen so you can position and style them. Turns off automatically when you close this window."] = "Zeigt alle drei Benachrichtigungen am Bildschirm, damit du sie positionieren und gestalten kannst. Schaltet sich beim Schließen des Fensters automatisch ab.",
    ["Notifications (flash & stack)"] = "Benachrichtigungen (Blitz & Stapel)",
    ["Combat Log (scrolling)"] = "Kampflog (scrollend)",
    ["Text"] = "Text",
    ["Outline Style"] = "Kontur-Stil",
    ["Thick Outline"] = "Dicke Kontur",
    ["Flash Duration (sec.)"] = "Blitz-Dauer (Sek.)",
    ["How long the +/- Combat flash stays before fading."] = "Wie lange das +/- Kampf-Aufblitzen bleibt, bevor es ausblendet.",
    ["Categories (Quick on/off)"] = "Kategorien (Schnell an/aus)",
    ["Combat State (+/- Combat)"] = "Kampfstatus (+/- Kampf)",
    ["Combat start and combat end messages."] = "Kampf-Start- und Kampf-Ende-Meldungen.",
    ["Combat Log Events"] = "Kampflog-Ereignisse",
    ["Interrupts, dispels, misses (Parry/Dodge/Block)."] = "Unterbrechungen, Banne, Misses (Parieren/Ausweichen/Blocken).",
    ["Durability Warning"] = "Haltbarkeitswarnung",
    ["Low durability after combat exit."] = "Niedrige Haltbarkeit nach Kampfende.",
    ["Global Defaults"] = "Globale Standardwerte",
    ["Per-Event Customization"] = "Pro-Ereignis-Anpassung",
    ["Font for our combat text engine. Also used for Blizzard's mob FCT (DAMAGE_TEXT_FONT) when enabled below."] = "Schriftart für unsere Kampftext-Engine. Wird auch für Blizzards Mob-FCT (DAMAGE_TEXT_FONT) verwendet, wenn unten aktiviert.",
    ["Also apply font to Blizzard mob FCT"] = "Schriftart auch auf Blizzard-Mob-FCT anwenden",
    ["Additionally sets DAMAGE_TEXT_FONT globally - changes the font of the damage numbers above mobs/pets. Requires /reload to take effect."] = "Setzt zusätzlich DAMAGE_TEXT_FONT global - ändert die Schriftart der Schadenszahlen über Mobs/Pets. Erfordert /reload zur Wirkung.",
    ["Default: Thick Outline"] = "Standard: Dicke Kontur",
    ["Default: Shadow"] = "Standard: Schatten",
    ["Scroll Duration (sec.)"] = "Scroll-Dauer (Sek.)",
    ["Scroll Distance (px)"] = "Scroll-Distanz (px)",
    ["Interrupted"] = "Unterbrochen",
    ["Interrupted: Frostbolt"] = "Unterbrochen: Frostblitz",
    ["Dispelled/Purged"] = "Gebannt/Vertrieben",
    ["Dispelled: Curse"] = "Gebannt: Fluch",
    ["Parried/Dodged/Missed"] = "Pariert/Ausgewichen/Verfehlt",
    ["Low Durability"] = "Niedrige Haltbarkeit",
    ["Durability Threshold (%)"] = "Haltbarkeits-Schwellwert (%)",
    ["Warning appears when at least one equipped item is below this value (after combat exit)."] = "Warnung erscheint, wenn mindestens ein angelegtes Item unter diesem Wert liegt (nach Kampfende).",
    ["Engine FCT (above mob/pet)"] = "Engine-FCT (über Mob/Pet)",
    ["Sharper hit indicator font (Friz Quadrata)"] = "Schärfere Hit-Indicator-Schrift (Friz Quadrata)",
    ["Engine FCT Scale"] = "Engine-FCT-Skalierung",
    ["Damage numbers above mob/pet — bitmap scaling."] = "Schadenszahlen über Mob/Pet — Bitmap-Skalierung.",
    ["Center"] = "Zentrieren",
    ["Keeps the horizontal position and only centers vertically in the screen center."] = "Behält die horizontale Position und zentriert nur vertikal in der Bildschirmmitte.",
    ["Unlock / Position"] = "Entsperren / Position",

    -- Trinkets wrapper
    ["Trinkets"] = "Schmuckstücke",
    ["Two trinket slots on screen with cooldown display, dropdown selection and auto-queue."] = "Zwei Schmuckstück-Slots auf dem Bildschirm mit Cooldown-Anzeige, Dropdown-Auswahl und Auto-Queue.",
    ["|cffaaaaaaTwo trinket slots with cooldown, dropdown selection and auto-queue.|nLeft click = use, right click = dropdown.|r"] = "|cffaaaaaaZwei Schmuckstück-Slots mit Cooldown, Dropdown-Auswahl und Auto-Queue.|nLinksklick = benutzen, Rechtsklick = Dropdown.|r",
    ["Show frame"] = "Fenster anzeigen",
    ["Hides or shows the two trinket slots. Auto-queue continues to run while hidden."] = "Blendet die beiden Schmuckstück-Slots aus oder zeigt sie an. Auto-Queue läuft im Hintergrund weiter.",
    ["Position locked"] = "Position gesperrt",
    ["If on, the frame cannot be accidentally moved."] = "Wenn an, kann das Fenster nicht versehentlich verschoben werden.",
    ["Size"] = "Größe",
    ["Scales the trinket slots."] = "Skaliert die Schmuckstück-Slots.",
    ["|cffaaaaaaTip: Left click on a slot uses the trinket, right click shows the selection list. Auto-queue is configured via right click -> Queue tab.|r"] = "|cffaaaaaaTipp: Linksklick auf einen Slot benutzt das Schmuckstück, Rechtsklick zeigt die Auswahlliste. Auto-Queue wird per Rechtsklick -> Queue-Reiter konfiguriert.|r",

    -- CharacterPanel
    ["Character Panel"] = "Charakterfenster",
    -- DarkSkin
    ["Dark Skin"] = "Dunkles Design",
    ["The dark look of the UI in one place: a built-in dark skin for action buttons and WeakAuras icons, plus an optional Dark Mode that darkens Blizzard's default frames, minimap and bars."] = "Der dunkle Look der Oberfläche an einem Ort: ein eingebauter dunkler Skin für Aktionsbuttons und WeakAuras-Icons, plus ein optionaler Dunkelmodus, der Blizzards Standard-Fenster, Minikarte und Leisten abdunkelt.",
    ["|cffaaaaaaThe dark look of the UI in one place: a built-in skin for action buttons and WeakAuras icons, plus an optional Dark Mode that re-tints Blizzard's default frames.|r"] = "|cffaaaaaaDer dunkle Look der Oberfläche an einem Ort: ein eingebauter Skin für Aktionsbuttons und WeakAuras-Icons, plus ein optionaler Dunkelmodus, der Blizzards Standard-Fenster umfärbt.|r",
    ["The dark action-bar button skin."] = "Der dunkle Aktionsleisten-Button-Skin.",
    ["Enable Dark Mode"] = "Dunkelmodus aktivieren",
    ["Re-tints Blizzard's default frames, minimap and action-bar artwork to a dark tone. Off by default."] = "Färbt Blizzards Standard-Fenster, Minikarte und Aktionsleisten-Grafik in einen dunklen Ton um. Standardmäßig aus.",
    ["|cffaaaaaaOptional: darkens and desaturates Blizzard's default artwork — unit frames, minimap and action bars — to a neutral dark tone. Reversible: turn it off and the gold look returns.|r"] = "|cffaaaaaaOptional: dunkelt Blizzards Standard-Grafik — Einheitenfenster, Minikarte und Aktionsleisten — auf einen neutralen dunklen Ton ab und entsättigt sie. Umkehrbar: ausschalten und der goldene Look kehrt zurück.|r",
    ["Button Skin"] = "Button-Skin",
    ["Built-in dark drop-shadow skin for action buttons and WeakAuras icons: black, rounded, soft rim. Several styles, no extra addons needed."] = "Eingebauter dunkler Schatten-Skin für Aktionsbuttons und WeakAuras-Icons: schwarz, abgerundet, weicher Rand. Mehrere Stile, keine Zusatz-Addons nötig.",
    ["|cffaaaaaaBuilt-in dark drop-shadow skin. Action bars and WeakAuras icons are configured separately below.|r"] = "|cffaaaaaaEingebauter dunkler Schatten-Skin. Aktionsleisten und WeakAuras-Icons werden unten getrennt eingestellt.|r",
    ["Action Bars"] = "Aktionsleisten",
    ["Skin the action bars"] = "Aktionsleisten skinnen",
    ["The dark action-bar border. Works on its own, and Dark Mode can drive it too."] = "Der dunkle Aktionsleisten-Rand. Funktioniert eigenständig, und der Dunkelmodus kann ihn ebenfalls steuern.",
    ["Bar style"] = "Leisten-Stil",
    ["Bar icon size"] = "Icon-Größe der Leisten",
    ["How much of the button the icon fills in Shadow style. Higher = bigger icons with a thinner rim."] = "Wie viel des Buttons das Icon im Shadow-Stil ausfüllt. Höher = größere Icons mit dünnerem Rand.",
    ["WeakAuras Icons"] = "WeakAuras-Icons",
    ["Skin WeakAuras icons"] = "WeakAuras-Icons skinnen",
    ["WeakAuras style"] = "WeakAuras-Stil",
    ["Style for WeakAuras icons, independent of the action bars."] = "Stil für WeakAuras-Icons, unabhängig von den Aktionsleisten.",
    ["Hide WeakAuras' own border"] = "WeakAuras-eigenen Rahmen ausblenden",
    ["Hides the light border WeakAuras draws on icons, so only our dark rim shows. /reload to fully restore it."] = "Blendet den hellen Rahmen aus, den WeakAuras auf Icons zeichnet, sodass nur unser dunkler Rand zu sehen ist. /reload stellt ihn vollständig wieder her.",
    ["Pick how the action buttons look. Rounded/Circle use an icon mask; Minimal is just the cropped icon."] = "Wähle das Aussehen der Aktionsbuttons. Abgerundet/Kreis nutzen eine Icon-Maske; Minimal ist nur das gecroppte Icon.",
    ["Shadow (dark rounded rim)"] = "Shadow (dunkler abgerundeter Rand)",
    ["Rounded icon (masked corners)"] = "Rundes Icon (maskierte Ecken)",
    ["Square (black edge)"] = "Eckig (schwarzer Rand)",
    ["Square (accent edge)"] = "Eckig (Akzent-Rand)",
    ["Circle"] = "Kreis",
    ["Minimal (icon only)"] = "Minimal (nur Icon)",
    ["Minimal Dark (darkened Blizzard border)"] = "Minimal Dunkel (abgedunkelter Blizzard-Rahmen)",
    ["|cffaaaaaaNote: turning a skin off fully reverts after a /reload.|r"] = "|cffaaaaaaHinweis: Einen Skin ausschalten wird nach /reload vollständig rückgängig gemacht.|r",
    ["Also skin pet & stance buttons"] = "Auch Begleiter- & Haltungs-Buttons skinnen",
    ["Enhances the character panel: iLvL per slot, socket display, shortened enchant text."] = "Erweitert das Charakterfenster: iLvL pro Slot, Sockel-Anzeige, gekürzter Verzauberungstext.",
    ["Show item level per slot"] = "Item-Level pro Slot anzeigen",
    ["Show average item level"] = "Durchschnitts-Item-Level anzeigen",
    ["Show sockets"] = "Sockel anzeigen",
    ["Shorten enchant text (DE/EN)"] = "Verzauberungstext kürzen (DE/EN)",
    ["Example: 'Stamina' -> 'Stam', 'Ausdauer' -> 'Ausd'."] = "Beispiel: 'Stamina' -> 'Stam', 'Ausdauer' -> 'Ausd'.",
    ["Treat rings as enchantable"] = "Ringe als verzauberbar behandeln",
    ["Also shows enchant text on rings (TBC: some professions can enchant rings). /reload required."] = "Zeigt auch Verzauberungstext auf Ringen (TBC: einige Berufe können Ringe verzaubern). /reload erforderlich.",
    ["Text Size"] = "Textgröße",
    ["Item Level Text Size"] = "Item-Level-Textgröße",
    ["Font size of the item level number on each item slot. Takes effect immediately when the character panel is open."] = "Schriftgröße der Item-Level-Zahl auf jedem Item-Slot. Wirkt sofort, wenn das Charakterfenster geöffnet ist.",
    ["Note: Some changes only take full effect after /reload, since the character panel is hooked on load."] = "Hinweis: Einige Änderungen werden erst nach /reload voll wirksam, da das Charakterfenster beim Laden gehookt wird.",
    ["|cffff0000No Ench|r"] = "|cffff0000Keine Verz|r",
    ["|c%siLvL - %d|r"] = "|c%siLvL - %d|r",

    -- GoldTracker
    ["Gold Tracker"] = "Gold-Tracker",
    ["Shows in the backpack gold tooltip how much gold has been gained or spent since the last reset. Per-char persistent."] = "Zeigt im Backpack-Gold-Tooltip an, wie viel Gold seit dem letzten Reset eingenommen oder ausgegeben wurde. Pro Charakter persistent.",
    ["Gold Tracker reset|r. Start = "] = "Gold-Tracker zurückgesetzt|r. Start = ",
    ["Gold Balance|r"] = "Gold-Bilanz|r",
    ["Gained:|r"] = "Eingenommen:|r",
    ["Spent:|r"] = "Ausgegeben:|r",
    ["|cffffffffNet:|r"] = "|cffffffffNetto:|r",
    ["Start:|r"] = "Start:|r",
    ["Now:|r"] = "Jetzt:|r",
    ["Reset with /vcui goldreset|r"] = "Zurücksetzen mit /vcui goldreset|r",
    ["|cffaaaaaaShows in the backpack gold tooltip the balance since the last manual reset:|n  - |cff44ff44Gained|r (quests, loot, vendor sales, mail)|n  - |cffff4444Spent|r (repair, vendor buy, mail cost)|n  - |cffffffffNet|r (+/- since reset)|n|nValues are |cffffffffper-char persistent|r across /reload and logout.|nOffline gold (AH mail, trade) is not counted.|n|nReset: button below or |cffffff00/vcui goldreset|r.|r"] = "|cffaaaaaaZeigt im Backpack-Gold-Tooltip die Bilanz seit dem letzten manuellen Reset:|n  - |cff44ff44Eingenommen|r (Quests, Loot, Anbieter-Verkäufe, Mail)|n  - |cffff4444Ausgegeben|r (Reparatur, Anbieter-Kauf, Mail-Kosten)|n  - |cffffffffNetto|r (+/- seit Reset)|n|nWerte sind |cffffffffpro Charakter persistent|r über /reload und Logout hinweg.|nOffline-Gold (AH-Mail, Trade) wird nicht gezählt.|n|nReset: Button unten oder |cffffff00/vcui goldreset|r.|r",
    ["Reset session"] = "Session zurücksetzen",

    -- VTManaDisplay
    ["Class Specific"] = "Klassenspezifisch",
    ["|cffaaaaaaVampiric Touch mana tracker — shows live how much mana you've given to the group (5% of shadow damage per tick, per mana user).|n|cffffffffReset automatically on combat start.|r|r"] = "|cffaaaaaaVampirberührungs-Mana-Tracker — zeigt live, wie viel Mana du der Gruppe gegeben hast (5% pro Tick des Schattenschadens, pro Mana-Nutzer).|n|cffffffffWird bei Kampfbeginn automatisch zurückgesetzt.|r|r",
    ["|cffff8800These tools are only active while playing a Priest.|r"] = "|cffff8800Diese Tools sind nur aktiv, wenn du einen Priester spielst.|r",
    ["No tools yet"] = "Noch keine Tools",
    ["|cffaaaaaaNo class-specific tools for this class yet. Got an idea? Let me know!|r"] = "|cffaaaaaaNoch keine klassenspezifischen Tools für diese Klasse. Eine Idee? Sag Bescheid!|r",
    ["|cff9b6cffVT Mana:|r %d"] = "|cff9b6cffVT-Mana:|r %d",
    ["|cff9b6cffVT Mana:|r 0"] = "|cff9b6cffVT-Mana:|r 0",
    ["Vampiric Touch: %d mana given to the group."] = "Vampirberührung: %d Mana an die Gruppe abgegeben.",
    ["|cffffffffVT MANA|r"] = "|cffffffffVT-MANA|r",
    ["VT mana frame: x=%.0f, y=%.0f"] = "VT-Mana-Fenster: x=%.0f, y=%.0f",
    ["VT mana mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "VT-Mana-Mover aktiv. |cff9b6cffZiehen|r oder |cff9b6cffPfeiltasten|r (SHIFT = 5px).",
    ["VT mana mover disabled."] = "VT-Mana-Mover deaktiviert.",
    ["Print to chat at combat end"] = "Bei Kampfende in Chat ausgeben",
    ["Writes a summary in chat after each fight."] = "Schreibt nach jedem Kampf eine Zusammenfassung in den Chat.",
    ["Reset manually"] = "Manuell zurücksetzen",
    ["VT mana reset."] = "VT-Mana zurückgesetzt.",

    -- Shadow DoTs
    ["Shadow DoT Tracker"] = "Schatten-DoT-Tracker",
    ["|cffaaaaaaTracks your Shadow DoTs on the target. |cff44ff44Green|r = a buff is up that makes it hit harder if you recast now (TBC snapshot); |cffff4444red|r = about to expire.|r"] = "|cffaaaaaaVerfolgt deine Schatten-DoTs auf dem Ziel. |cff44ff44Grün|r = ein Buff ist aktiv, der bei Neu-Cast mehr Schaden bringt (TBC-Snapshot); |cffff4444rot|r = läuft gleich aus.|r",
    ["Bars"] = "Balken",
    ["Icons"] = "Symbole",
    ["Shadow Word: Pain"] = "Schattenwort: Schmerz",
    ["Vampiric Touch"] = "Vampirberührung",
    ["Devouring Plague"] = "Zehrende Plage",
    ["Warning (seconds left)"] = "Warnung (Sekunden übrig)",
    ["Bar width"] = "Balkenbreite",
    ["Bar height"] = "Balkenhöhe",
    ["Spacing"] = "Abstand",
    ["Color the timer text"] = "Timer-Text einfärben",
    ["Show recast gain %"] = "Neucast-Gewinn in % anzeigen",
    ["Shows how much harder a fresh cast would hit right now (e.g. +12% with a spell power proc up). Negative values mean the running DoT snapshotted stronger — keep it."] = "Zeigt, wie viel härter ein Neucast jetzt treffen würde (z. B. +12% bei aktivem Zaubermacht-Proc). Negative Werte heißen: Der laufende DoT hat stärker gesnapshottet — laufen lassen.",
    ["DoT Tracker"] = "DoT-Tracker",
    ["|cffaaaaaaTracks your DoTs on the target. |cff44ff44Green|r = a buff is up that makes it hit harder if you recast now (TBC snapshot); |cffff4444red|r = about to expire.|r"] = "|cffaaaaaaVerfolgt deine DoTs auf dem Ziel. |cff44ff44Grün|r = ein Buff ist aktiv, der bei Neu-Cast mehr Schaden bringt (TBC-Snapshot); |cffff4444rot|r = läuft gleich aus.|r",
    ["|cffff8800Only active while playing a %s.|r"] = "|cffff8800Nur aktiv, während du %s spielst.|r",
    ["|cffaaaaaaTracks your Warlock DoTs (Corruption, Curse of Agony, Unstable Affliction, Siphon Life, Immolate, Curse of Doom) on the target, with the same recast-snapshot readout as the Priest tracker.|r"] = "|cffaaaaaaVerfolgt deine Hexenmeister-DoTs (Verderbnis, Fluch der Pein, Instabiles Gebrechen, Lebensentzug, Feuerbrand, Fluch der Verdammnis) auf dem Ziel, mit derselben Neucast-Snapshot-Anzeige wie der Priester-Tracker.|r",
    ["Corruption"] = "Verderbnis",
    ["Curse of Agony"] = "Fluch der Pein",
    ["Unstable Affliction"] = "Instabiles Gebrechen",
    ["Siphon Life"] = "Lebensentzug",
    ["Immolate"] = "Feuerbrand",
    ["Curse of Doom"] = "Fluch der Verdammnis",
    ["|cffffffffSHADOW DOTS|r"] = "|cffffffffSCHATTEN-DOTS|r",
    ["|cffffffffDOTS|r"] = "|cffffffffDOTS|r",
    ["Shadow DoTs: x=%.0f, y=%.0f"] = "Schatten-DoTs: x=%.0f, y=%.0f",
    ["Shadow DoTs mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Schatten-DoTs-Mover aktiv. |cff9b6cffZiehen|r oder |cff9b6cffPfeiltasten|r (SHIFT = 5px).",
    ["Shadow DoTs mover disabled."] = "Schatten-DoTs-Mover deaktiviert.",

    -- Character Panel
    ["Mark empty sockets"] = "Leere Sockel markieren",
    ["Adds a red ring around item sockets that have no gem."] = "Zeigt einen roten Ring um Item-Sockel ohne Stein.",
    ["Text shadow (instead of outline)"] = "Text-Schatten (statt Outline)",
    ["Cleaner text with a drop shadow instead of a thick outline."] = "Sauberer Text mit Schatten statt dickem Outline.",

    -- Shaman Totem Timer
    -- MinimapStyle
    ["|cffaaaaaaA modern round minimap with a beveled ring, zone text and clock in a slim pill. Zoom with the mouse wheel. |cffffffffShift+drag the map|r to move it — or use Unlock / the addon's own Edit Mode (/vedit). Blizzard's Edit Mode does not manage this map.|r"] = "|cffaaaaaaEine moderne runde Minimap mit Relief-Ring, Zonentext und Uhr in einer schmalen Pille. Zoomen per Mausrad. |cffffffffShift+Ziehen auf der Karte|r verschiebt sie — oder Entsperren bzw. der addon-eigene Edit Mode (/vedit). Blizzards Edit Mode verwaltet diese Karte nicht.|r",
    ["|cffffffffMINIMAP|r"] = "|cffffffffMINIMAP|r",
    ["Minimap: x=%.0f, y=%.0f"] = "Minimap: x=%.0f, y=%.0f",
    ["Minimap mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Minimap-Verschieber aktiv. |cff9b6cffZiehen|r oder |cff9b6cffPfeiltasten|r (SHIFT = 5px).",
    ["Minimap module disabled — /reload restores the default layout completely."] = "Minimap-Modul deaktiviert — /reload stellt das Standard-Layout vollständig wieder her.",
    ["Minimap ping: %s"] = "Minimap-Ping: %s",
    ["Shape"] = "Form",
    ["Round"] = "Rund",
    ["Accent ring"] = "Akzent-Ring",
    ["Ring color"] = "Ringfarbe",
    ["Accent (purple)"] = "Akzent (Lila)",
    ["Class color"] = "Klassenfarbe",
    ["Custom color"] = "Eigene Farbe",
    ["Theme color"] = "Theme-Farbe",
    ["Dark guild & communities window"] = "Dunkles Gilden- & Gemeinschaftsfenster",
    ["Restyles the guild and communities window to the same dark look. Turning it off needs a /reload."] = "Färbt das Gilden- & Gemeinschaftsfenster im selben dunklen Look. Zum Abschalten ist ein /reload nötig.",
    ["Debuffs on target (yours only)"] = "Debuffs auf dem Ziel (nur eigene)",
    ["Missing buffs (reminder)"] = "Fehlende Buffs (Erinnerung)",
    ["|cffaaaaaaIcons appear while YOUR debuff/DoT is on the target, with its remaining time. Add the debuff by name or ID.|r"] = "|cffaaaaaaIcons erscheinen, solange DEIN Debuff/DoT auf dem Ziel liegt, mit Restzeit. Füge den Debuff per Name oder ID hinzu.|r",
    ["|cffaaaaaaIcons appear while the buff is MISSING on you - a reminder for weapon oils, blessings, food buffs. Add the buff by name or ID.|r"] = "|cffaaaaaaIcons erscheinen, solange dir der Buff FEHLT – als Erinnerung für Waffenöle, Segen, Essensbuffs. Füge den Buff per Name oder ID hinzu.|r",
    ["Tint blue when out of mana"] = "Blau einfärben ohne Mana",
    ["Tint red when out of range"] = "Rot einfärben außer Reichweite",
    ["Needs a target; uses the spell's own range."] = "Benötigt ein Ziel; nutzt die Reichweite des Zaubers.",
    ["Auto-track equipped trinkets"] = "Angelegte Schmuckstücke automatisch verfolgen",
    ["Keeps both equipped trinkets in this group automatically - they follow along when you swap trinkets."] = "Hält beide angelegten Schmuckstücke automatisch in dieser Gruppe – beim Wechseln ziehen sie mit um.",
    ["Duplicate"] = "Duplizieren",
    ["Copies the selected group with all entries and layout settings."] = "Kopiert die gewählte Gruppe mit allen Einträgen und Layout-Einstellungen.",
    ["(copy)"] = "(Kopie)",
    ["Show tooltips on hover"] = "Tooltips beim Überfahren anzeigen",
    ["The icons then intercept the mouse - leave this off if the bar sits over clickable UI."] = "Die Icons fangen dann die Maus ab – aus lassen, wenn die Leiste über klickbarer Oberfläche liegt.",
    ["Copy the link with Ctrl+C:"] = "Link mit Strg+C kopieren:",
    ["Click: copy link"] = "Klick: Link kopieren",
    ["|cffaaaaaaColors everything that is purple today in the color of your choice - sidebar, borders, highlights, bars. A /reload applies it everywhere.|r"] = "|cffaaaaaaFärbt alles, was heute lila ist, in deiner Wunschfarbe – Sidebar, Rahmen, Hervorhebungen, Leisten. Ein /reload übernimmt sie überall.|r",
    ["Preset"] = "Vorlage",
    ["Purple (default)"] = "Lila (Standard)",
    ["Turquoise"] = "Türkis",
    ["Pink"] = "Pink",
    ["Orange"] = "Orange",
    ["Theme color changed. /reload applies it to everything (elements already drawn keep the old color until then)."] = "Theme-Farbe geändert. /reload übernimmt sie überall (bereits gezeichnete Elemente behalten die alte Farbe bis dahin).",
    ["Custom ring color"] = "Eigene Ringfarbe",
    ["A thin colored line around the dark ring (round shape only)."] = "Eine dünne farbige Linie um den dunklen Ring (nur bei runder Form).",
    ["Zone panel"] = "Zonen-Leiste",
    ["Zone text and clock"] = "Zonentext und Uhr",
    ["Above the map"] = "Über der Karte",
    ["Below the map"] = "Unter der Karte",
    ["Hidden"] = "Ausgeblendet",
    ["Show clock"] = "Uhr anzeigen",
    ["Show date"] = "Datum anzeigen",
    ["Shows the date next to the clock. Click it to open the calendar."] = "Zeigt das Datum neben der Uhr. Klick öffnet den Kalender.",
    ["Buttons"] = "Knöpfe",
    ["Zoom buttons (+/-)"] = "Zoom-Buttons (+/-)",
    ["Shows a flat + and - on the right edge of the map. The mouse wheel always zooms too."] = "Zeigt ein flaches + und - am rechten Kartenrand. Das Mausrad zoomt weiterhin.",
    ["Show day/night button"] = "Tag/Nacht-Knopf anzeigen",
    ["Restyle addon buttons"] = "Addon-Knöpfe umgestalten",
    ["Removes the gold borders from other addons' minimap buttons and gives them a clean round look. Turning this off needs a /reload."] = "Entfernt die goldenen Ränder der Minimap-Knöpfe anderer Addons und gibt ihnen einen klaren runden Look. Zum Deaktivieren ist ein /reload nötig.",
    ["Addon buttons only on mouseover"] = "Addon-Knöpfe nur bei Mouseover",
    ["Hides other addons' minimap buttons until the mouse is over the minimap."] = "Blendet die Minimap-Knöpfe anderer Addons aus, bis die Maus über der Minimap ist.",
    ["Ping in chat"] = "Ping im Chat",
    ["Prints who pinged the minimap."] = "Zeigt im Chat an, wer die Minimap angepingt hat.",
    ["Totem Bar"] = "Totem-Leiste",
    ["|cffaaaaaa|cffffffffLeft-click|r an icon to (re)cast that element's totem, |cffffffffhover|r a slot to pick which totem from the icon list, |cffffffffmiddle-click|r to recall all totems. The icon border turns red just before the totem expires.|r"] = "|cffaaaaaa|cffffffffLinksklick|r = Totem des Elements (neu) stellen, |cffffffffmit der Maus über einen Slot|r = Totem aus der Icon-Liste wählen, |cffffffffMittelklick|r = alle Totems einsammeln. Der Icon-Rahmen wird rot kurz bevor das Totem ausläuft.|r",
    ["|cffff8800Only active while playing a Shaman.|r"] = "|cffff8800Nur aktiv, wenn du einen Schamanen spielst.|r",
    ["Totem set"] = "Totem-Set",
    ["Active set"] = "Aktives Set",
    ["Set name"] = "Set-Name",
    ["New set"] = "Neues Set",
    ["Delete set"] = "Set löschen",
    ["(auto: last cast)"] = "(auto: zuletzt gestellt)",
    ["|cff888888(cast a totem to add it here)|r"] = "|cff888888(stelle ein Totem, um es hier hinzuzufügen)|r",
    ["Shown elements"] = "Angezeigte Elemente",
    ["Sound before a totem expires"] = "Ton bevor ein Totem ausläuft",
    ["Icon border (action-bar style)"] = "Icon-Rahmen (Action-Leisten-Stil)",
    ["Style"] = "Stil",
    ["VuloUI (dark)"] = "VuloUI (dunkel)",
    ["Classic (metal)"] = "Klassisch (Metall)",
    ["Flyout direction"] = "Flyout-Richtung",
    ["Which way the totem picker opens when you hover a slot. Automatic picks the side away from the screen edge."] = "In welche Richtung sich die Totem-Auswahl öffnet, wenn du über einen Slot fährst. Automatisch wählt die vom Bildschirmrand abgewandte Seite.",
    ["Automatic"] = "Automatisch",
    ["Upwards"] = "Nach oben",
    ["Downwards"] = "Nach unten",
    ["To the left"] = "Nach links",
    ["To the right"] = "Nach rechts",
    ["Open flyout in combat"] = "Flyout im Kampf öffnen",
    ["Tooltip with cooldown on hover"] = "Tooltip mit Abklingzeit beim Hovern",
    ["Hovering a totem slot or a picker icon shows the totem name and its remaining cooldown."] = "Beim Drüberfahren über einen Totem-Slot oder ein Auswahl-Icon werden Totemname und verbleibende Abklingzeit angezeigt.",
    ["Off = hovering a slot never opens the totem picker while you are fighting (clicks still cast). The picker now also closes itself on mouse-out and after every cast, even in combat."] = "Aus = im Kampf öffnet sich die Totem-Auswahl nicht mehr beim Drüberfahren (Klicks wirken weiterhin). Die Auswahl schließt sich außerdem von selbst beim Verlassen mit der Maus und nach jedem Wurf — auch im Kampf.",
    ["Fire"]  = "Feuer",
    ["Earth"] = "Erde",
    ["Water"] = "Wasser",
    ["Air"]   = "Luft",
    ["|cffffffffTOTEMS|r"] = "|cffffffffTOTEMS|r",
    ["Totems: x=%.0f, y=%.0f"] = "Totems: x=%.0f, y=%.0f",
    ["Totem timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Totem-Mover aktiv. |cff9b6cffZiehen|r oder |cff9b6cffPfeiltasten|r (SHIFT = 5px).",
    ["Totem timer mover disabled."] = "Totem-Mover deaktiviert.",
    ["|cffff5555Class tool error:|r %s"] = "|cffff5555Klassen-Tool-Fehler:|r %s",

    -- Edit Mode / Unlock Mode
    ["EDIT MODE"] = "EDIT-MODUS",
    ["Edit Mode"] = "Edit-Modus",
    ["Open Edit Mode"] = "Edit-Modus öffnen",
    ["Close Edit Mode and lock all windows. Your changes stay applied."] = "Edit-Modus schließen und alle Fenster sperren. Deine Änderungen bleiben erhalten.",
    ["Keep the current arrangement and carry on editing. Discard then returns to this point instead of to how things looked when Edit Mode opened."] = "Sichert die aktuelle Anordnung und lässt dich weiterarbeiten. Verwerfen springt danach hierher zurück statt zum Stand beim Öffnen des Edit-Modus.",
    ["Window positions saved."] = "Fensterpositionen gesichert.",
    ["Exit"] = "Beenden",
    ["Close"] = "Schließen",
    ["Reset"] = "Zurücksetzen",
    ["Reset this frame"] = "Dieses Fenster zurücksetzen",
    ["Reset all VuloUI window positions to the screen centre."] = "Alle VuloUI-Fensterpositionen auf die Bildschirmmitte zurücksetzen.",
    ["Reset all VuloUI window positions to the screen centre?"] = "Alle VuloUI-Fensterpositionen auf die Bildschirmmitte zurücksetzen?",
    ["Done — lock everything"] = "Fertig — alles sperren",

    ["Grid"] = "Raster",
    ["Snap"] = "Einrasten",
    ["Show an alignment grid."] = "Ein Ausrichtungsraster anzeigen.",
    ["Snap windows to the grid while dragging."] = "Fenster beim Ziehen am Raster einrasten.",
    ["%d frames here - hold Alt to cycle"] = "%d Fenster hier – Alt halten zum Durchschalten",
    ["Drag a box, or hover it and use the arrow keys (Shift = 5px). Shift+click to select several and drag them together."] = "Ein Kästchen ziehen, oder darüberfahren und die Pfeiltasten nutzen (Umschalt = 5px). Umschalt+Klick wählt mehrere aus und zieht sie gemeinsam.",
    ["Which screen point the frame is pinned to (keeps it put across resolution changes)."] = "An welchem Bildschirmpunkt das Fenster verankert ist (hält es bei Auflösungsänderungen an Ort und Stelle).",

    ["ANCHOR"] = "ANKER",
    ["POSITION"] = "POSITION",
    ["SCALE"] = "SKALIERUNG",
    ["FREE MOVE"] = "FREI",
    ["FOLLOW WINDOW"] = "FOLGT FENSTER",
    ["Pins this window to another one - it then moves along whenever that window is moved. Dragging this window keeps the pin and just updates the distance."] = "Heftet dieses Fenster an ein anderes – es wandert dann mit, sobald das andere Fenster bewegt wird. Dieses Fenster selbst zu ziehen behält die Verbindung und passt nur den Abstand an.",
    ["Not possible - that would create a loop."] = "Nicht möglich – das würde eine Schleife erzeugen.",
    ["Anchor to window..."] = "An Fenster ankern...",
    ["WIDTH LIKE"] = "BREITE WIE",
    ["HEIGHT LIKE"] = "HÖHE WIE",
    ["Takes its width from another window and keeps it."] = "Übernimmt die Breite eines anderen Fensters und behält sie bei.",
    ["Takes its height from another window and keeps it."] = "Übernimmt die Höhe eines anderen Fensters und behält sie bei.",
    ["This window sets its own size - the match will not stick."] = "Dieses Fenster legt seine Größe selbst fest – die Angleichung hält nicht.",
    ["Drag a box, or hover it and use the arrow keys (Shift = 5px). Hold Shift while dragging to lock one axis. Shift+right-click hides a box that is in the way."] = "Ein Kästchen ziehen, oder darüberfahren und die Pfeiltasten nutzen (Umschalt = 5px). Umschalt beim Ziehen sperrt eine Achse. Umschalt+Rechtsklick blendet ein störendes Kästchen aus.",
    ["Then click any window to anchor this one to it."] = "Danach ein beliebiges Fenster anklicken, an das dieses angedockt wird.",
    ["Click a window to anchor it (right-click to cancel)."] = "Ein Fenster anklicken, an das angedockt werden soll (Rechtsklick bricht ab).",
    ["ANCHOR SIDE"] = "ANKERSEITE",
    ["GAP"] = "ABSTAND",
    ["Distance from that edge, in pixels. 0 is flush."] = "Abstand zu dieser Kante, in Pixeln. 0 heißt bündig.",
    ["Docks this window to that side of the target and centres it there. 'Centered' does not move it - it only travels along. The gap is kept edge-to-edge, so it survives either window being resized."] = "Dockt dieses Fenster an die gewählte Seite des Zielfensters an und zentriert es dort. 'Mittig' verschiebt nichts — es wird nur mitgeführt. Der Abstand wird von Kante zu Kante gehalten und übersteht so eine Größenänderung beider Fenster.",
    ["Centered"] = "Mittig",
    ["Top of"] = "Oben",
    ["Bottom of"] = "Unten",
    ["Discard"] = "Verwerfen",
    ["Discard changes and revert every window to how it was when Edit Mode opened."] = "Verwirft die Änderungen und stellt jedes Fenster so wieder her, wie es beim Öffnen des Edit-Modus war.",
    ["Discard all changes made since opening Edit Mode?"] = "Alle seit dem Öffnen des Edit-Modus vorgenommenen Änderungen verwerfen?",
    ["Pin this frame to a screen edge/corner so it stays put across resolution changes. Off keeps it centred."] = "Verankert das Fenster an einer Bildschirmkante/-ecke, damit es bei Auflösungsänderungen an Ort und Stelle bleibt. Aus = bleibt zentriert.",
    ["Leave this window unlocked so you can still drag it after closing Edit Mode. Stays unlocked through /reload."] = "Lässt dieses Fenster entsperrt, sodass du es auch nach dem Schließen des Edit-Modus noch ziehen kannst. Bleibt über /reload hinweg entsperrt.",

    ["LAYOUTS"] = "LAYOUTS",
    ["Layouts"] = "Layouts",
    ["SAVED"] = "GESPEICHERT",
    ["No layouts saved"] = "Keine Layouts gespeichert",
    ["No layout selected."] = "Kein Layout ausgewählt.",
    ["Save, load, export and import named window layouts."] = "Benannte Fenster-Layouts speichern, laden, exportieren und importieren.",
    ["Save your window arrangement, then load or share it any time."] = "Speichere deine Fensteranordnung und lade oder teile sie jederzeit.",
    ["Pick a saved layout to load, delete or export."] = "Wähle ein gespeichertes Layout zum Laden, Löschen oder Exportieren.",
    ["Save current as..."] = "Aktuelles speichern als...",
    ["Name for this layout:"] = "Name für dieses Layout:",
    ["Delete layout '%s'?"] = "Layout '%s' löschen?",
    ["Layout '%s' saved."] = "Layout '%s' gespeichert.",
    ["Applied layout '%s' (%d frames)."] = "Layout '%s' angewendet (%d Fenster).",
    ["Layout '%s' imported."] = "Layout '%s' importiert.",
    ["Import"] = "Importieren",
    ["Export"] = "Exportieren",
    ["Imported"] = "Importiert",
    ["Import failed (%s)."] = "Import fehlgeschlagen (%s).",
    ["Paste a layout string and confirm:"] = "Layout-Text einfügen und bestätigen:",
    ["Copy this string (Ctrl+A, Ctrl+C):"] = "Diesen Text kopieren (Strg+A, Strg+C):",

    ["click to edit"] = "Klicken zum Bearbeiten",
    ["Move it in the unified Edit Mode (/vedit)."] = "Im vereinheitlichten Edit-Modus (/vedit) verschieben.",
    ["Drag the combat-text box in the unified Edit Mode (/vedit)."] = "Das Kampftext-Kästchen im vereinheitlichten Edit-Modus (/vedit) ziehen.",
    ["|cffffffffARENA FRAMES|r"] = "|cffffffffARENA-FRAMES|r",
    ["|cff44ff44Edit Mode is ON.|r Close this window to reach the boxes."] = "|cff44ff44Edit-Modus ist AN.|r Schließe dieses Fenster, um an die Kästchen zu gelangen.",
    ["|cffaaaaaaMove everything in one editor: VuloUI windows and Blizzard's frames (player, target, focus, minimap, buffs). They snap to a shared grid.|r"] = "|cffaaaaaaAlles in einem Editor verschieben: VuloUI-Fenster und Blizzards Frames (Spieler, Ziel, Fokus, Minimap, Buffs). Sie rasten an einem gemeinsamen Raster ein.|r",
    ["|cff888888• Drag a purple box to move that frame.|n• Hover a box, then arrow keys fine-tune (SHIFT = 5px).|n• Right-click a box for exact X / Y.|n• |cffffffff/vedit|r toggles Edit Mode too.|r"] = "|cff888888• Ein lila Kästchen ziehen, um das Fenster zu verschieben.|n• Über ein Kästchen fahren, dann mit den Pfeiltasten feinjustieren (UMSCHALT = 5px).|n• Rechtsklick auf ein Kästchen für genaues X / Y.|n• |cffffffff/vedit|r schaltet ebenfalls den Edit-Modus um.|r",
    ["Enable 'Target and Focus' in Blizzard's Edit Mode settings, then /reload, so VuloUI can move the target/focus frame."] = "Aktiviere „Ziel und Fokus“ in den Einstellungen von Blizzards Bearbeitungsmodus und lade dann mit /reload neu, damit VuloUI das Ziel-/Fokusfenster verschieben kann.",

    -- Dark Mode
    ["Dark Mode"] = "Dunkelmodus",
    ["Darkens and desaturates Blizzard's default UI artwork (unit frames, minimap, action bars) to a neutral dark tone. Keeps Blizzard's frames — it just re-tints them."] = "Verdunkelt und entsättigt Blizzards Standard-Grafik (Einheitenfenster, Minimap, Aktionsleisten) zu einem neutralen dunklen Ton. Behält Blizzards Frames — es färbt sie nur um.",
    ["|cffaaaaaaDarkens and desaturates Blizzard's default artwork — unit frames, minimap and action bars — to a neutral dark tone. Reversible: turn it off and the gold look returns.|r"] = "|cffaaaaaaVerdunkelt und entsättigt Blizzards Standard-Grafik — Einheitenfenster, Minimap und Aktionsleisten — zu einem neutralen dunklen Ton. Umkehrbar: ausschalten und der goldene Look kehrt zurück.|r",
    ["Look"] = "Aussehen",
    ["Desaturate (greyscale)"] = "Entsättigen (Graustufen)",
    ["Strips the colour out of the artwork before tinting, for a true greyscale look. Off keeps a hint of the original hue."] = "Entzieht der Grafik vor dem Einfärben die Farbe, für echte Graustufen. Aus behält einen Hauch des ursprünglichen Farbtons.",
    ["Tint colour"] = "Tönungsfarbe",
    ["Apply to"] = "Anwenden auf",
    ["Unit frames"] = "Einheitenfenster",
    ["Player, target, focus, pet and party frame borders."] = "Ränder von Spieler-, Ziel-, Fokus-, Begleiter- und Gruppenfenstern.",
    ["Minimap border, compass, zoom and tracking buttons."] = "Minimap-Rand, Kompass, Zoom- und Verfolgen-Knöpfe.",
    ["Action bar artwork"] = "Aktionsleisten-Grafik",
    ["The gryphons and the metal action-bar background."] = "Die Greifen und der metallene Aktionsleisten-Hintergrund.",
    ["Action button borders"] = "Aktionsknopf-Ränder",
    ["Also tints the border ring around every action button. Optional — leave off if it looks too flat."] = "Färbt auch den Rahmen um jeden Aktionsknopf. Optional — auslassen, wenn es zu flach wirkt.",
    ["Action bar dark border"] = "Dunkler Aktionsleisten-Rand",
    ["Adds the dark Button Skin border to the action bars while Dark Mode is on (and removes it when Dark Mode turns off). You can also switch it on with Dark Mode off in the Button Skin module."] = "Fügt den dunklen Button-Skin-Rand zu den Aktionsleisten hinzu, solange der Dunkelmodus an ist (und entfernt ihn, wenn der Dunkelmodus ausgeht). Du kannst ihn auch bei ausgeschaltetem Dunkelmodus im Modul „Button-Skin“ einschalten.",
    ["Bag slots"] = "Taschenplätze",
    ["Tints the backpack, bag and keyring button borders."] = "Färbt die Ränder von Rucksack-, Taschen- und Schlüsselbund-Knopf.",
    ["|cffaaaaaaNote: if the Player & Target Frame module's |cffffffffThreat glow|r is on, threat colouring takes over the target/focus border while you have aggro — that's intended.|r"] = "|cffaaaaaaHinweis: Wenn beim Modul „Spieler- & Zielfenster“ das |cffffffffBedrohungs-Leuchten|r aktiv ist, übernimmt die Bedrohungsfärbung den Ziel-/Fokus-Rand, solange du Aggro hast — das ist beabsichtigt.|r",
    ["|cffaaaaaaAction button borders are also managed by the Button Skin module — if that's on, it controls the buttons instead.|r"] = "|cffaaaaaaAktionsknopf-Ränder werden auch vom Modul „Button-Skin“ verwaltet — wenn das an ist, steuert es stattdessen die Knöpfe.|r",

    -- Chat
    ["Chat"] = "Chat",
    ["Polishes Blizzard's chat: a dark panel with an icon sidebar, timestamps, class-coloured names, clickable links, dark tabs, idle fade and history that survives a /reload. Every part is optional."] = "Verbessert Blizzards Chat: ein dunkles Panel mit Icon-Sidebar, Zeitstempel, Namen in Klassenfarbe, klickbare Links, dunkle Tabs, Abblenden bei Inaktivität und Verlauf, der ein /reload übersteht. Jeder Teil ist optional.",
    ["|cffaaaaaaPolishes Blizzard's own chat — nothing is replaced, so it stays light and compatible. Every option below is independent.|r"] = "|cffaaaaaaVerbessert Blizzards eigenen Chat — nichts wird ersetzt, daher bleibt es leichtgewichtig und kompatibel. Jede Option unten ist unabhängig.|r",
    ["Timestamps"] = "Zeitstempel",
    ["Show timestamps"] = "Zeitstempel anzeigen",
    ["Prefixes each line with the time, using the game's own timestamp setting."] = "Stellt jeder Zeile die Uhrzeit voran, über die spieleigene Zeitstempel-Einstellung.",
    ["Time format"] = "Zeitformat",
    ["Names & links"] = "Namen & Links",
    ["Class-coloured names"] = "Namen in Klassenfarbe",
    ["Colours player names by their class in say, party, raid, guild, whisper and channels."] = "Färbt Spielernamen nach Klasse in Sagen, Gruppe, Schlachtzug, Gilde, Flüstern und Kanälen.",
    ["Clickable links"] = "Klickbare Links",
    ["Turns web links into clickable links that open a copy box."] = "Macht Web-Links anklickbar und öffnet beim Klick ein Kopierfeld.",
    ["Style chat tabs"] = "Chat-Tabs stylen",
    ["Flat dark tab background with an accent underline on the active tab."] = "Flacher dunkler Tab-Hintergrund mit Akzent-Unterstrich am aktiven Tab.",
    ["Tab label size"] = "Tab-Beschriftungsgröße",
    ["One uniform font size for every chat tab label."] = "Eine einheitliche Schriftgröße für jede Chat-Tab-Beschriftung.",
    ["Chat font size (0 = Blizzard)"] = "Chat-Schriftgröße (0 = Blizzard)",
    ["Scrollback (lines per window)"] = "Zeilenspeicher (pro Fenster)",
    ["How many lines each chat window keeps for scrolling (Blizzard default: 128). More lines use a little more memory; changing this clears the currently shown lines once."] = "Wie viele Zeilen jedes Chatfenster zum Zurückscrollen behält (Blizzard-Standard: 128). Mehr Zeilen brauchen etwas mehr Speicher; eine Änderung leert die aktuell angezeigten Zeilen einmalig.",
    ["Item levels in chat links"] = "Itemlevel in Chat-Links",
    ["Appends the item level to equipment links: [Sword] becomes [Sword (45)]."] = "Hängt das Itemlevel an Ausrüstungslinks an: aus [Schwert] wird [Schwert (45)].",
    ["Overrides the message font size for every chat window. 0 keeps each window's own Blizzard size."] ="Überschreibt die Nachrichten-Schriftgröße für jedes Chat-Fenster. 0 behält die jeweilige Blizzard-Größe bei.",
    ["Panel opacity (%)"] = "Panel-Deckkraft (%)",
    ["Transparency of the dark background panel behind the chat."] = "Transparenz des dunklen Hintergrund-Panels hinter dem Chat.",
    ["Indent wrapped lines"] = "Umbruchzeilen einrücken",
    ["Wraps long messages with continuation lines indented under the message start, for a cleaner column."] = "Bricht lange Nachrichten um und rückt Folgezeilen unter dem Nachrichtenanfang ein — für eine sauberere Spalte.",
    ["Copy button"] = "Kopier-Knopf",
    ["A small button above the chat that opens a copyable text box of the current window."] = "Ein kleiner Knopf über dem Chat, der ein kopierbares Textfeld des aktuellen Fensters öffnet.",
    ["Idle fade"] = "Abblenden bei Inaktivität",
    ["Fade chat when idle"] = "Chat bei Inaktivität abblenden",
    ["Dims the chat after a while with no activity. A new message, hovering it or typing brings it back."] = "Blendet den Chat nach einer Weile ohne Aktivität ab. Eine neue Nachricht, Drüberfahren oder Tippen holt ihn zurück.",
    ["Idle delay (seconds)"] = "Inaktivitäts-Verzögerung (Sekunden)",
    ["Faded opacity (%)"] = "Abgeblendete Deckkraft (%)",
    ["History"] = "Verlauf",
    ["Keep chat history"] = "Chatverlauf behalten",
    ["Remembers recent chat per character and re-shows it after a /reload."] = "Merkt sich den jüngsten Chat pro Charakter und zeigt ihn nach einem /reload wieder an.",
    ["Lines to keep"] = "Zu behaltende Zeilen",
    ["Clear history"] = "Verlauf löschen",
    ["Chat history cleared."] = "Chatverlauf gelöscht.",
    ["--- chat history ---"] = "--- Chatverlauf ---",
    ["Copy"] = "Kopieren",
    ["Copy chat"] = "Chat kopieren",
    ["Link"] = "Link",
    ["Ctrl+A to select all, Ctrl+C to copy."] = "Strg+A zum Auswählen, Strg+C zum Kopieren.",
    ["Scroll to bottom"] = "Nach unten scrollen",
    ["|cffaaaaaaThe panel, input and sidebar reposition Blizzard's chat. Turning them off here hides them immediately; a |cffffffff/reload|r restores the exact original positions.|r"] = "|cffaaaaaaPanel, Eingabezeile und Sidebar positionieren Blizzards Chat um. Sie hier auszuschalten blendet sie sofort aus; ein |cffffffff/reload|r stellt die exakten Originalpositionen wieder her.|r",
    ["Dark background panel"] = "Dunkles Hintergrund-Panel",
    ["A dark panel behind the chat and input line, with the tab bar above it — one cohesive block."] = "Ein dunkles Panel hinter Chat und Eingabezeile, mit der Tab-Leiste darüber — ein zusammenhängender Block.",
    ["Top fade"] = "Oberer Verlauf",
    ["Fades old lines into the panel at the top edge of the chat."] = "Blendet alte Zeilen am oberen Chat-Rand ins Panel aus.",
    ["Icon sidebar"] = "Icon-Sidebar",
    ["A slim bar left of the chat with copy, settings, new-window and scroll-to-bottom icons."] = "Eine schmale Leiste links vom Chat mit Kopier-, Einstellungs-, Neues-Fenster- und Nach-unten-scrollen-Icons.",
    ["Show online friends"] = "Online-Freunde anzeigen",
    ["Show how many friends are online at the top of the sidebar; click the icon to open the friends list."] = "Zeigt oben in der Seitenleiste, wie viele Freunde online sind; Klick auf das Icon öffnet die Freundesliste.",
    ["Friends online"] = "Freunde online",
    ["New chat window"] = "Neues Chat-Fenster",
    ["Create new chat window"] = "Neues Chat-Fenster erstellen",
    ["This client can't create extra chat windows."] = "Dieser Client kann keine zusätzlichen Chat-Fenster erstellen.",
    ["Use VuloUI font"] = "VuloUI-Schrift verwenden",
    ["Applies the VuloUI font to the chat text, tabs and input line."] = "Wendet die VuloUI-Schrift auf Chat-Text, Tabs und Eingabezeile an.",
    ["Copy button (standalone)"] = "Kopier-Knopf (einzeln)",
    ["A small copy button above the chat. Off by default since the sidebar already has a copy icon; turn the sidebar off to use this instead."] = "Ein kleiner Kopier-Knopf über dem Chat. Standardmäßig aus, da die Sidebar bereits ein Kopier-Icon hat; schalte die Sidebar aus, um stattdessen diesen zu nutzen.",

    -- Bags
    ["Bags"] = "Taschen",
    ["Inventory"] = "Inventar",
    ["Items"] = "Gegenstände",
    ["Hide"] = "Verbergen",
    ["Show"] = "Anzeigen",
    ["Color item levels by quality"] = "Gegenstandsstufen nach Qualität färben",
    ["Tints the item level number in the item's quality color instead of plain white."] = "Färbt die Gegenstandsstufe in der Qualitätsfarbe statt einfach Weiß.",
    ["%d free"] = "%d frei",
    ["|cffaaaaaaOne window for all your bags. Press your bag key (default B) to open it. Type in the search box to find items; click the sort button to tidy up. At a banker, your bank opens in a matching window.|r"] = "|cffaaaaaaEin Fenster für alle deine Taschen. Drücke deine Taschen-Taste (Standard B), um es zu öffnen. Tippe im Suchfeld, um Gegenstände zu finden; klicke den Sortier-Knopf zum Aufräumen. Beim Bankier öffnet sich deine Bank in einem passenden Fenster.|r",
    ["Quality borders"] = "Qualitätsränder",
    ["Colour each item's border by its rarity."] = "Färbt den Rand jedes Items nach seiner Seltenheit.",
    ["Item count text size"] = "Anzahl-Textgröße",
    ["Reset bag position"] = "Taschen-Position zurücksetzen",
    ["Search & sorting"] = "Suche & Sortierung",
    ["Show search box"] = "Suchfeld anzeigen",
    ["A search field in the window header. Dims items that don't match."] = "Ein Suchfeld in der Fensterkopfzeile. Dimmt Gegenstände, die nicht passen.",
    ["Show sort button"] = "Sortier-Knopf anzeigen",
    ["A sort button in the window header. Right-click it to reverse the order."] = "Ein Sortier-Knopf in der Fensterkopfzeile. Rechtsklick kehrt die Reihenfolge um.",
    ["Reverse sort order"] = "Sortierreihenfolge umkehren",
    ["Sort from low to high quality instead of high to low."] = "Von niedriger zu hoher Qualität sortieren statt umgekehrt.",
    ["Sort bags"] = "Taschen sortieren",
    ["Bank contents"] = "Bankinhalt",
    ["Shows what your bank holds - from the last bank visit, viewable anywhere."] = "Zeigt, was in deiner Bank liegt – vom letzten Bankbesuch, überall einsehbar.",
    ["As of: %s"] = "Stand: %s",
    ["%d free slots"] = "%d freie Plätze",
    ["No bank visit recorded on this character yet."] = "Auf diesem Charakter wurde noch kein Bankbesuch aufgezeichnet.",
    ["Right-click to toggle sort order."] = "Rechtsklick kehrt die Reihenfolge um.",
    ["Can't sort bags in combat."] = "Taschen können im Kampf nicht sortiert werden.",
    ["Sort order: reversed"] = "Sortierung: umgekehrt",
    ["Sort order: normal"] = "Sortierung: normal",
    ["Sort order"] = "Sortierreihenfolge",
    ["How the sort button arranges items. 'Blizzard' groups by category like the default UI; the others are a flat order."] = "Wie der Sortier-Knopf Gegenstände anordnet. 'Blizzard' gruppiert nach Kategorie wie die Standard-UI; die anderen sind eine flache Reihenfolge.",
    ["Blizzard (category)"] = "Blizzard (Kategorie)",
    ["Quality"] = "Qualität",
    ["Item type"] = "Gegenstandstyp",
    ["Sort in the opposite direction."] = "In umgekehrter Richtung sortieren.",
    ["Item level"] = "Gegenstandsstufe",
    ["Off"] = "Aus",
    ["Sort categories by"] = "Kategorien sortieren nach",
    ["Display-only ordering of the items inside each category section. Never moves anything in your bags."] = "Reine Anzeige-Sortierung der Gegenstände innerhalb jeder Kategorie. Bewegt nichts in deinen Taschen.",
    ["Show free slots (OneBag)"] = "Freie Plätze anzeigen (OneBag)",
    ["OneBag view: show the empty bag slots after the items, so you can drop things onto them directly."] = "OneBag-Ansicht: zeigt die leeren Taschenplätze hinter den Gegenständen, sodass du Sachen direkt hineinziehen kannst.",
    ["Fixed slot order (OneBag)"] = "Feste Platz-Reihenfolge (OneBag)",
    ["Shows every slot in its natural bag order with the empty slots inline — items stay visually where you drop them, like one big real bag. Needs the free-slots option above."] = "Zeigt jeden Platz in seiner natürlichen Taschen-Reihenfolge, leere Plätze mittendrin — Gegenstände bleiben sichtbar dort liegen, wo du sie hinziehst, wie in einer großen echten Tasche. Benötigt die Option für freie Plätze darüber.",
    ["Junk marker (C)"] = "Müll-Markierung (C)",
    ["Marks vendor trash with a purple C in the icon corner - grey items a merchant pays gold for."] = "Markiert Händlerware mit einem lila C in der Icon-Ecke — graue Gegenstände, für die ein Händler Gold zahlt.",
    ["BoE/BoU markers"] = "BoE/BoU-Kennzeichnung",
    ["Tags equipment that is still tradeable (binds on equip or use, not yet soulbound) - handy for banking and the auction house."] = "Kennzeichnet Ausrüstung, die noch handelbar ist (beim Anlegen oder Benutzen gebunden, noch nicht seelengebunden) — praktisch fürs Bankieren und Auktionshaus.",
    ["Categories"] = "Kategorien",
    ["Group items into categories"] = "Gegenstände in Kategorien gruppieren",
    ["Show items in labelled sections (Quest, Consumables, Armor...). Off = one flat grid."] = "Gegenstände in beschrifteten Abschnitten anzeigen (Quest, Verbrauchbar, Rüstung...). Aus = ein einzelnes Raster.",
    ["Hide empty categories"] = "Leere Kategorien ausblenden",
    ["Don't show a section header for a category that has no items."] = "Keine Abschnittsüberschrift für Kategorien ohne Gegenstände anzeigen.",
    ["Consumables"] = "Verbrauchbar",
    ["Weapons"] = "Waffen",
    ["Armor"] = "Rüstung",
    ["Trade Goods"] = "Handelswaren",
    ["Ammo"] = "Munition",
