    -- Nameplates
    ["Custom enemy & NPC nameplates with a live preview: health bar, cast bar, name and health text, reaction / class colours, target highlight and threat."] = "Eigene Namensplaketten für Gegner und NPCs mit Live-Vorschau: Lebensleiste, Zauberleiste, Name und Lebenstext, Reaktions-/Klassenfarben, Ziel-Hervorhebung und Bedrohung.",
    ["|cffaaaaaaCustom nameplates for enemies and NPCs. Configure below — the live preview updates as you change each option.|r"] = "|cffaaaaaaEigene Namensplaketten für Gegner und NPCs. Stelle unten alles ein — die Live-Vorschau aktualisiert sich bei jeder Änderung.|r",
    ["Live preview"] = "Live-Vorschau",
    ["Target Dummy"] = "Zielattrappe",
