    ["Bar opacity"] = "Leisten-Deckkraft",
    ["Show empty buttons"] = "Leere Buttons anzeigen",
    ["Off hides empty slots; they reappear automatically while you drag an ability."] = "Aus blendet leere Plätze aus; beim Ziehen einer Fähigkeit erscheinen sie automatisch wieder.",
    ["Click through"] = "Durchklickbar",
    ["The bar ignores the mouse entirely — clicks go through it. Keybinds still work."] = "Die Leiste ignoriert die Maus komplett — Klicks gehen hindurch. Tastenbelegungen funktionieren weiter.",
