    ["0 = default size. Requires cooldown numbers to be enabled in the game options."] = "0 = Standardgröße. Erfordert aktivierte Cooldown-Zahlen in den Spieloptionen.",
    ["Cooldown & look"] = "Cooldown & Optik",
    ["|cffff5555Quick keybind mode is not available on this client.|r"] = "|cffff5555Der Schnell-Belegen-Modus ist auf diesem Client nicht verfügbar.|r",
