    ["Tick where your interrupt becomes ready"] = "Markierung, wo dein Unterbrechen bereit wird",
    ["Marks the spot on the enemy cast bar where YOUR interrupt comes off cooldown — everything after the tick is kickable."] = "Markiert die Stelle auf der gegnerischen Castleiste, an der DEIN Unterbrechen vom Cooldown kommt — alles nach der Markierung ist unterbrechbar.",
