    ["Mail emptied: looted %s%s."] = "Post geleert: %s%s erbeutet.",
    ["No contacts yet"] = "Noch keine Kontakte",
    ["No groups forming right now."] = "Gerade sucht niemand eine Gruppe.",
    ["Not all mail is shown — reopen the mailbox and click again for the rest."] = "Es wird nicht die gesamte Post angezeigt — Briefkasten neu öffnen und nochmal klicken.",
    ["One-key reel (soft-target interact)"] = "Ein-Tasten-Einholen (Soft-Target)",
    ["Open All"] = "Alle öffnen",
    ["Press the key for fishing  (ESC to cancel)"] = "Drücke die Taste fürs Angeln  (ESC = abbrechen)",
    ["Print a looted summary"] = "Beute-Zusammenfassung ausgeben",
    ["Recently mailed"] = "Zuletzt gemailt",
    ["Recipient dropdown on the Send tab"] = "Empfänger-Dropdown im Versenden-Tab",
    ["Scan guild chat"] = "Gildenchat scannen",
    ["Scan say / yell"] = "Sagen/Schreien scannen",
    ["Scan world / trade / LFG channels"] = "Welt-/Handels-/LFG-Channels scannen",
    ["Set fishing key"] = "Angel-Taste festlegen",
    ["Slot %d"] = "Slot %d",
    ["Speed (seconds between actions)"] = "Tempo (Sekunden zwischen Aktionen)",
    ["Take item attachments"] = "Gegenstands-Anhänge nehmen",
    ["Take money"] = "Geld nehmen",
    ["While the bobber is out, maxes effect + master volume and dims music/ambience so the splash is easy to hear. Restored when you reel in."] = "Während der Bobber draußen ist, werden Effekt- + Master-Lautstärke maximiert und Musik/Ambiente abgesenkt, damit das Platschen gut hörbar ist. Wird beim Einholen wiederhergestellt.",
    ["While the bobber is out, the same key interacts with it to reel in. Needs soft-target interaction, which is enabled only while fishing and restored afterwards."] = "Während der Bobber draußen ist, holt dieselbe Taste ihn ein. Braucht Soft-Target-Interaktion — wird nur beim Angeln aktiviert und danach wiederhergestellt.",
    ["Whisper"] = "Flüstern",
    ["Who"] = "Wer",
    ["Your characters"] = "Deine Charaktere",
    ["now"] = "jetzt",
    ["|cffaaaaaaAdds an 'Open All' button to the mailbox. It takes every attachment and coin, skipping CoD and GM mail. Shift-click the button to ignore the filters and take everything.|r"] = "|cffaaaaaaFügt dem Briefkasten einen 'Alle öffnen'-Knopf hinzu. Nimmt alle Anhänge und Münzen, überspringt Nachnahme- und GM-Post. Shift-Klick ignoriert die Filter und nimmt alles.|r",
    ["|cffaaaaaaItems or macros also used by the key while fishing — only when ready (off cooldown, buff missing, conditions met), then it goes back to casting. Type an item name or ID, shift-click an item into the box, or paste a /macro.|r"] = "|cffaaaaaaItems oder Makros, die die Taste beim Angeln mitbenutzt — nur wenn bereit (kein Cooldown, Buff fehlt, Bedingungen erfüllt), danach wird wieder ausgeworfen. Item-Name oder -ID eintippen, ein Item per Shift-Klick einfügen, oder ein /Makro einfügen.|r",
    ["|cffaaaaaaOne key does it all: cast, reel in, and apply a lure — then auto-loots. Set a key below, face some water, and press it.|r"] = "|cffaaaaaaEine Taste macht alles: auswerfen, einholen und Köder anlegen — danach Auto-Plündern. Unten eine Taste festlegen, aufs Wasser schauen, drücken.|r",
    ["|cffff5555Arena submodule OnDisable error:|r %s"] = "|cffff5555Arena-Submodul OnDisable-Fehler:|r %s",
    -- Patch notes, module descriptions, anchors, embedded engine (sweep 2026-07)
    ["Languages"] = "Sprachen",
    ["Reminders (new module)"] = "Erinnerungen (neues Modul)",
    ["Arena"] = "Arena",
    ["Totems"] = "Totems",
    ["Fixes"] = "Fixes",
    ["Resource Bar"] = "Ressourcenleiste",
    ["Settings Window"] = "Einstellungsfenster",
    ["Character Window"] = "Charakterfenster",
    ["Nameplates (German: Namensplaketten)"] = "Namensplaketten",
    ["German client"] = "Deutscher Client",
    ["Performance"] = "Performance",
    ["Equipment Sets"] = "Ausrüstungssets",
    ["NEW — Guild Bank"] = "NEU — Gildenbank",
    ["Friends & Reskins"] = "Freunde & Reskins",
    ["Bags & Bank"] = "Taschen & Bank",
    ["NEW — Bags & Bank"] = "NEU — Taschen & Bank",
    ["NEW — Chat"] = "NEU — Chat",
    ["NEW — Dark Mode"] = "NEU — Dunkelmodus",
    ["Spanish, French, Italian, Portuguese, Russian and Korean. All six are complete — every one of the 2244 texts is translated, nothing falls back to English. Spanish also serves Latin American clients. Choose your language under General, or leave it on Auto."] = "Spanisch, Französisch, Italienisch, Portugiesisch, Russisch und Koreanisch. Alle sechs sind vollständig — jeder der 2244 Texte ist übersetzt, nichts fällt auf Englisch zurück. Spanisch bedient auch lateinamerikanische Clients. Wähle deine Sprache unter Allgemein oder lass sie auf Auto.",
    ["Shows what you are missing before a pull: weapon oils and stones, blessings, food and flask buffs, the aura or stance you forgot to set. Click a reminder to cast or use it. Off by default, found under Quality of Life."] = "Zeigt vor einem Pull, was dir fehlt: Waffenöle und -steine, Segen, Essens- und Fläschchenbuffs, die Aura oder Haltung, die du vergessen hast. Klicke eine Erinnerung, um sie zu wirken oder zu benutzen. Standardmäßig aus, zu finden unter Lebensqualität.",
    ["A spark at the bar's fill point, rounded corners, aura rows you can assign freely, and your own damage-over-time effects on a row of their own."] = "Ein Funke am Füllpunkt der Leiste, abgerundete Ecken, frei belegbare Aura-Reihen und deine eigenen DoTs in einer separaten Reihe.",
    ["Aura borders take the colour of their spell school, and an aura flashes shortly before it runs out."] = "Aura-Rahmen nehmen die Farbe ihrer Zauberschule an, und eine Aura blinkt kurz, bevor sie ausläuft.",
    ["Level and elite text, plus overall scale and vertical offset per plate."] = "Stufen- und Elite-Text, dazu Gesamtskalierung und vertikaler Versatz pro Plakette.",
    ["A window can take its width or height from another window and keep it."] = "Ein Fenster kann seine Breite oder Höhe von einem anderen Fenster übernehmen und behalten.",
    ["Save button. While dragging, hold Shift to lock one axis."] = "Speichern-Button. Halte beim Ziehen Shift, um eine Achse zu sperren.",
    ["Trinket and racial cooldowns, Shadow Sight timer, a ring on the class icon for the most important aura, and range checking."] = "Trinket- und Volksfähigkeiten-Cooldowns, Schattensicht-Timer, ein Ring am Klassen-Icon für die wichtigste Aura und Reichweiten-Check.",
    ["Totem icons grey out once you leave the totem's range and regain their colour when you come back."] = "Totem-Icons werden grau, sobald du die Reichweite des Totems verlässt, und bekommen ihre Farbe zurück, wenn du zurückkommst.",
    ["The character sheet and spellbook open in combat again. The action bars no longer set a protected field from our own code, which was the real cause."] = "Charakterfenster und Zauberbuch öffnen sich im Kampf wieder. Die Aktionsleisten setzen kein geschütztes Feld mehr aus unserem eigenen Code — das war die eigentliche Ursache.",
    ["The melee swing timer is off by default and only loads for melee classes and specialisations."] = "Der Nahkampf-Swingtimer ist standardmäßig aus und lädt nur für Nahkampfklassen und -spezialisierungen.",
    ["Sliders got a proper look: soft edges, an inner shadow and a smoother hover."] = "Slider haben jetzt einen ordentlichen Look: weiche Kanten, ein Innenschatten und ein sanfteres Hover.",
    ["Own icons for the three collection pages, and class icons on the class tabs."] = "Eigene Icons für die drei Sammlungsseiten und Klassen-Icons auf den Klassen-Tabs.",
    ["Anchor a window to another one's edge (left/right/top/bottom) — the gap is kept edge-to-edge, so it survives either window being resized."] = "Verankere ein Fenster an der Kante eines anderen (links/rechts/oben/unten) — der Abstand wird Kante zu Kante gehalten und bleibt erhalten, wenn eines der Fenster seine Größe ändert.",
    ["Click-to-anchor: press \"Anchor to window...\" in a window's panel, then click the target window. Loop and self-anchor are blocked."] = "Klick-Ankern: Drücke 'An Fenster ankern...' im Panel eines Fensters und klicke dann das Zielfenster an. Schleifen und Selbst-Ankern sind blockiert.",
    ["While dragging, alignment lines now also show the pixel distance to the window you line up with."] = "Beim Ziehen zeigen die Ausrichtungslinien jetzt auch den Pixelabstand zu dem Fenster, an dem du dich ausrichtest.",
    ["Discard button — snapshots the layout when you open Edit Mode and restores it (positions, scale, anchors and links) if you discard."] = "Verwerfen-Button — macht beim Öffnen des Edit Mode einen Schnappschuss des Layouts und stellt ihn (Positionen, Skalierung, Anker und Verknüpfungen) beim Verwerfen wieder her.",
    ["The drag area now covers the whole dark chat panel down to the edit box, not just the narrow message strip."] = "Der Ziehbereich deckt jetzt das ganze dunkle Chat-Panel bis zum Eingabefeld ab, nicht nur den schmalen Nachrichtenstreifen.",
    ["Fixed right-click on the chat window not opening its settings panel in Edit Mode."] = "Behoben: Rechtsklick auf das Chatfenster öffnete im Edit Mode nicht sein Einstellungs-Panel.",
    ["Interrupt help on the cast bar: own colours while your interrupt is on cooldown or ready, a tick marking where it comes back mid-cast, a shield on uninterruptible casts and an interrupt flash that can show who landed the kick."] = "Unterbrechungshilfe auf der Castbar: eigene Farben, während dein Unterbrechungszauber auf Cooldown oder bereit ist, eine Markierung, die zeigt, wo er mitten im Cast zurückkommt, ein Schild auf nicht unterbrechbaren Casts und ein Unterbrechungs-Blitz, der zeigen kann, wer den Kick gelandet hat.",
    ["Cast bar suite: icon side and scale, remaining time, own background, channel colour, a warning colour when the cast aims at YOU — and on your target the cast bar lines up flush with the health bar including its border."] = "Castbar-Paket: Icon-Seite und -Skalierung, Restzeit, eigener Hintergrund, Kanalisierungs-Farbe, eine Warnfarbe, wenn der Cast auf DICH zielt — und am Ziel schließt die Castbar bündig mit dem Lebensbalken samt Rahmen ab.",
    ["Execute line, target and mouseover effects, crowd control section, combo point shapes and placement, per-element position, size and text-size controls plus a font picker."] = "Execute-Linie, Ziel- und Mouseover-Effekte, Crowd-Control-Bereich, Formen und Platzierung der Kombopunkte, Position, Größe und Textgröße pro Element plus eine Schriftauswahl.",
    ["The options page carries a clickable live preview that stays pinned while you scroll — click any element to jump to its settings."] = "Die Optionsseite trägt eine klickbare Live-Vorschau, die beim Scrollen angeheftet bleibt — klicke ein Element an, um zu seinen Einstellungen zu springen.",
    ["Smooth health movement with a damage trail, value plus percent text layouts with short numbers, and a decimal toggle for aura timers."] = "Sanfte Lebensbewegung mit Schadensspur, Textlayouts mit Wert plus Prozent und Kurzzahlen sowie ein Dezimalstellen-Schalter für Aura-Timer.",
    ["Per-bar visibility conditions (instances, mounted, target, group), modifier paging, quick keybind mode (/vkb), a sixth bar, growth directions, button text styling and cooldown look options."] = "Sichtbarkeitsbedingungen pro Leiste (Instanzen, aufgesessen, Ziel, Gruppe), Seitenwechsel per Modifikator, Schnell-Tastenbelegungsmodus (/vkb), eine sechste Leiste, Wachstumsrichtungen, Button-Text-Gestaltung und Optionen für die Cooldown-Optik.",
    ["Micro menu and bag bar modern style: flat dark strips with an own monochrome icon set, plus world map, friends list, group finder, shop and key ring buttons."] = "Mikromenü und Taschenleiste im modernen Stil: flache dunkle Streifen mit eigenem monochromen Icon-Set, dazu Buttons für Weltkarte, Freundesliste, Gruppensuche, Shop und Schlüsselbund.",
    ["The experience bar width now adjusts in single steps."] = "Die Breite der Erfahrungsleiste lässt sich jetzt in Einzelschritten anpassen.",
    ["Visibility conditions, colour modes with gradient, background and border colours, smooth value changes, hash marks and threshold colouring."] = "Sichtbarkeitsbedingungen, Farbmodi mit Verlauf, Hintergrund- und Rahmenfarben, sanfte Wertänderungen, Markierungen und Schwellwert-Färbung.",
    ["Character sheet stats panel no longer bleeds into other tabs; loadout sidebar aligns with the modern character sheet."] = "Das Werte-Panel des Charakterfensters ragt nicht mehr in andere Tabs hinein; die Set-Sidebar richtet sich am modernen Charakterfenster aus.",
    ["Arena points calculator panel and button wear the addon look and dock beside the character sheet."] = "Arenapunkte-Rechner-Panel und -Button tragen den Addon-Look und docken neben dem Charakterfenster an.",
    ["The Escape menu now wears the dark addon look — flat buttons, accent title — and gains a VuloClassicUI button that opens the options window. Both have their own toggles under General."] = "Das Escape-Menü trägt jetzt den dunklen Addon-Look — flache Buttons, Akzent-Titel — und bekommt einen VuloClassicUI-Button, der das Optionsfenster öffnet. Beide haben eigene Schalter unter Allgemein.",
    ["The add friend dialog is skinned to match: dark panel, accent headline, dark input field and flat buttons."] = "Der Freund-hinzufügen-Dialog ist passend geskinnt: dunkles Panel, Akzent-Überschrift, dunkles Eingabefeld und flache Buttons.",
    ["Guild roster column header hover and click no longer stick out past the flat header row."] = "Die Spaltenüberschriften der Gildenliste stehen bei Hover und Klick nicht mehr über die flache Kopfzeile hinaus.",
    ["The combat log filter bar now shares the exact width and height of the chat tab row, flush with the panel edge."] = "Die Filterleiste des Kampflogs teilt jetzt exakt Breite und Höhe der Chat-Tab-Reihe, bündig mit der Panelkante.",
    ["After an update, a pulsing dot on the \"Patch Notes\" entry points at the new notes until you open them once — account wide, per version."] = "Nach einem Update weist ein pulsierender Punkt auf dem Eintrag 'Patch Notes' auf die neuen Notizen hin, bis du sie einmal öffnest — accountweit, pro Version.",
    ["With the Modern style, the equipment set sidebar now docks to the right of the stats panel at exactly the window's height, instead of overlapping it. Switching styles with the window open moves it immediately."] = "Im Modern-Stil dockt die Ausrüstungsset-Sidebar jetzt rechts vom Werte-Panel an, exakt auf Fensterhöhe, statt es zu überlappen. Ein Stilwechsel bei offenem Fenster verschiebt sie sofort.",
    ["Micro menu buttons that the game hides situationally are shown again, so the row no longer has a gap."] = "Mikromenü-Buttons, die das Spiel situationsbedingt versteckt, werden wieder angezeigt, sodass die Reihe keine Lücke mehr hat.",
    ["The default nameplate no longer shows through as a faint transparent bar under the custom plate — it is now hidden outright and kept hidden while the custom plate is active."] = "Die Standard-Namensplakette scheint nicht mehr als blasser transparenter Balken unter der eigenen Plakette durch — sie wird jetzt komplett versteckt und bleibt versteckt, solange die eigene Plakette aktiv ist.",
    ["All micro menu buttons open their windows again — the emptied default micro menu shell was invisibly swallowing clicks on the relocated buttons."] = "Alle Mikromenü-Buttons öffnen ihre Fenster wieder — die geleerte Standard-Mikromenü-Hülle hat Klicks auf die verschobenen Buttons unsichtbar geschluckt.",
    ["Fixed a blocked-action error when the stance bar updated during combat; stance button visibility now only changes out of combat, while icon tint, cooldown and the active marker keep updating live."] = "Behoben: ein Fehler durch blockierte Aktionen, wenn sich die Haltungsleiste im Kampf aktualisierte; die Sichtbarkeit der Haltungs-Buttons ändert sich jetzt nur noch außerhalb des Kampfes, während Icon-Färbung, Cooldown und aktive Markierung live weiterlaufen.",
    ["An Action Bars module puts every action bar on its own movable frame — action bars 1 to 5, the stance bar and the pet bar — each placed and scaled in Edit Mode and configured on its own."] = "Ein Aktionsleisten-Modul legt jede Aktionsleiste auf einen eigenen verschiebbaren Rahmen — Aktionsleisten 1 bis 5, die Haltungsleiste und die Begleiterleiste — jede im Edit Mode platziert und skaliert und einzeln konfiguriert.",
    ["The main bar pages correctly with druid, rogue, warrior and priest forms, and your keybinds keep working on every bar, with the key shown on the buttons."] = "Die Hauptleiste blättert mit Druiden-, Schurken-, Krieger- und Priester-Formen korrekt um, und deine Tastenbelegungen funktionieren auf jeder Leiste weiter — die Taste wird auf den Buttons angezeigt.",
    ["Per bar: visibility (always, mouseover, in or out of combat), opacity, icon size, buttons per row, spacing, vertical layout, reverse order, and hiding the keybind or macro text — with adjustable text sizes for keybind, macro, count and cooldown numbers."] = "Pro Leiste: Sichtbarkeit (immer, Mouseover, im oder außerhalb des Kampfes), Deckkraft, Icon-Größe, Buttons pro Reihe, Abstand, vertikales Layout, umgekehrte Reihenfolge und das Ausblenden von Tastenbelegungs- oder Makrotext — mit einstellbaren Textgrößen für Tastenbelegung, Makro, Anzahl und Cooldown-Zahlen.",
    ["Empty slots can be hidden and reappear automatically while you drag an ability onto the bar, and a bar can be made click-through."] = "Leere Slots lassen sich ausblenden und erscheinen automatisch wieder, während du eine Fähigkeit auf die Leiste ziehst, und eine Leiste kann durchklickbar gemacht werden.",
    ["Cooldown and look settings for all bars: cooldown sweep darkness, desaturating icons on cooldown, colouring icons while the target is out of range, and hiding button tooltips always or only in combat."] = "Cooldown- und Optik-Einstellungen für alle Leisten: Dunkelheit des Cooldown-Sweeps, Entsättigen von Icons auf Cooldown, Einfärben von Icons, während das Ziel außer Reichweite ist, und das Ausblenden von Button-Tooltips immer oder nur im Kampf.",
    ["An own experience bar with adjustable width, height and colour, rested overlay and progress text — it replaces the default bar while enabled and hides at the level cap."] = "Eine eigene Erfahrungsleiste mit einstellbarer Breite, Höhe und Farbe, Erholt-Overlay und Fortschrittstext — sie ersetzt die Standardleiste, solange sie aktiviert ist, und versteckt sich auf der Maximalstufe.",
    ["The micro menu, the bag bar and the performance bar sit on movable holders, and each of them can be hidden — as can the default experience bar."] = "Mikromenü, Taschenleiste und Performance-Leiste sitzen auf verschiebbaren Haltern, und jeder davon kann versteckt werden — ebenso die Standard-Erfahrungsleiste.",
    ["Off by default: the standard bars stay untouched until you enable the module, and disabling hands everything back (a reload fully restores the default bars)."] = "Standardmäßig aus: Die Standardleisten bleiben unangetastet, bis du das Modul aktivierst, und beim Deaktivieren wird alles zurückgegeben (ein Reload stellt die Standardleisten vollständig wieder her).",
    ["The dark button skin now also covers the new action-bar buttons."] = "Der dunkle Button-Skin deckt jetzt auch die neuen Aktionsleisten-Buttons ab.",
    ["A custom Nameplates module draws its own health bar, cast bar, name and health text over enemy and NPC nameplates — fully configurable, with a live preview that updates as you change each option."] = "Ein eigenes Namensplaketten-Modul zeichnet eigene Lebensbalken, Castbar, Namen und Lebenstext über Gegner- und NPC-Plaketten — voll konfigurierbar, mit einer Live-Vorschau, die sich bei jeder geänderten Option sofort aktualisiert.",
    ["Health bar with your choice of texture, width, height, background, and a border drawn as thin lines or a texture, all in your own colours."] = "Lebensbalken mit Textur, Breite, Höhe und Hintergrund nach Wahl sowie einem Rahmen als dünne Linien oder Textur, alles in deinen eigenen Farben.",
    ["Colouring by reaction (hostile, neutral, friendly, tapped) and by class for players, plus role-based threat colouring for tanks and damage dealers."] = "Färbung nach Reaktion (feindlich, neutral, freundlich, getappt) und nach Klasse bei Spielern, dazu rollenbasierte Bedrohungsfärbung für Tanks und Schadensausteiler.",
    ["Target and focus highlight rings, and an optional fade for plates that are not your target."] = "Ziel- und Fokus-Hervorhebungsringe und ein optionales Verblassen für Plaketten, die nicht dein Ziel sind.",
    ["Cast bar with spell icon, spell name, and a separate colour for casts that cannot be interrupted."] = "Castbar mit Zauber-Icon, Zaubername und einer eigenen Farbe für Casts, die nicht unterbrochen werden können.",
    ["Aura rows: your debuffs (or all of them), enemy buffs, and a separate prominent row for crowd control such as Polymorph, Fear and Sap. A glow marks enemy buffs you can steal or dispel."] = "Aura-Reihen: deine Debuffs (oder alle), Gegner-Buffs und eine eigene prominente Reihe für Crowd Control wie Verwandlung, Furcht und Kopfnuss. Ein Glühen markiert Gegner-Buffs, die du stehlen oder bannen kannst.",
    ["Combo point pips on your target for Rogues and Druids in cat form."] = "Kombopunkt-Pips auf deinem Ziel für Schurken und Druiden in Katzengestalt.",
    ["Raid target markers (skull, cross, and the rest) with adjustable size and position."] = "Schlachtzugszeichen (Totenkopf, Kreuz und der Rest) mit einstellbarer Größe und Position.",
    ["Friendly plates can show name only, the full plate, or nothing — set separately for players and NPCs — and can show a friendly NPC's subtitle under its name."] = "Freundliche Plaketten können nur den Namen, die ganze Plakette oder nichts zeigen — getrennt einstellbar für Spieler und NPCs — und können den Untertitel eines freundlichen NPCs unter seinem Namen anzeigen.",
    ["A single \"Dark Skin\" module now covers the dark action-button and WeakAuras skin plus the optional Dark Mode that darkens Blizzard's default frames — those used to be two separate modules. Your existing settings carry over."] = "Ein einzelnes Modul 'Dunkles Design' deckt jetzt den dunklen Aktionsbutton- und WeakAuras-Skin plus den optionalen Dunkelmodus ab, der Blizzards Standard-Fenster abdunkelt — das waren vorher zwei getrennte Module. Deine bestehenden Einstellungen werden übernommen.",
    ["The reskin modules (skins, character panel, chat, friends list, minimap) are now one tabbed entry, matching how the other groups are already organised."] = "Die Reskin-Module (Skins, Charakterfenster, Chat, Freundesliste, Minimap) sind jetzt ein Eintrag mit Tabs, passend dazu, wie die anderen Gruppen bereits organisiert sind.",
    ["Consolidated groups now list their modules as a vertical, icon-labelled column instead of a wrapping row of tabs — easier to scan when there are many."] = "Zusammengefasste Gruppen listen ihre Module jetzt als vertikale Spalte mit Icon-Beschriftung statt als umbrechende Tab-Reihe — leichter zu überblicken, wenn es viele sind.",
    ["A \"Patch Notes\" page under Overview shows every version's changes right in the game."] = "Eine Seite 'Patch Notes' unter Übersicht zeigt die Änderungen jeder Version direkt im Spiel.",
    ["Cleaner tab names for a few tools: Training, Leisten-Profile, Apexis-Minispiel, Gruppensuche."] = "Sauberere Tab-Namen für ein paar Tools: Training, Leisten-Profile, Apexis-Minispiel, Gruppensuche.",
    ["The target-frame extras and the elite player-frame border are now a single module called \"Player & Target Frame\". Your existing settings and per-character on and off state carry over automatically."] = "Die Zielfenster-Extras und der Elite-Rahmen des Spielerfensters sind jetzt ein einzelnes Modul namens 'Spieler- & Zielfenster'. Deine bestehenden Einstellungen und der An-/Aus-Zustand pro Charakter werden automatisch übernommen.",
    ["Settings now default to a separate profile per class, so what you set on one class no longer changes another. Your current settings are copied into each class profile, and you can still share or pin profiles as before."] = "Einstellungen nutzen jetzt standardmäßig ein eigenes Profil pro Klasse, sodass das, was du auf einer Klasse einstellst, keine andere mehr verändert. Deine aktuellen Einstellungen werden in jedes Klassenprofil kopiert, und du kannst Profile weiterhin wie bisher teilen oder anheften.",
    ["Scrolling messages that fire at the same moment now stack with a gap instead of overlapping."] = "Scrollende Nachrichten, die im selben Moment ausgelöst werden, stapeln sich jetzt mit Abstand, statt sich zu überlappen.",
    ["Fixed an error that could appear when combat started while your line was cast. The sound and interact settings now restore after combat ends instead."] = "Behoben: ein Fehler, der auftreten konnte, wenn der Kampf begann, während deine Angelschnur ausgeworfen war. Die Sound- und Interagieren-Einstellungen werden jetzt stattdessen nach Kampfende wiederhergestellt.",
    ["Lighter cast bar time text, cooldown bars that batch their refreshes during busy moments, a cheaper combat-log check for the cooldown pulse, and a lighter minimap hover check."] = "Leichtgewichtigerer Castbar-Zeittext, Cooldown-Leisten, die ihre Aktualisierungen in hektischen Momenten bündeln, ein günstigerer Kampflog-Check für den Cooldown-Puls und ein leichterer Minimap-Hover-Check.",
    ["The spell stats are ordered spell power, healing, spell crit, then spell hit."] = "Die Zauberwerte sind in der Reihenfolge Zaubermacht, Heilung, Zauberkrit, dann Zaubertreffer angeordnet.",
    ["The Fishing and Mail tabs now read \"Angeln\" and \"Post\"."] = "Die Angel- und Post-Tabs heißen jetzt 'Angeln' und 'Post'.",
    ["A style dropdown at the top of the module options. Classic+ keeps the current look; Modern is a new dark, single-window style."] = "Ein Stil-Dropdown oben in den Modul-Optionen. Classic+ behält den aktuellen Look; Modern ist ein neuer dunkler Ein-Fenster-Stil.",
    ["Modern reskins the whole character window dark with an accent border and a stats panel on the right: a big equipped item level, then collapsible categories — attributes, melee, spell, defense and resistances — with per-stat hover breakdowns and mouse-wheel scrolling."] = "Modern gestaltet das ganze Charakterfenster dunkel um, mit Akzent-Rahmen und einem Werte-Panel rechts: ein groß angezeigtes Item-Level der angelegten Ausrüstung, dann einklappbare Kategorien — Attribute, Nahkampf, Zauber, Verteidigung und Widerstände — mit Hover-Aufschlüsselung pro Wert und Mausrad-Scrollen.",
    ["Under Modern the built-in stats, resistance icons and the model rotate arrows are hidden, and the reputation, skills and player-versus-player sub-tabs plus the bottom tabs are skinned to match. Everything switches back to Classic+ live, and adapts per client (rating stats only where they exist)."] = "Unter Modern sind die eingebauten Werte, die Widerstands-Icons und die Drehpfeile am Modell versteckt, und die Untertabs Ruf, Fertigkeiten und PvP sowie die unteren Tabs sind passend geskinnt. Alles wechselt live zurück zu Classic+ und passt sich pro Client an (Wertungs-Werte nur dort, wo es sie gibt).",
    ["Dark skin for a world-map options window, with its own on and off switch in the Addon Skins options."] = "Dunkler Skin für ein Weltkarten-Optionsfenster, mit eigenem An-/Aus-Schalter in den Addon-Skins-Optionen.",
    ["The clock now sits on the same line as the date and zone instead of floating higher."] = "Die Uhr sitzt jetzt auf derselben Zeile wie Datum und Zone, statt höher zu schweben.",
    ["Dark skin for a loot-distribution addon — its award and roll windows, its settings and overview windows, and the two always-visible roll and bid bars get the house panel, accent border and flat close button."] = "Dunkler Skin für ein Loot-Verteilungs-Addon — seine Vergabe- und Würfelfenster, seine Einstellungs- und Übersichtsfenster und die beiden dauerhaft sichtbaren Würfel- und Bietleisten bekommen das Haus-Panel, den Akzent-Rahmen und den flachen Schließen-Button.",
    ["Dark skin for an attunement tracker — the main window and its buttons match the dark look; the colored status rows stay as they are so the state colors remain readable."] = "Dunkler Skin für einen Attunement-Tracker — Hauptfenster und Buttons passen zum dunklen Look; die farbigen Statuszeilen bleiben, wie sie sind, damit die Statusfarben lesbar bleiben.",
    ["Both are separate on and off switches in the Addon Skins options, next to the others."] = "Beide sind eigene An-/Aus-Schalter in den Addon-Skins-Optionen, neben den anderen.",
    ["Fixed: an expanded set sometimes would not collapse on the second click of its arrow. The arrow is also easier to hit now."] = "Behoben: Ein ausgeklapptes Set ließ sich manchmal beim zweiten Klick auf seinen Pfeil nicht einklappen. Der Pfeil ist jetzt auch leichter zu treffen.",
    ["The slot flyout can now equip not-yet-bound items too — with the game's own \"this will bind to you\" confirmation before it soulbinds."] = "Das Slot-Flyout kann jetzt auch noch nicht gebundene Items anlegen — mit der spieleigenen 'Wird beim Anlegen gebunden'-Bestätigung, bevor es seelengebunden wird.",
    ["Item levels in links now only show on uncommon (green) and better gear — grey and white trash no longer gets a number."] = "Item-Level in Links erscheinen jetzt nur noch auf ungewöhnlicher (grüner) und besserer Ausrüstung — grauer und weißer Kram bekommt keine Zahl mehr.",
    ["No double number when another loot addon already tagged the item with its item level."] = "Keine doppelte Zahl mehr, wenn ein anderes Loot-Addon das Item bereits mit seinem Item-Level markiert hat.",
    ["The date now shows next to the clock in the zone panel — click it to open the calendar, hover for the full date. Optional in the minimap settings."] = "Das Datum steht jetzt neben der Uhr im Zonen-Panel — klicke es, um den Kalender zu öffnen, hovere für das volle Datum. Optional in den Minimap-Einstellungen.",
    ["The zone panel is a touch wider so the zone name, clock and date sit more comfortably."] = "Das Zonen-Panel ist einen Hauch breiter, damit Zonenname, Uhr und Datum bequemer sitzen.",
    ["Hover an equipment slot in the character window for a compact flyout of matching items from your bags — click one to equip it. The modifier-click picker is still there for a larger, pinnable window."] = "Hovere über einen Ausrüstungs-Slot im Charakterfenster für ein kompaktes Flyout mit passenden Items aus deinen Taschen — klicke eines, um es anzulegen. Die Modifier-Klick-Auswahl gibt es weiterhin für ein größeres, anheftbares Fenster.",
    ["Item levels on gear are now tinted in the item's quality color, matching the rest of the window (toggle in the options)."] = "Item-Level auf Ausrüstung sind jetzt in der Qualitätsfarbe des Items eingefärbt, passend zum Rest des Fensters (Schalter in den Optionen).",
    ["Section headers gained a thin divider line and a collapse control — click a category header to fold it away. The state is remembered per category."] = "Abschnittsköpfe haben eine dünne Trennlinie und ein Einklapp-Element bekommen — klicke eine Kategorie-Überschrift, um sie zusammenzuklappen. Der Zustand wird pro Kategorie gemerkt.",
    ["The window title now shows the used and total item count."] = "Der Fenstertitel zeigt jetzt die genutzte und die gesamte Item-Anzahl.",
    ["Theme color — pick the accent color in the global settings (presets or your own). Everything purple follows it, saved per profile."] = "Themenfarbe — wähle die Akzentfarbe in den globalen Einstellungen (Vorlagen oder eigene). Alles Violette folgt ihr, gespeichert pro Profil.",
    ["Pin a profile to a single character; at login it beats the class assignment and the account-wide selection."] = "Hefte ein Profil an einen einzelnen Charakter; beim Einloggen schlägt es die Klassenzuweisung und die accountweite Auswahl.",
    ["Track your own debuffs on the target, or set up a missing-buff reminder group (icon shows while the buff is absent)."] = "Verfolge deine eigenen Debuffs auf dem Ziel oder richte eine Erinnerungsgruppe für fehlende Buffs ein (das Icon erscheint, solange der Buff fehlt).",
    ["Icons tint blue when you are out of mana and red when the target is out of range; ready-only groups now pack without gaps."] = "Icons färben sich blau, wenn dir Mana fehlt, und rot, wenn das Ziel außer Reichweite ist; Nur-bereit-Gruppen rücken jetzt ohne Lücken zusammen.",
    ["Auto-track your equipped trinkets, duplicate a whole group, and optional hover tooltips."] = "Verfolge automatisch deine angelegten Schmuckstücke, dupliziere eine ganze Gruppe, dazu optionale Hover-Tooltips.",
    ["Dark skin for the guild & communities window — flat tabs, list cards, roster and chat panels."] = "Dunkler Skin für das Gilden- & Gemeinschaftsfenster — flache Tabs, Listenkarten, Roster- und Chat-Panels.",
    ["Pushback readout, a latency window on casts (the spell-queue moment), a crafting-series counter (e.g. 3/20), timer format options, accent/class fill colors and smoother fill on time jumps."] = "Pushback-Anzeige, ein Latenzfenster auf Casts (der Spell-Queue-Moment), ein Zähler für Handwerks-Serien (z. B. 3/20), Timer-Formatoptionen, Akzent-/Klassenfarben-Füllung und sanftere Füllung bei Zeitsprüngen.",
    ["Reworked with inline spell icons and bracketed spell names; separate purge, incoming-dispel, buff-given/received and spell-reflect messages, with anti-spam throttling."] = "Überarbeitet mit Zauber-Icons im Text und Zaubernamen in Klammern; getrennte Nachrichten für Vertreiben, eingehende Banne, gegebene/erhaltene Buffs und Zauberreflexion, mit Anti-Spam-Drosselung.",
    ["Death announcements for group members with class-colored names."] = "Todesmeldungen für Gruppenmitglieder mit klassengefärbten Namen.",
    ["A per-character snapshot of your bank contents, viewable anywhere from the bag window — with tooltips and smart search."] = "Ein Schnappschuss deines Bankinhalts pro Charakter, überall einsehbar über das Taschenfenster — mit Tooltips und smarter Suche.",
    ["A dark guild bank window with tabs, search, a money log, deposit/withdraw and engine-based sorting."] = "Ein dunkles Gildenbank-Fenster mit Tabs, Suche, einem Gold-Log, Einlagern/Abheben und Sortierung über die Sortier-Engine.",
    ["Full dark reskin of the friends window with class crests, row layout, tabs and a battletag pill."] = "Kompletter dunkler Reskin des Freundesfensters mit Klassenwappen, Zeilenlayout, Tabs und einer Battletag-Pille.",
    ["Addon Skins module — matches supported third-party windows to the dark look, including a quest tracker with accent headers."] = "Addon-Skins-Modul — passt unterstützte Drittanbieter-Fenster an den dunklen Look an, inklusive eines Quest-Trackers mit Akzent-Überschriften.",
    ["Smart search keywords (quality, type, item level) that also search an open bank and guild bank."] = "Smarte Suchbegriffe (Qualität, Typ, Item-Level), die auch eine geöffnete Bank und Gildenbank durchsuchen.",
    ["Bind-on-equip and junk markers, keyring separation, and a fixed-slot OneBag layout."] = "Markierungen für 'Wird beim Anlegen gebunden' und Müll, Schlüsselbund-Trennung und ein OneBag-Layout mit festen Slots.",
    ["Availability markers, set-preview tooltips, true partial sets, and an item-level/set warning in the disenchant queue."] = "Verfügbarkeits-Markierungen, Set-Vorschau-Tooltips, echte Teil-Sets und eine Item-Level-/Set-Warnung in der Entzauberungs-Queue.",
    ["Rebuilt sort engine (bags, bank and guild bank) that keeps materials and gear apart."] = "Neu gebaute Sortier-Engine (Taschen, Bank und Gildenbank), die Materialien und Ausrüstung getrennt hält.",
    ["Minimap and totem-bar improvements, plus framework hardening for the current clients."] = "Minimap- und Totemleisten-Verbesserungen, dazu Framework-Härtung für die aktuellen Clients.",
    ["A single unified inventory window: search, sort, categories, custom groups, pinned & recent items, keyring, quick-drop, item levels and quality borders."] = "Ein einziges vereintes Inventarfenster: Suche, Sortierung, Kategorien, eigene Gruppen, angeheftete & letzte Items, Schlüsselbund, Schnell-Wegwerfen, Item-Level und Qualitätsrahmen.",
    ["A new bank window with slot purchasing."] = "Ein neues Bankfenster mit Slot-Kauf.",
    ["Friends counter in the chat, a gold overview tooltip, and taint-free Edit Mode movers."] = "Freundeszähler im Chat, ein Gold-Übersichts-Tooltip und taintfreie Edit-Mode-Mover.",
    ["Chat module polish and localization fixes."] = "Feinschliff am Chat-Modul und Lokalisierungs-Fixes.",
    ["A reworked chat: timestamps, class-colored names, clickable links, short channel names, a dark panel with an icon sidebar, idle fade and history that survives a reload. Every part is optional."] = "Ein überarbeiteter Chat: Zeitstempel, klassengefärbte Namen, klickbare Links, kurze Kanalnamen, ein dunkles Panel mit Icon-Sidebar, Ausblenden bei Inaktivität und ein Verlauf, der einen Reload übersteht. Jeder Teil ist optional.",
    ["Per-frame free-move and an anchor toggle, with panel polish."] = "Freies Verschieben pro Fenster und ein Anker-Schalter, dazu Panel-Feinschliff.",
    ["Dark border on the action bars; fixed a compat-frame taint issue."] = "Dunkler Rahmen auf den Aktionsleisten; ein Taint-Problem mit einem Kompatibilitäts-Frame behoben.",
    ["A dark-mode module, plus German localization fixes."] = "Ein Dunkelmodus-Modul, dazu deutsche Lokalisierungs-Fixes.",
    ["NEW:"] = "NEU:",
    ["A single unified inventory window: all bags in one grid, with quality borders, counts, cooldowns, money and free slots. Movable and scalable."] = "Ein einziges vereintes Inventarfenster: alle Taschen in einem Raster, mit Qualitätsrahmen, Anzahl, Cooldowns, Gold und freien Slots. Verschiebbar und skalierbar.",
    ["Fixes stuck inspect bugs (no player inspect possible after a faulty close/timeout). Auto-reset after a timeout, auto-retry when the window stays empty, cleanup when InspectFrame closes + /inspectreset slash command."] = "Behebt hängende Inspect-Bugs (kein Spieler-Inspect möglich nach fehlerhaftem Schließen/Timeout). Auto-Reset nach einem Timeout, Auto-Retry, wenn das Fenster leer bleibt, Cleanup beim Schließen des InspectFrames + /inspectreset Slash-Befehl.",
    ["A modern minimap: round with a clean dark ring and accent line, zone text and clock in a slim panel, mouse-wheel zoom, movable and scalable. Optionally hides other addons' buttons until mouseover."] = "Eine moderne Minimap: rund mit sauberem dunklem Ring und Akzentlinie, Zonentext und Uhr in einem schmalen Panel, Zoomen per Mausrad, verschiebbar und skalierbar. Versteckt optional die Buttons anderer Addons bis zum Mouseover.",
    ["Custom enemy & NPC nameplates with a live preview: health bar, cast bar, name and health text, reaction / class colours, target highlight and threat colouring."] = "Eigene Gegner- & NPC-Namensplaketten mit Live-Vorschau: Lebensbalken, Castbar, Namens- und Lebenstext, Reaktions-/Klassenfarben, Ziel-Hervorhebung und Bedrohungsfärbung.",
    ["Hover an equipment slot for a compact flyout of compatible bag items, or modifier-click for a larger picker. Click an item to equip it."] = "Hovere über einen Ausrüstungs-Slot für ein kompaktes Flyout mit passenden Taschen-Items, oder Modifier-Klick für eine größere Auswahl. Klicke ein Item, um es anzulegen.",
    ["Move every VuloUI window and Blizzard's default frames in one editor."] = "Verschiebe jedes VuloUI-Fenster und Blizzards Standard-Fenster in einem Editor.",
    ["One-key fishing: one key casts, reels and applies a lure, and auto-loots your catch."] = "Ein-Tasten-Angeln: Eine Taste wirft aus, holt ein und trägt einen Köder auf, und dein Fang wird automatisch geplündert.",
    ["Scans chat for people forming groups and lists them by Classic/TBC instance in a window (/vlfg or the minimap button)."] = "Durchsucht den Chat nach Leuten, die Gruppen bilden, und listet sie nach Classic-/TBC-Instanz in einem Fenster (/vlfg oder der Minimap-Button).",
    ["Adds an 'Open All' button to your mailbox that collects every attachment and coin in one click."] = "Fügt deinem Briefkasten einen 'Alle öffnen'-Button hinzu, der jeden Anhang und jede Münze mit einem Klick einsammelt.",
    ["Top"] = "Oben",
    ["Bottom"] = "Unten",
    ["Top-Left"] = "Oben links",
    ["Top-Right"] = "Oben rechts",
    ["Bottom-Left"] = "Unten links",
    ["Bottom-Right"] = "Unten rechts",
    ["Trinkets: Cleared all ignored/hidden trinkets."] = "Trinkets: Alle ignorierten/versteckten Schmuckstücke geleert.",
    ["Trinkets usage:"] = "Trinkets-Verwendung:",
    ["/trinket or /Trinkets : toggle the window"] = "/trinket oder /Trinkets : Fenster ein-/ausblenden",
    ["/trinket reset : reset all settings"] = "/trinket reset : setzt alle Einstellungen zurück",
    ["/trinket clear : clear all ignored/hidden trinkets"] = "/trinket clear : leert alle ignorierten/versteckten Schmuckstücke",
    ["/trinket opt : summon options window"] = "/trinket opt : öffnet das Optionsfenster",
    ["/trinket lock|unlock : toggles window lock"] = "/trinket lock|unlock : sperrt/entsperrt das Fenster",
    ["/trinket scale main|menu (number) : sets an exact scale"] = "/trinket scale main|menu (Zahl) : setzt eine exakte Skalierung",
    ["/trinket load top|bottom profilename : loads a profile to top or bottom trinket"] = "/trinket load top|bottom Profilname : lädt ein Profil auf das obere oder untere Schmuckstück",
    ["Are you sure you want to reset Trinkets to default state and reload the UI?"] = "Bist du sicher, dass du Trinkets auf den Standardzustand zurücksetzen und die UI neu laden willst?",
    ["Queued: %s"] = "In der Warteschlange: %s",
    ["Priority"] = "Priorität",
    ["Pause Queue"] = "Warteschlange pausieren",
    ["Parameter must be 0 for top trinket or 1 for bottom."] = "Parameter muss 0 für das obere oder 1 für das untere Schmuckstück sein.",
    ["No profiles saved yet."] = "Noch keine Profile gespeichert.",
    -- Patch notes, module descriptions, anchors, embedded engine (sweep 2026-07)
    -- Patch notes 1.37.1
    ["Visuals"] = "Optik",
    ["The language option under General now actually applies. It silently never took effect — the addon read the client language before your saved choice was loaded. After a /reload every label, dropdown and popup follows your choice."] = "Die Sprachauswahl unter Allgemein greift jetzt wirklich. Sie wirkte stillschweigend nie — das Addon las die Client-Sprache, bevor deine gespeicherte Wahl geladen war. Nach einem /reload folgen alle Beschriftungen, Auswahllisten und Dialoge deiner Wahl.",
    ["The Patch Notes page is translated into all languages, including every past version."] = "Die Patch-Notizen-Seite ist in alle Sprachen übersetzt, einschließlich aller früheren Versionen.",
    ["The trinket panel, its queue window and the /trinket help are translated too."] = "Das Schmuck-Fenster, seine Warteschlange und die /trinket-Hilfe sind ebenfalls übersetzt.",
    ["German: sixteen duplicated translations cleaned up, five of which contradicted each other."] = "Deutsch: sechzehn doppelte Übersetzungen bereinigt, fünf davon widersprachen sich.",
    ["Third pass over the busiest code paths: nameplate auras scan once instead of four times, combat-log and aura events skip a safety wrapper, timer texts only redraw when the shown number changes, and several background listeners now sleep while their feature is off or hidden. Less stutter in raids and arenas."] = "Dritter Durchgang über die meistbelasteten Codepfade: Namensplaketten-Auren werden einmal statt viermal durchsucht, Kampflog- und Auren-Ereignisse sparen sich eine Sicherheitshülle, Timer-Texte zeichnen nur neu, wenn sich die angezeigte Zahl ändert, und mehrere Hintergrund-Zuhörer schlafen, solange ihre Funktion aus oder verborgen ist. Weniger Ruckeln in Schlachtzügen und Arenen.",
    ["The frames can be turned off again without leftovers."] = "Die Fenster lassen sich wieder ohne Rückstände abschalten.",
    ["An interrupted enemy cast now shows INTERRUPTED briefly — it used to vanish the same instant."] = "Ein unterbrochener gegnerischer Zauber zeigt jetzt kurz UNTERBROCHEN — bisher verschwand er im selben Moment.",
    ["Diminishing-returns icons clean up correctly after toggling the tracker mid-arena."] = "Die Symbole des Diminishing-Returns-Trackers räumen korrekt auf, wenn der Tracker mitten in der Arena umgeschaltet wird.",
    ["Seven working settings that were invisible in the options are shown again, and several switches that did nothing are wired up."] = "Sieben funktionierende Einstellungen, die in den Optionen unsichtbar waren, werden wieder angezeigt, und mehrere wirkungslose Schalter sind jetzt angeschlossen.",
    ["Modules tidy up after themselves when disabled: totem range dimming, the inspect window, queue timer, quest log and font bars no longer leave stale pieces behind."] = "Module räumen beim Abschalten hinter sich auf: Totem-Reichweiten-Abdunklung, das Inspizieren-Fenster, Warteschlangen-Timer, Questlog und Schriftleisten hinterlassen keine Reste mehr.",
    ["Three modules got their own sidebar icons instead of the placeholder, and Reminders got a nicer bell."] = "Drei Module haben eigene Seitenleisten-Symbole statt des Platzhalters bekommen, und die Erinnerungen eine schönere Glocke.",
    -- Bags: quest starter marker
    ["Quest starter marker (!)"] = "Quest-Start-Markierung (!)",
    ["Overlays a yellow exclamation mark on items that start a quest you have not accepted yet."] = "Legt ein gelbes Ausrufezeichen über Gegenstände, die eine noch nicht angenommene Quest starten.",
    -- Options page build failure
    ["|cffff5555Options page '%s' failed to build:|r %s"] = "|cffff5555Optionsseite '%s' konnte nicht aufgebaut werden:|r %s",
    ["|cffff5555This page could not be built. /reload, and report it if it persists.|r"] = "|cffff5555Diese Seite konnte nicht aufgebaut werden. /reload, und melde es bitte, falls es bleibt.|r",
    ["|cff888888%.2f ms/frame |cff666666(%.1f%% of ours, peak %.1f ms)|r|r"] = "|cff888888%.2f ms/Bild |cff666666(%.1f%% davon unsere, Spitze %.1f ms)|r|r",
    ["|cffaaaaaaThe header shows how much frame time VuloClassicUI costs. Your client measures this on its own, all the time — no setting and no reload needed.|r"] = "|cffaaaaaaDie Kopfzeile zeigt, wie viel Bildzeit VuloClassicUI kostet. Dein Client misst das von selbst, dauerhaft — ohne Einstellung und ohne Neuladen.|r",
    -- Patch notes 1.37.2
    ["Classic Era, Hardcore and Season of Discovery"] = "Classic Era, Hardcore und Season of Discovery",
    ["Under the hood"] = "Unter der Haube",
    ["The addon loads again without ticking \"Load out of date AddOns\". Blizzard's July interface update moved these realms to a new version number."] = "Das Addon lädt wieder ohne das Häkchen „Veraltete AddOns laden“. Blizzards Oberflächen-Update im Juli hat diese Realms auf eine neue Versionsnummer gehoben.",
    ["Fixed a crash that switched the whole Class Trainer page off on Season of Discovery: one ability the realm does not know took the entire module down with it."] = "Ein Absturz behoben, der in Season of Discovery die ganze Klassenlehrer-Seite abschaltete: eine einzige Fähigkeit, die der Realm nicht kennt, riss das komplette Modul mit.",
    ["The elite border on your player frame sits correctly again. It was placed against the old frame layout, which that same update replaced."] = "Der Elite-Rahmen am Spielerfenster sitzt wieder richtig. Er war an der alten Fensteraufteilung ausgerichtet, die dasselbe Update ersetzt hat.",
    ["Fixed a rare error storm at the end of a fight. Cleanup work in nineteen files could be skipped and the chat filled with error lines."] = "Einen seltenen Fehlerschwall am Kampfende behoben. Aufräumarbeiten in neunzehn Dateien konnten übersprungen werden und der Chat füllte sich mit Fehlerzeilen.",
    ["Combat log features (swing timer, cooldown pulse, combat text, arena tracker, nameplates, mana display) no longer depend on a setting a player can switch off."] = "Kampflog-Funktionen (Schlagtimer, Abklingpuls, Kampftexte, Arena-Verfolger, Namensplaketten, Manaanzeige) hängen nicht mehr an einer Einstellung, die man abschalten kann.",
    ["An interrupted enemy cast now really shows INTERRUPTED for a moment."] = "Ein unterbrochener gegnerischer Zauber zeigt die Unterbrechung jetzt wirklich einen Moment lang an.",
    ["Items that start a quest you have not accepted yet are marked with a yellow exclamation mark, in bags, bank and keyring."] = "Gegenstände, die eine noch nicht angenommene Quest starten, tragen jetzt ein gelbes Ausrufezeichen — in Taschen, Bank und Schlüsselbund.",
    ["Seven of the eight shipped translations no longer build their lookup table at all. Only the language you actually read is assembled, which frees about a megabyte on every login."] = "Sieben der acht mitgelieferten Übersetzungen bauen ihre Nachschlagetabelle gar nicht mehr auf. Nur die Sprache, die du wirklich liest, wird zusammengesetzt — das spart bei jedem Login rund ein Megabyte.",
    ["Edit Mode: three background drivers no longer run permanently, dragging a window allocates far less, and finding a window is a direct lookup instead of a search."] = "Bearbeitungsmodus: drei Hintergrund-Taktgeber laufen nicht mehr dauerhaft, das Ziehen eines Fensters erzeugt deutlich weniger Ballast, und ein Fenster wird direkt nachgeschlagen statt gesucht.",
    ["Disabling a module now detaches it completely — several used to leave listeners running for the rest of the session."] = "Ein abgeschaltetes Modul löst sich jetzt vollständig: mehrere ließen bisher Zuhörer für den Rest der Sitzung weiterlaufen.",
    ["The performance readout in the header uses your client's own always-on measurement, so it needs no setting and no reload."] = "Die Leistungsanzeige in der Kopfzeile nutzt die stets laufende Messung deines Clients und braucht daher weder Einstellung noch Neuladen.",
    -- Built-in profiler
    ["Nothing measured yet. Play for a bit, then read it again."] = "Noch nichts gemessen. Spiel eine Weile und lies es dann erneut aus.",
    ["Measured over %.1f s -- %.1f ms total, %.2f%% of it ours:"] = "Gemessen über %.1f s -- %.1f ms gesamt, davon %.2f%% unsere:",
    ["Measurement off."] = "Messung aus.",
    ["Measurement reset."] = "Messung zurückgesetzt.",
    ["Measurement on. Play, then type /vcuiprof again to read it."] = "Messung an. Spiel eine Weile und tippe dann erneut /vcuiprof.",
    -- Patch notes 1.37.3
    ["Class Trainer page"] = "Klassenlehrer-Seite",
    ["Fixed the page being thrown away again a moment after you opened it, dropping you back on a class tab. The spell book resets its own page whenever your spells change, and our page sits past the last real tab, so it was always the one discarded. Most noticeable on Season of Discovery, where engraving changes spells constantly."] = "Behoben, dass die Seite kurz nach dem Öffnen wieder verworfen wurde und dich auf einem Klassenreiter zurückließ. Das Zauberbuch setzt seine eigene Seite zurück, sobald sich deine Zauber ändern, und unsere sitzt hinter dem letzten echten Reiter — also traf es immer sie. Am deutlichsten in Season of Discovery, wo das Gravieren ständig Zauber ändert.",
    ["`/vcuiprof` measures how much frame time each part of the addon costs, then prints a list. It ships switched off and costs nothing while it is — the measuring code is only put in place when you turn it on. Type it once to start, once more to read."] = "`/vcuiprof` misst, wie viel Bildzeit jeder Teil des Addons kostet, und gibt eine Liste aus. Es wird ausgeschaltet ausgeliefert und kostet in diesem Zustand nichts — die messende Fassung wird erst beim Einschalten eingesetzt. Einmal tippen startet, ein zweites Mal liest aus.",
    -- Patch notes 1.37.4
    ["Clicking a trinket button while that trinket slot is empty no longer throws an error. The game's own shortcut for \"use the item in slot N\" stopped tolerating an empty slot with July's interface update, so the button now takes a different route to the same action."] = "Ein Klick auf einen Schmuck-Knopf mit leerem Schmuckplatz wirft keinen Fehler mehr. Die spieleigene Abkürzung für „benutze den Gegenstand in Platz N“ verträgt seit dem Oberflächen-Update im Juli keinen leeren Platz mehr, also nimmt der Knopf jetzt einen anderen Weg zur selben Handlung.",
    ["Fixed a stutter of almost two frames every time you entered or left combat, if you use WeakAuras and have the WeakAuras skin switched on. Every combat change repainted every aura you have ever saved — including the ones not on screen — with a look that had not changed. Auras are now only repainted when the settings or their size actually changed. Measured: 28 ms down to under 2 ms. The skin itself is unchanged."] = "Ein Stocken von fast zwei Bildern bei jedem Kampfbeginn und -ende behoben, wenn du WeakAuras nutzt und unseren WeakAuras-Anstrich anhast. Bei jedem Kampfwechsel wurde jede je gespeicherte Aura neu bemalt — auch die, die gar nicht auf dem Bildschirm ist — mit einem Aussehen, das sich nicht geändert hatte. Auren werden jetzt nur noch neu bemalt, wenn sich Einstellungen oder Größe wirklich geändert haben. Gemessen: 28 ms auf unter 2 ms. Der Anstrich selbst bleibt gleich.",
    -- Patch notes 1.39.0
    ["Download"] = "Download",
    ["Diminishing Returns Position – Put the DR row on either side of the frame, with its own X and Y offset"] = "Position der Verkettungsanzeige – Legt die Reihe auf eine der beiden Rahmenseiten, mit eigenem Versatz X und Y",
    ["The DR row no longer lands on top of the trinket or racial icon. It used to hang at a fixed distance on the right edge, exactly where the side icon sits, so switching it on stacked the two. The new default clears it, and on the left edge the row grows outward instead of across the frame."] = "Die Reihe der Verkettungsanzeige landet nicht mehr auf dem Schmuck- oder Volksfähigkeitssymbol. Sie hing in festem Abstand an der rechten Kante, genau dort, wo das Seitensymbol sitzt, sodass sich beide beim Einschalten überlagerten. Der neue Standard räumt daran vorbei, und an der linken Kante wächst die Reihe nach außen statt quer über den Rahmen.",
    ["The trinket and racial icons sit further out from the enemy frame and are a little smaller, so the health and mana bars read as the middle of the frame instead of competing with an icon at each shoulder. Both are sliders, so your own values are kept."] = "Die Symbole für Schmuckstück und Volksfähigkeit sitzen weiter vom Gegnerrahmen entfernt und sind etwas kleiner, sodass sich Lebens- und Manaleiste als Mitte des Rahmens lesen, statt gegen ein Symbol an jeder Schulter anzutreten. Beides sind Regler, deine eigenen Werte bleiben also erhalten.",
    ["The addon folder no longer ships build tools and source files that no player needs. The licence files stay where they are."] = "Der Addon-Ordner liefert keine Bauwerkzeuge und Quelldateien mehr mit, die kein Spieler braucht. Die Lizenzdateien bleiben, wo sie sind.",
    ["The release notes on the distribution pages are written in English now."] = "Die Versionshinweise auf den Verteilseiten sind jetzt auf Englisch geschrieben.",
    ["Six languages were missing seven texts that existed in German only. All nine are complete again."] = "Sechs Sprachen fehlten sieben Texte, die es nur auf Deutsch gab. Alle neun sind wieder vollständig.",
    ["The keyword help for the item search was misleading in Chinese: it gave an English type name as the example, which a Chinese client would never have matched. The example is written in the reader's own language now."] = "Die Stichwort-Hilfe der Gegenstandssuche war auf Chinesisch irreführend: Sie nannte als Beispiel einen englischen Typnamen, den ein chinesischer Client nie gefunden hätte. Das Beispiel steht jetzt in der Sprache des Lesers.",
    ["Seal Twist Helper – A swing bar with the twist window marked, plus the next sensible action"] = "Siegelwechsel-Hilfe – Eine Schwungleiste mit markiertem Wechselfenster und der nächsten sinnvollen Aktion",
    ["The bar counts down to your next auto attack with two marks: green is the last moment the second seal can still land, purple is how long a Judgement still fits in front of it. The next action is worked out live from your swing timer, the global cooldown and the seals actually on you — not from a fixed rotation. Crusader Strike is only suggested while there is room for it and the holding seal afterwards. Judgement deliberately gets none: it consumes the seal, and a wrong hint costs more there than no hint. Off by default."] = "Die Leiste zählt bis zu deinem nächsten Autoangriff herunter, mit zwei Marken: Grün ist der letzte Moment, in dem das zweite Siegel noch landen kann, Lila zeigt, wie lange ein Richturteil noch davorpasst. Die nächste Aktion wird live aus deinem Schwungtakt, der globalen Abklingzeit und den tatsächlich anliegenden Siegeln berechnet — nicht aus einem festen Rotationsmuster. Der Kreuzfahrerstoß wird nur vorgeschlagen, solange davor noch Platz für ihn und das Halte-Siegel bleibt. Das Richturteil bekommt bewusst keinen: Es verbraucht das Siegel, und ein falscher Hinweis kostet dort mehr als gar keiner. Standardmäßig aus.",
    -- Sidebar groups (QoL split, 1.40.0)
    ["Bags & Items"] = "Taschen & Gegenstände",
    ["Chat & Social"] = "Chat & Soziales",
    ["Extras"] = "Kleinkram",
    ["Tools"] = "Werkzeuge",
    -- Overview page
    ["peak %.1f ms"] = "Spitze %.1f ms",
    ["%.2f ms"] = "%.2f ms",
    ["%.1f MB"] = "%.1f MB",
    ["%d KB"] = "%d KB",
    ["%d of %d"] = "%d von %d",
    ["moved"] = "verschoben",
    ["Modules"] = "Module",
    ["Frame time"] = "Bildzeit",
    ["Memory"] = "Speicher",
    ["Windows"] = "Fenster",
    ["%d modules are switched off."] = "%d Module sind ausgeschaltet.",
    ["The edit mode grid is switched on."] = "Das Raster im Bearbeitungsmodus ist eingeschaltet.",
    ["There are patch notes you have not read yet."] = "Es gibt Versionshinweise, die du noch nicht gelesen hast.",
    ["What would you like to change?"] = "Was möchtest du einstellen?",
    ["Worth knowing"] = "Wissenswert",
    ["Recently visited"] = "Zuletzt besucht",
    -- Talent overrides
    ["active"] = "aktiv",
    ["Talent Overrides"] = "Übersteuerungen je Talentwahl",
    ["Talent group %d"] = "Talentwahl %d",
    ["Record changes for this talent group"] = "Änderungen für diese Talentwahl mitschreiben",
    ["While this is on, every setting you change is remembered for this talent group and applied again whenever you switch back to it. Switch it off when you are done."] = "Solange das an ist, wird jede Einstellung, die du änderst, für diese Talentwahl gemerkt und wieder angewendet, sobald du zu ihr zurückwechselst. Schalte es aus, wenn du fertig bist.",
    ["Recording for %s"] = "Schreibt mit für %s",
    ["%d settings overridden"] = "%d Einstellungen übersteuert",
    ["Forget all overrides for this talent group"] = "Alle Übersteuerungen dieser Talentwahl vergessen",
    ["Overrides apply on their own when you switch talent groups. This client has no specialisations, so the dual talent system is the axis."] = "Übersteuerungen greifen von selbst, sobald du die Talentwahl wechselst. Dieser Client kennt keine Spezialisierungen, deshalb ist die duale Talentwahl die Achse.",
    -- Override groups
    ["Talent group %d (%s)"] = "Talentwahl %d (%s)",
    ["Name for the new group"] = "Name der neuen Gruppe",
    ["Editing as"] = "Bearbeiten als",
    ["Yourself"] = "Ich selbst",
    ["Manage groups..."] = "Gruppen verwalten...",
    ["Owns the current talent group"] = "Gilt für die aktuelle Talentwahl",
    ["Delete this group"] = "Diese Gruppe löschen",
    ["No groups yet."] = "Noch keine Gruppen.",
    -- Anchor points
    ["Centre"] = "Mitte",
    ["Thin outline"] = "Dünne Kontur",
    -- Patch notes 1.40.0
    ["Moved out of the sidebar into Global Settings, as its own tab beside Profiles. Your saved setups were kept."] = "Aus der Seitenleiste heraus in die Globalen Einstellungen umgezogen, als eigener Reiter neben den Profilen. Deine gespeicherten Belegungen sind erhalten.",
    ["They were stored once per class profile — seven copies of one macro library. Stored once now, which cut the settings file by a third. Identical copies are merged, ones that differ are kept side by side."] = "Sie lagen einmal je Klassenprofil — sieben Kopien derselben Makrobibliothek. Jetzt liegen sie einmal, was die Einstellungsdatei um ein Drittel verkleinert hat. Gleiche Kopien werden zusammengelegt, abweichende bleiben nebeneinander erhalten.",
    ["The chat window no longer jumps back the moment you open the edit mode. Switching layouts re-anchors every window the game knows about, including ones we place ourselves."] = "Das Chatfenster springt nicht mehr zurück, sobald du den Bearbeitungsmodus öffnest. Ein Layoutwechsel verankert jedes Fenster neu, das das Spiel kennt — auch die, die wir selbst setzen.",
    ["A dropdown with a long entry no longer wraps into the row below it."] = "Ein Klappmenü mit einem langen Eintrag bricht nicht mehr in die Zeile darunter.",
    ["The first page is a picture of your interface instead of a second sidebar: modules running, frame time and memory, windows you moved, pages you last visited."] = "Die erste Seite zeigt den Zustand deines Interface statt einer zweiten Seitenleiste: laufende Module, Bildzeit und Speicher, verschobene Fenster und die zuletzt besuchten Seiten.",
    ["Talent Overrides – Named groups hold their own value for individual settings and apply when you switch talent specs"] = "Talent-Übersteuerungen – Benannte Gruppen halten eigene Werte für einzelne Einstellungen und greifen beim Wechsel der Talentwahl",
    ["A group can also name a situation — raid, dungeon, arena, battleground, in a group, alone. Anything you change while a group is active is recorded into it, and every overridden row is marked."] = "Eine Gruppe darf zusätzlich eine Situation nennen — Schlachtzug, Instanz, Arena, Schlachtfeld, in einer Gruppe, allein. Alles, was du bei aktiver Gruppe änderst, wird darin mitgeschrieben, und jede übersteuerte Zeile ist markiert.",
    ["Sliders are one row like every other setting, their number can be typed into, and labels line up in a measured column across the page. A long translation no longer pushes a value box into the next column or a button off its card."] = "Regler sind jetzt eine Zeile wie jede andere Einstellung, ihre Zahl lässt sich eintippen, und die Beschriftungen fluchten in einer gemessenen Spalte über die ganze Seite. Eine lange Übersetzung schiebt keinen Wertblock mehr in die Nachbarspalte und keinen Knopf mehr über die Karte hinaus.",
    ["Every section starts closed, so a long page opens as a list of headings."] = "Jeder Abschnitt startet zugeklappt, sodass eine lange Seite als Liste von Überschriften aufgeht.",
    ["The automatic swap queue has controls again — order, delay and the stop marker, on the trinket page. They only ever existed in a window this addon hides."] = "Die automatische Tauschwarteschlange hat wieder eine Bedienung — Reihenfolge, Verzögerung und die Endmarke, auf der Schmuckseite. Sie lag bisher nur in einem Fenster, das dieses Addon versteckt.",
    ["Trinket icons show up again: on the buttons, on the queue marker, and on your worn trinkets right after login instead of only once you click them."] = "Die Schmucksymbole sind wieder da: auf den Knöpfen, auf der Warteschlangenmarke und auf deinen getragenen Schmuckstücken direkt nach dem Anmelden statt erst nach einem Klick.",
    -- Befehlsregistratur
    ["%s has no handler yet — this is a bug, please report it."] = "%s hat noch keine Behandlung — das ist ein Fehler, bitte melde ihn.",
    ["%s belongs to %s, which is switched off."] = "%s gehört zu %s, und das ist ausgeschaltet.",
    ["|cff9b6cffCommands|r — %d in total. Grey ones belong to a module that is switched off."] = "|cff9b6cffBefehle|r — %d insgesamt. Graue gehören zu einem ausgeschalteten Modul.",
    ["%s is also claimed by another addon (%s) — one of the two wins."] = "%s wird auch von einem anderen Addon beansprucht (%s) — eines von beiden gewinnt.",
    ["waiting for a swing"] = "warte auf einen Schlag",
    ["  -  lag %.0fms"] = "  -  Latenz %.0fms",
    ["|cffaaaaaaHold Seal of Command, then cast the second seal in the last fraction of a second before your auto-attack: that swing carries both. The bar counts down to the swing, the |cff33ff66green zone|r is the twist window and the |cffb388ffpurple mark|r is the last moment a cast of the held seal still fits in front of it. Below level 64 the second seal is Righteousness; Blood and the Martyr replace it from there.|r"] = "|cffaaaaaaHalte das Siegel des Befehls und wirke das zweite Siegel im letzten Sekundenbruchteil vor deinem Autoangriff: dieser Schlag trägt dann beide. Die Leiste zählt zum Schlag herunter, die |cff33ff66grüne Zone|r ist das Wechselfenster und die |cffb388fflila Marke|r der letzte Moment, in dem ein Wirkvorgang des gehaltenen Siegels noch davor passt. Unter Stufe 64 ist das zweite Siegel das der Rechtschaffenheit; ab dort lösen es Blut und Märtyrer ab.|r",
    ["|cffff8800No seal to twist out of. Only Seal of Command and Seal of Righteousness carry over to a swing after being replaced, so one of the two has to be learned.|r"] = "|cffff8800Kein Siegel zum Herauswechseln. Nur das Siegel des Befehls und das Siegel der Rechtschaffenheit wirken noch auf einen Schlag, nachdem sie ersetzt wurden — eines von beiden muss gelernt sein.|r",
    ["|cffff8800Only one seal learned. A second one is needed to twist into.|r"] = "|cffff8800Nur ein Siegel gelernt. Zum Wechseln wird ein zweites gebraucht.|r",
    ["|cffff8800The seal you hold cannot be twisted out of. Only Seal of Command and Seal of Righteousness carry over to the swing that replaces them.|r"] = "|cffff8800Aus dem Siegel, das du hältst, kann nicht gewechselt werden. Nur das Siegel des Befehls und das Siegel der Rechtschaffenheit wirken noch auf den Schlag, der sie ersetzt.|r",
    ["Only Seal of Command and Seal of Righteousness work here: they are the two whose effect still lands on the swing that replaces them."] = "Hier passen nur das Siegel des Befehls und das Siegel der Rechtschaffenheit: Sie sind die beiden, deren Wirkung noch auf dem Schlag landet, der sie ersetzt.",
    ["Compensate for latency"] = "Latenz ausgleichen",
    ["Opens the window earlier by one trip to the server, and closes it once the cast can no longer arrive before the swing. Uses your measured world latency, capped at 250 ms."] = "Öffnet das Fenster um einen Weg zum Server früher und schließt es, sobald der Wirkvorgang nicht mehr vor dem Schlag ankommen kann. Nutzt deine gemessene Weltlatenz, gedeckelt bei 250 ms.",
    ["Show out of combat"] = "Außerhalb des Kampfes zeigen",
    ["Normally the bar is only up in combat. Switch this on to keep it on screen, which is the easier way to practise the timing on a dummy."] = "Normalerweise steht die Leiste nur im Kampf. Schalte das ein, um sie dauerhaft zu sehen — der bequemere Weg, das Timing an einer Puppe zu üben.",
    -- Namensplaketten-Vorlage
    ["Nameplate settings replaced. Switch profile to get the old ones back."] = "Die Einstellungen der Namensplaketten wurden ersetzt. Ein Profilwechsel holt die alten zurück.",
    ["Overwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched."] = "Überschreibt die Namensplaketten-Einstellungen dieses Profils mit einem breiten, flachen, dunklen Aussehen. Andere Profile bleiben unberührt.",
    ["|cffaaaaaaOverwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched.|r"] = "|cffaaaaaaÜberschreibt die Namensplaketten-Einstellungen dieses Profils mit einem breiten, flachen, dunklen Aussehen. Andere Profile bleiben unberührt.|r",
    ["Apply the wide, flat look"] = "Breites, flaches Aussehen übernehmen",
} end)
